// ── Console safety shim para WebViews móviles sin consola ───────────
if (typeof console === 'undefined') window.console = {};
['log','warn','error','info','debug'].forEach(function(m){
  if (typeof console[m] !== 'function') console[m] = function(){};
});

// ── FIX C-2: Logger condicional ──────────────────────────────────────
// Activar en desarrollo con: window.__PALEOBOT_DEBUG = true (antes de cargar la página)
// En producción todos los .log y .warn quedan silenciados automáticamente.
/**
 * Logger condicional. Silencia logs en producción.
 * Activar con window.__PALEOBOT_DEBUG = true ANTES de cargar la página.
 * @namespace Logger
 */
const Logger = (() => {
  const DEBUG  = typeof window.__PALEOBOT_DEBUG !== 'undefined' && window.__PALEOBOT_DEBUG === true;
  const PREFIX = '[PaleoBot]';
  return {
    /** @param {...*} args - Solo visible si DEBUG=true */
    log:   (...args) => { if (DEBUG) console.log(PREFIX,   ...args); },
    /** @param {...*} args - Solo visible si DEBUG=true */
    warn:  (...args) => { if (DEBUG) console.warn(PREFIX,  ...args); },
    /** @param {...*} args - Errores SIEMPRE visibles (críticos) */
    error: (...args) => console.error(PREFIX, ...args),
    /** @returns {boolean} */
    isDebug: () => DEBUG,
  };
})();

// ── FIX A-5: SafeStorage — localStorage con degradación elegante ─────
// Falla silenciosamente en iOS Safari privado (QuotaExceededError con cuota 0)
// y en contextos con storage bloqueado. Usa memoria en sesión como fallback.
/**
 * Adaptador de almacenamiento con degradación elegante.
 * Usa localStorage cuando está disponible; memoria de sesión si no.
 * @namespace SafeStorage
 */
const SafeStorage = (() => {
  const _mem = new Map();
  let _available = false;

  // Verificar disponibilidad real (no sólo existencia del objeto)
  try {
    const _t = '__paleobot_storage_test__';
    localStorage.setItem(_t, '1');
    localStorage.removeItem(_t);
    _available = true;
  } catch (_) {
    Logger.warn('SafeStorage: localStorage no disponible — usando memoria de sesión.');
  }

  return {
    /**
     * Recupera un valor almacenado.
     * @param {string} key
     * @param {string|null} [fallback=null]
     * @returns {string|null}
     */
    get(key, fallback = null) {
      try {
        if (_available) {
          const v = localStorage.getItem(key);
          return v !== null ? v : fallback;
        }
        return _mem.has(key) ? _mem.get(key) : fallback;
      } catch (e) {
        Logger.warn('SafeStorage.get error:', e.message);
        return fallback;
      }
    },
    /**
     * Guarda un valor.
     * @param {string} key
     * @param {string} value
     */
    set(key, value) {
      try {
        if (_available) localStorage.setItem(key, value);
        else            _mem.set(key, value);
      } catch (e) {
        Logger.warn('SafeStorage.set error — usando memoria:', e.message);
        _mem.set(key, value);  // fallback a memoria incluso si localStorage falla en runtime
      }
    },
    /**
     * Elimina un valor.
     * @param {string} key
     */
    remove(key) {
      try {
        if (_available) localStorage.removeItem(key);
        else            _mem.delete(key);
      } catch (e) {
        Logger.warn('SafeStorage.remove error:', e.message);
      }
    },
    /** @returns {boolean} */
    isAvailable: () => _available,
  };
})();

// ════════════════════════════════════════════════════════════════════
// R69 — Estado visual de bajo riesgo mediante clases externas.
// ════════════════════════════════════════════════════════════════════
window.PaleoBotStyleState = Object.freeze({
  display(el, mode = '') {
    if (!el?.classList) return false;
    el.classList.remove('pb-r69-display-none','pb-r69-display-block','pb-r69-display-flex');
    if (mode === 'none') el.classList.add('pb-r69-display-none');
    else if (mode === 'block') el.classList.add('pb-r69-display-block');
    else if (mode === 'flex') el.classList.add('pb-r69-display-flex');
    return true;
  },
  opacityZero(el, on = true) {
    if (!el?.classList) return false;
    el.classList.toggle('pb-r69-opacity-zero', Boolean(on));
    return true;
  },
  token(el, className, on = true) {
    if (!el?.classList || !className) return false;
    el.classList.toggle(className, Boolean(on));
    return true;
  }
});

// ════════════════════════════════════════════════════════════════════
// R71 — Registro de estilos dinámicos mediante clases + CSSOM externo.
// El HTML generado usa data-pb-r71-style; el observador lo transforma
// en una clase de alta especificidad y elimina el atributo de transporte.
// ════════════════════════════════════════════════════════════════════
window.PaleoBotDynamicStyle = (() => {
  const ATTR = 'data-pb-r71-style';
  const LINK_ID = 'paleobot-r71-dynamic-style-registry';
  const PREFIX = 'pb-r71-dyn-';
  const cache = new Map();
  const assigned = new WeakMap();

  function hash32(text, seed) {
    let h = seed >>> 0;
    for (let i = 0; i < text.length; i += 1) {
      h ^= text.charCodeAt(i);
      h = Math.imul(h, 16777619) >>> 0;
    }
    return h.toString(16).padStart(8, '0');
  }

  function classNameFor(text) {
    return PREFIX + hash32(text, 2166136261) + hash32(text, 2246822519);
  }

  function safeDeclaration(text) {
    const value = String(text || '').trim();
    if (!value) return '';
    if (/[{}<>]/.test(value)) return '';
    if (/@import/i.test(value) || /url\s*\(/i.test(value)) return '';
    return value;
  }

  function stylesheet() {
    return document.getElementById(LINK_ID)?.sheet || null;
  }

  function classFor(styleText) {
    const declaration = safeDeclaration(styleText);
    if (!declaration) return '';
    if (cache.has(declaration)) return cache.get(declaration);

    const sheet = stylesheet();
    if (!sheet) return '';

    const className = classNameFor(declaration);
    const selector = `.${className}:not(#paleobot-r71-never-match)`;
    try {
      sheet.insertRule(`${selector}{${declaration}}`, sheet.cssRules.length);
      cache.set(declaration, className);
      return className;
    } catch (err) {
      window.__PALEOBOT_DEBUG && console.warn('[PaleoBot R71] regla dinámica rechazada', err);
      return '';
    }
  }

  function set(el, styleText, slot = 'default') {
    if (!el?.classList) return false;
    const key = String(slot || 'default');
    let slots = assigned.get(el);
    if (!slots) {
      slots = new Map();
      assigned.set(el, slots);
    }
    const previous = slots.get(key);
    const raw = String(styleText || '').trim();

    if (!raw) {
      if (previous) {
        el.classList.remove(previous);
        slots.delete(key);
      }
      return true;
    }

    const declaration = safeDeclaration(raw);
    if (!declaration) return false;

    const className = classFor(declaration);
    if (!className) return false;
    if (previous && previous !== className) el.classList.remove(previous);
    if (previous !== className) el.classList.add(className);
    slots.set(key, className);
    return true;
  }

  function apply(el) {
    if (!el?.getAttribute || !el?.classList) return false;
    const declaration = el.getAttribute(ATTR);
    if (declaration === null) return false;
    const ok = set(el, declaration, 'transport');
    if (!ok) return false;
    el.removeAttribute(ATTR);
    return true;
  }

  function scan(root = document) {
    if (!root?.querySelectorAll) return 0;
    let done = 0;
    if (root.nodeType === 1 && root.hasAttribute?.(ATTR) && apply(root)) done += 1;
    root.querySelectorAll(`[${ATTR}]`).forEach(el => { if (apply(el)) done += 1; });
    return done;
  }

  function observe() {
    if (typeof MutationObserver !== 'function') return null;
    const observer = new MutationObserver(records => {
      records.forEach(record => {
        record.addedNodes.forEach(node => {
          if (node?.nodeType === 1) scan(node);
        });
      });
    });
    observer.observe(document.documentElement, { childList:true, subtree:true });
    return observer;
  }

  const observer = observe();
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => scan(document), { once:true });
  } else {
    scan(document);
  }
  window.addEventListener('load', () => scan(document), { once:true });

  return Object.freeze({
    attribute: ATTR,
    classFor,
    set,
    apply,
    scan,
    observer
  });
})();


// R81 — propietario geométrico CSSOM acotado.
// Una regla por clave estable; los cambios de valor actualizan esa misma regla.
window.PaleoBotGeometryStyle = (() => {
  const LINK_ID = 'paleobot-r81-geometry-registry';
  const PREFIX = 'pb-r81-geom-';
  const ALLOWED = new Set(['left','right','top','bottom','width','height']);
  const rules = new Map();

  function hash32(text, seed) {
    let h = seed >>> 0;
    for (let i = 0; i < text.length; i += 1) {
      h ^= text.charCodeAt(i);
      h = Math.imul(h, 16777619) >>> 0;
    }
    return h.toString(16).padStart(8, '0');
  }

  function classForKey(key) {
    const text = String(key || '');
    return PREFIX + hash32(text, 2166136261) + hash32(text, 2246822519);
  }

  function stylesheet() {
    return document.getElementById(LINK_ID)?.sheet || null;
  }

  function safeValue(value) {
    const text = String(value ?? '').trim();
    if (!text) return '';
    if (text === 'auto') return text;
    return /^-?\d+(?:\.\d+)?(?:px|%)$/.test(text) ? text : '';
  }

  function ensureRule(key) {
    const stableKey = String(key || '').trim();
    if (!stableKey) return null;
    if (rules.has(stableKey)) return rules.get(stableKey);

    const sheet = stylesheet();
    if (!sheet) return null;
    const className = classForKey(stableKey);
    const selector = `.${className}:not(#paleobot-r81-never-match)`;
    try {
      const index = sheet.cssRules.length;
      sheet.insertRule(`${selector}{}`, index);
      const rule = sheet.cssRules[index];
      const record = { className, rule };
      rules.set(stableKey, record);
      return record;
    } catch (err) {
      window.__PALEOBOT_DEBUG && console.warn('[PaleoBot R81] regla geométrica rechazada', err);
      return null;
    }
  }

  function set(el, key, geometry) {
    if (!el?.classList || !geometry || typeof geometry !== 'object') return false;

    const validated = [];
    for (const [prop, raw] of Object.entries(geometry)) {
      if (!ALLOWED.has(prop)) return false;
      const value = safeValue(raw);
      if (!value) return false;
      validated.push([prop, value]);
    }
    if (!validated.length) return false;

    const record = ensureRule(key);
    if (!record?.rule?.style) return false;
    el.classList.add(record.className);
    validated.forEach(([prop, value]) => record.rule.style.setProperty(prop, value));
    return true;
  }

  function clear(el, key, properties = []) {
    const stableKey = String(key || '').trim();
    const record = rules.get(stableKey);
    if (!record?.rule?.style) return false;
    const list = Array.isArray(properties) && properties.length ? properties : [...ALLOWED];
    list.forEach(prop => {
      if (ALLOWED.has(prop)) record.rule.style.removeProperty(prop);
    });
    if (el?.classList) el.classList.remove(record.className);
    return true;
  }

  function stats() {
    return Object.freeze({ ruleCount: rules.size, keys: [...rules.keys()] });
  }

  return Object.freeze({ set, clear, stats });
})();

// ════════════════════════════════════════════════════════════════════
// QuizProgress — Progreso persistente del quiz (v29)
// Clave SafeStorage: 'paleobot_quiz_v29' con migración desde 'paleobot_quiz_v26'
// Schema: { classic:{ok,fail}, generative:{ok,fail},
//           bySpecies:{ id:{ok,fail,last} }, lastReset }
// ════════════════════════════════════════════════════════════════════
const QuizProgress = (() => {
  const STORAGE_KEY = 'paleobot_quiz_v29';
  const LEGACY_STORAGE_KEYS = ['paleobot_quiz_v26'];

  /** Carga el progreso desde SafeStorage o devuelve un objeto vacío. */
  function _load() {
    try {
      const current = SafeStorage.get(STORAGE_KEY, 'null');
      if (current && current !== 'null') return JSON.parse(current) || _empty();
      for (const key of LEGACY_STORAGE_KEYS) {
        const legacy = SafeStorage.get(key, 'null');
        if (legacy && legacy !== 'null') {
          const migrated = JSON.parse(legacy) || _empty();
          _save(migrated);
          return migrated;
        }
      }
      return _empty();
    } catch (_) { return _empty(); }
  }

  function _empty() {
    return {
      classic:    { ok: 0, fail: 0 },
      generative: { ok: 0, fail: 0 },
      bySpecies:  {},
      lastReset:  Date.now()
    };
  }

  function _save(data) {
    try { SafeStorage.set(STORAGE_KEY, JSON.stringify(data)); } catch(_) { /* recuperable: suprimido intencionalmente */ }
  }

  /**
   * Registra una respuesta del quiz.
   * @param {string} spId   - ID de la especie (ej: 'afarensis')
   * @param {boolean} ok    - true = correcta, false = incorrecta
   * @param {'classic'|'generative'} mode
   */
  function record(spId, ok, mode = 'classic') {
    const data = _load();
    // Contador global por modo
    if (data[mode]) {
      ok ? data[mode].ok++ : data[mode].fail++;
    }
    // Contador por especie
    if (spId) {
      if (!data.bySpecies[spId]) data.bySpecies[spId] = { ok: 0, fail: 0, last: 0 };
      ok ? data.bySpecies[spId].ok++ : data.bySpecies[spId].fail++;
      data.bySpecies[spId].last = Date.now();
    }
    _save(data);
  }

  /**
   * Devuelve las N especies con mayor tasa de error (mínimo 1 intento).
   * Útil para priorizar el repaso (repetición espaciada básica).
   * @param {number} n - Número de especies a devolver
   * @returns {{ spId: string, ok: number, fail: number, rate: number }[]}
   */
  function getWeakest(n = 3) {
    const data = _load();
    return Object.entries(data.bySpecies)
      .filter(([, v]) => (v.ok + v.fail) >= 1)
      .map(([spId, v]) => ({
        spId,
        ok:   v.ok,
        fail: v.fail,
        rate: v.fail / (v.ok + v.fail)   // proporción de fallos (0–1)
      }))
      .sort((a, b) => b.rate - a.rate || b.fail - a.fail)
      .slice(0, n);
  }

  /** Estadísticas globales. */
  function getStats() {
    const d = _load();
    const totalOk   = d.classic.ok   + d.generative.ok;
    const totalFail = d.classic.fail + d.generative.fail;
    const total     = totalOk + totalFail;
    return {
      total,
      ok:      totalOk,
      fail:    totalFail,
      pct:     total > 0 ? Math.round((totalOk / total) * 100) : null,
      classic: d.classic,
      gen:     d.generative,
      species: Object.keys(d.bySpecies).length,
      lastReset: d.lastReset
    };
  }

  /** Borra todo el historial. */
  function reset() {
    _save(_empty());
  }

  return { record, getWeakest, getStats, reset };
})();


// ── FIX A-8: _showConfirmDialog — diálogo de confirmación accesible ─────────
// Sustituye al confirm() nativo (bloqueante, no accesible, rechazado en WebViews).
// Inyecta un micro-modal accesible con role=alertdialog, focus-trap y retorno de foco.
// @param {string} title   - Texto principal de la pregunta
// @param {string} [desc]  - Descripción adicional opcional
// @param {Function} onOk  - Callback si el usuario acepta
(function() {
  const OVERLAY_ID = '__paleobot_confirm_overlay';

  function _showConfirmDialog(title, desc, onOk, okLabel) {
    // Evitar múltiples diálogos simultáneos
    let existing = document.getElementById(OVERLAY_ID);
    if (existing) existing.remove();

    const overlay = document.createElement('div');
    overlay.id = OVERLAY_ID;
    overlay.setAttribute('role', 'alertdialog');
    overlay.setAttribute('aria-modal', 'true');
    overlay.setAttribute('aria-labelledby', '__pb_cdlg_title');
    overlay.setAttribute('aria-describedby', desc ? '__pb_cdlg_desc' : '__pb_cdlg_title');
    overlay.classList.add('pb-r79-confirm-overlay');

    const box = document.createElement('div');
    box.classList.add('pb-r79-confirm-box');

    const h3 = document.createElement('h3');
    h3.id = '__pb_cdlg_title';
    h3.textContent = title;
    h3.classList.add('pb-r79-confirm-title');

    if (desc) {
      const p = document.createElement('p');
      p.id = '__pb_cdlg_desc';
      p.textContent = desc;
      p.classList.add('pb-r79-confirm-desc');
      box.appendChild(h3);
      box.appendChild(p);
    } else {
      h3.classList.add('pb-r79-confirm-title--solo');
      box.appendChild(h3);
    }

    const btnRow = document.createElement('div');
    btnRow.classList.add('pb-r79-confirm-actions');

    const btnCancel = document.createElement('button');
    btnCancel.textContent = 'Cancelar';
    btnCancel.classList.add('pb-r79-confirm-btn', 'pb-r79-confirm-btn--cancel');

    const btnOk = document.createElement('button');
    btnOk.textContent = okLabel || 'Reiniciar';
    btnOk.classList.add('pb-r79-confirm-btn', 'pb-r79-confirm-btn--danger');

    const _close = function() { overlay.remove(); };
    btnCancel.addEventListener('click', _close);
    btnOk.addEventListener('click', function() { _close(); if (typeof onOk === 'function') onOk(); });

    // Cerrar con Escape
    const _keydown = function(e) {
      if (e.key === 'Escape') { document.removeEventListener('keydown', _keydown); _close(); }
    };
    document.addEventListener('keydown', _keydown);
    overlay.addEventListener('click', function(e) { if (e.target === overlay) _close(); });

    btnRow.appendChild(btnCancel);
    btnRow.appendChild(btnOk);
    box.appendChild(btnRow);
    overlay.appendChild(box);
    document.body.appendChild(overlay);

    // Devolver foco al botón cancelar por defecto (más seguro)
    requestAnimationFrame(function() { btnCancel.focus(); });
  }

  // Exponer en scope global del script
  window._showConfirmDialog = _showConfirmDialog;
})();

// ── FIX C-1: sanitizeText — prevención de XSS ───────────────────────
// Sanitiza texto externo (respuestas de API, datos de red) antes de
// insertarlo en innerHTML. Usa textContent del DOM — no regex.
/**
 * Convierte texto plano en HTML seguro escapando caracteres especiales.
 * Úsalo SIEMPRE antes de interpolar en innerHTML texto de origen externo.
 * @param {string|null|undefined} str - Texto potencialmente peligroso
 * @returns {string} Texto con entidades HTML escapadas, seguro para innerHTML
 */
function sanitizeText(str) {
  if (str === null || str === undefined) return '';
  const div = document.createElement('div');
  div.textContent = String(str);   // el navegador escapa automáticamente
  return div.innerHTML;
}

// ── FIX C-3e: Focus Trap para modales y panel lateral ────────────────
// Cumple WCAG 2.1 §2.1.2 No Keyboard Trap (nivel A).
// El trap devuelve el foco al elemento disparador al cerrarse.
/**
 * Atrapa el foco dentro de un contenedor (modal / panel lateral).
 * @param {HTMLElement} container - Elemento contenedor
 * @param {HTMLElement|null} [returnTo=null] - Elemento que recupera el foco al cerrar
 * @returns {Function} Función que elimina el trap (llamar al cerrar)
 */
function createFocusTrap(container, returnTo = null) {
  const FOCUSABLE = [
    'a[href]',
    'button:not([disabled])',
    'input:not([disabled])',
    'select:not([disabled])',
    'textarea:not([disabled])',
    '[tabindex]:not([tabindex="-1"])',
  ].join(',');

  function getFocusable() {
    return Array.from(container.querySelectorAll(FOCUSABLE))
                .filter(el => !el.closest('[hidden]') && el.offsetParent !== null);
  }

  function handleKeydown(e) {
    if (e.key !== 'Tab') return;
    const focusable = getFocusable();
    if (!focusable.length) { e.preventDefault(); return; }
    const first = focusable[0];
    const last  = focusable[focusable.length - 1];
    if (e.shiftKey) {
      if (document.activeElement === first || document.activeElement === container) {
        e.preventDefault();
        last.focus();
      }
    } else {
      if (document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    }
  }

  // Mover foco al primer elemento focusable del contenedor
  requestAnimationFrame(() => {
    const focusable = getFocusable();
    if (focusable.length) focusable[0].focus();
  });

  container.addEventListener('keydown', handleKeydown);

  // Retorna función de limpieza
  return function removeTrap(options = {}) {
    container.removeEventListener('keydown', handleKeydown);
    if (!options.skipReturnFocus && returnTo?.isConnected && typeof returnTo.focus === 'function') {
      returnTo.focus();
    }
  };
}

// ── FIX M-10: Regex de glosario robusto con lookbehind Unicode ───────
/**
 * Construye una expresión regular de frontera de palabra compatible con
 * caracteres Unicode acentuados (falla con \b estándar).
 * @param {string} term - Término a buscar
 * @returns {RegExp}
 */
function buildGlossRegex(term) {
  // \\b no reconoce limites ante vocales acentuadas en todos los motores JS.
  // Lookbehind/lookahead con rango Latin Extended U+00C0-U+024F (FIX M-10).
  const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  try {
    return new RegExp(
      '(?<![\\w\u00C0-\u024F])(' + escaped + ')(?![\\w\u00C0-\u024F])',
      'gi'
    );
  } catch (_) {
    // Fallback: Safari < 16 no soporta lookbehind Unicode
    return new RegExp('\\b(' + escaped + ')\\b', 'gi');
  }
}

