document.addEventListener('keydown', function(e) {
  const presMapKeyTrigger = e.target.closest('[data-pres-map-expand]');
  if (presMapKeyTrigger && (e.key === 'Enter' || e.key === ' ')) {
    e.preventDefault();
    openPresMapModal();
    return;
  }

  const tabTrigger = e.target.closest('[data-tab]');
  if (!tabTrigger || (e.key !== 'Enter' && e.key !== ' ')) return;
  e.preventDefault();
  switchTab(tabTrigger.dataset.tab, tabTrigger);
});

