function isNoImageUrl(url) {
  return !url || /No_image_available/i.test(url);
}

function buildMediaPlaceholder(sp) {
  // Neutral card: a different taxon's fossil must never stand in for missing evidence.
  const name = String(sp?.nombre || 'Recurso visual'); /* R97: sin taxón no se rotula «Taxón sin nombre» */
  const escapeXml = value => String(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[ch]));
  const svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 430" role="img" aria-label="Imagen no disponible">' +
    '<rect width="720" height="430" fill="#f0eee9"/>' +
    '<rect x="28" y="28" width="664" height="374" rx="14" fill="#fff" stroke="#596778" stroke-width="2"/>' +
    '<text x="56" y="126" font-size="24" font-family="sans-serif" fill="#23384b">SIN IMAGEN VERIFICADA</text>' +
    '<text x="56" y="192" font-size="21" font-family="sans-serif" fill="#23384b" textLength="608" lengthAdjust="spacingAndGlyphs">' + escapeXml(name) + '</text>' +
    '<text x="56" y="326" font-size="17" font-family="sans-serif" fill="#44586b">Consulte la evidencia fósil y su procedencia en la ficha.</text></svg>';
  return 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent(svg);
}

function getCommonsSourceUrlFromImage(url) {
  if (!url || !/upload\.wikimedia\.org\/wikipedia\/commons/i.test(url)) return "";
  const clean = decodeURIComponent(url.split('?')[0]);
  const parts = clean.split('/');
  const thumbIndex = parts.indexOf('thumb');
  const fileName = thumbIndex >= 0 && parts.length > thumbIndex + 3
    ? parts[thumbIndex + 3]
    : parts.pop();
  if (!fileName) return "";
  return `https://commons.wikimedia.org/wiki/File:${encodeURIComponent(fileName).replace(/%20/g, '_')}`;
}

function buildImageThumbUrl(url, width = 240) {
  if (!url || !/upload\.wikimedia\.org\/wikipedia\/commons/i.test(url)) return url || "";
  const clean = url.split('?')[0];
  const parts = clean.split('/');
  const commonsIndex = parts.indexOf('commons');
  if (commonsIndex < 0) return url;

  /* R97: Wikimedia rechaza (HTTP 429) el enlace directo a miniaturas de tamaño no estándar.
     Pasos oficiales ($wgThumbnailSteps): 20, 40, 60, 120, 250, 330, 500, 960, 1280, 1920, 3840.
     800 no es un paso válido: se sustituye por 960. */
  const requestedWidth = Math.max(80, Math.min(960, Number(width) || 250));
  const safeWidth = ([120, 250, 330, 500, 960].find(w => w >= requestedWidth) || 960);
  const thumbIndex = parts.indexOf('thumb');
  if (thumbIndex >= 0 && parts.length > thumbIndex + 4) {
    const fileName = parts[thumbIndex + 3];
    return `https://commons.wikimedia.org/wiki/Special:Redirect/file/${fileName}?width=${safeWidth}`;
  }

  if (parts.length < commonsIndex + 4) return url;
  const fileName = parts.slice(commonsIndex + 3).join('/');
  if (!fileName) return url;
  return `https://commons.wikimedia.org/wiki/Special:Redirect/file/${fileName}?width=${safeWidth}`;
}

function getSpeciesMedia(sp) {
  const safeSp = sp || {};
  const safeName = safeSp.nombre || 'Taxón sin nombre';
  const override = MEDIA_OVERRIDES[safeSp.id] || {};
  const hasRealImage = !isNoImageUrl(safeSp.imagen);
  const url = override.url || (hasRealImage ? safeSp.imagen : buildMediaPlaceholder(safeSp));
  const thumbUrl = override.thumbUrl || buildImageThumbUrl(url, 240);
  const tipo = override.tipo || (hasRealImage ? "imagen de referencia" : "aviso de imagen no disponible");
  const titulo = override.titulo || (hasRealImage ? `Imagen de referencia de ${safeName}` : `Sin imagen verificada para ${safeName}`);
  const fuente = override.fuente || (hasRealImage ? "Wikimedia Commons / fuente externa enlazada" : "PaleoBot");
  const licencia = override.licencia || (hasRealImage ? "ver licencia en la fuente original" : "Tarjeta tipográfica del proyecto; sin fotografía de terceros");
  const nota = override.nota || (hasRealImage
    ? "Imagen representativa: puede ser fósil, molde, reconstrucción museística o fotografía de referencia según disponibilidad."
    : "No hay imagen fósil verificada. La tarjeta tipográfica no representa anatomía ni un espécimen.");
  return {
    url,
    thumbUrl,
    tipo,
    titulo,
    fuente,
    licencia,
    nota,
    sourceUrl: override.sourceUrl || getCommonsSourceUrlFromImage(url),
    commons: `https://commons.wikimedia.org/w/index.php?search=${encodeURIComponent(safeName + ' fossil')}&title=Special:MediaSearch&type=image`
  };
}

function getSpeciesImage(sp) {
  return getSpeciesMedia(sp).url;
}

function getSpeciesThumb(sp, width = 240) {
  const media = getSpeciesMedia(sp);
  return width === 240 ? media.thumbUrl : buildImageThumbUrl(media.url, width);
}

function getMediaLicenseProfile(media) {
  const safeMedia = media || {};
  const url = String(safeMedia.url || '');
  const sourceUrl = String(safeMedia.sourceUrl || '');
  const license = String(safeMedia.licencia || '').toLowerCase();
  const source = String(safeMedia.fuente || '').toLowerCase();
  const isPlaceholder = /^data:image\/svg/i.test(url) || isNoImageUrl(url);
  const isInstitutional = /institucional|verificar permisos|tokyo|university museum/.test(license + ' ' + source);
  const isOpen = /commons\.wikimedia\.org/.test(sourceUrl) && /(cc0|cc by|cc-by|dominio público|dominio publico|public domain)/.test(license);
  if (isPlaceholder) {
    return { level: 'provisional', label: 'Lámina provisional', title: 'No sustituye una imagen curada del material fósil.' };
  }
  if (isInstitutional && !isOpen) {
    return { level: 'caution', label: 'Fuente institucional: verificar reutilización', title: 'Imagen académicamente útil, pero con permisos de redistribución no equivalentes a Commons.' };
  }
  if (isOpen) {
    return { level: 'open', label: 'Imagen abierta trazable', title: 'Imagen con fuente y licencia abierta verificables.' };
  }
  return { level: 'caution', label: 'Licencia por revisar', title: 'La imagen tiene fuente, pero la licencia debe revisarse antes de redistribuir.' };
}

function auditSpeciesMedia() {
  const rows = DB.map(sp => {
    const media = getSpeciesMedia(sp);
    const licenseProfile = getMediaLicenseProfile(media);
    return {
      id: sp.id,
      nombre: sp.nombre,
      hasImage: !!media.url && !isNoImageUrl(media.url),
      hasThumb: !!media.thumbUrl && !isNoImageUrl(media.thumbUrl),
      hasSource: !!media.sourceUrl,
      isPlaceholder: /^data:image\/svg/i.test(media.url) || isNoImageUrl(media.url),
      licenseLevel: licenseProfile.level,
      licenseLabel: licenseProfile.label,
      source: media.fuente,
      license: media.licencia,
      url: media.url,
      thumbUrl: media.thumbUrl
    };
  });
  const issues = rows.filter(r => !r.hasImage || !r.hasThumb || !r.hasSource || r.isPlaceholder);
  const warnings = rows.filter(r => !issues.includes(r) && r.licenseLevel !== 'open');
  return {
    total: rows.length,
    ok: rows.length - issues.length,
    issues,
    warnings,
    rows
  };
}

function updateMediaAuditStatus() {
  const audit = auditSpeciesMedia();
  const stat = document.getElementById('headerStatMedia');
  if (stat) {
    stat.textContent = `${audit.ok}/${audit.total}`;
    const wrapper = stat.closest?.('.stat-item');
    if (wrapper) {
      wrapper.classList.toggle('media-warning', audit.warnings.length > 0 || audit.issues.length > 0);
      wrapper.setAttribute('title', audit.issues.length
        ? `${audit.issues.length} ficha(s) con incidencias de imagen`
        : audit.warnings.length
          ? `${audit.warnings.length} ficha(s) con imagen disponible, pero licencia o reutilización por revisar`
          : 'Todas las fichas tienen imagen, miniatura y licencia abierta asociada');
      const label = wrapper.querySelector('span');
      if (label) {
        const warningText = audit.warnings.length === 1 ? '1 alerta' : `${audit.warnings.length} alertas`;
        label.textContent = audit.warnings.length ? `Imágenes · ${warningText}` : 'Imágenes';
      }
    }
  }
  Logger.log(`MediaAudit: ${audit.ok}/${audit.total} imágenes listas. Incidencias: ${audit.issues.length}. Alertas: ${audit.warnings.length}.`);
  return audit;
}

function auditSpeciesDetailReadiness() {
  const required = ['id', 'nombre', 'anos', 'ubicacion', 'holo', 'datacion', 'dieta', 'herramientas'];
  const rows = DB.map(sp => {
    const expert = getSpeciesExpert(sp);
    const missing = required.filter(key => sp[key] === undefined || sp[key] === null || sp[key] === '');
    if (!expert.descripcion_tecnica && !sp.descripcion) missing.push('descripcion');
    if (!expert.referencias.length) missing.push('referencias');
    return { id: sp.id || '(sin-id)', nombre: sp.nombre || '(sin nombre)', missing };
  });
  const issues = rows.filter(row => row.missing.length);
  return {
    total: rows.length,
    ok: rows.length - issues.length,
    issues,
    rows
  };
}

function updateDetailAuditStatus() {
  const audit = auditSpeciesDetailReadiness();
  if (audit.issues.length) {
    Logger.warn('DetailAudit: fichas con datos incompletos', audit.issues);
  } else {
    Logger.log(`DetailAudit: ${audit.ok}/${audit.total} fichas listas para apertura.`);
  }
  return audit;
}

function getEvidenceProfile(sp) {
  const status = sp?.estado || 'sin_revision';
  if (status === 'revision') return { level: 'review', label: 'Revisión', title: 'Taxón o interpretación en revisión' };
  if (status === 'debatida') return { level: 'debated', label: 'Debate', title: 'Taxón debatido: conviene leer los argumentos' };

  const completeness = getFossilCompletenessProfile(sp);
  const known = Object.values(completeness).filter(Boolean).length;
  if (known >= 3) return { level: 'high', label: 'Alta', title: 'Registro relativamente informativo' };
  if (known === 2) return { level: 'medium', label: 'Media', title: 'Registro parcial, interpretación moderadamente cautelosa' };
  return { level: 'low', label: 'Baja', title: 'Registro fragmentario, interpretación con alta cautela' };
}

function renderEvidenceBadge(sp) {
  const evidence = getEvidenceProfile(sp);
  return `<span class="evidence-badge evidence-${escapeHtmlAttr(evidence.level)}" title="${escapeHtmlAttr(evidence.title)}">Evidencia ${escapeHtmlText(evidence.label)}</span>`;
}

function normalizeVisualUrl(url) {
  return String(url || '').trim().replace(/([?&])width=\d+/i, '$1').replace(/[?&]$/, '').toLowerCase();
}

function isUsableRealVisual(url) {
  const safeUrl = String(url || '').trim();
  if (!safeUrl || isNoImageUrl(safeUrl)) return false;
  if (/^data:image\/svg/i.test(safeUrl) || /\.svg($|[?#])/i.test(safeUrl)) return false;
  return /^https?:\/\//i.test(safeUrl);
}

function getVisualEvidencePrompt(item, sp) {
  if (item.role === 'map') {
    return `Identifica la región actual ${escapeHtmlText(sp.ubicacion || '')}. Este fondo no marca yacimientos ni demuestra la distribución del taxón.`;
  }
  if (/reconstru/i.test(item.kind + ' ' + item.title)) {
    return 'Distingue dato e interpretación: ¿qué parte procede del fósil y qué parte es reconstrucción visual?';
  }
  if (/cráneo|craneo|skull|mandíbula|mandibula|jaw|maxilla|diente|tooth|molar/i.test(item.title + ' ' + item.url)) {
    return 'Observa un rasgo concreto: dentición, mandíbula o bóveda craneal. ¿Qué inferencia permite y cuál no?';
  }
  return 'Describe primero lo visible y después formula una inferencia prudente basada en la evidencia.';
}

function buildVisualEvidenceItems(sp) {
  const media = getSpeciesMedia(sp);
  const seen = new Set();
  const items = [];
  const addItem = item => {
    if (!isUsableRealVisual(item.url)) return;
    const key = normalizeVisualUrl(item.url);
    if (seen.has(key)) return;
    seen.add(key);
    items.push(item);
  };

  addItem({
    role: 'primary',
    kind: media.tipo || 'imagen principal',
    title: media.titulo || `Imagen de ${sp.nombre}`,
    url: media.url,
    sourceUrl: media.sourceUrl || media.commons
  });

  // Secondary media require individual identity and rights review. The legacy
  // sp.imagen diverges from the curated preference in 34 of 50 records.

  addItem({
    role: 'map',
    kind: 'mapa regional actual',
    title: `Fondo de contexto actual: ${sp.ubicacion || sp.nombre}`,
    url: sp.mapa,
    sourceUrl: getCommonsSourceUrlFromImage(sp.mapa)
  });

  return items.slice(0, 3).map(item => ({
    ...item,
    prompt: getVisualEvidencePrompt(item, sp)
  }));
}

function renderVisualEvidenceGallery(sp) {
  const items = buildVisualEvidenceItems(sp);
  if (!items.length) return '';
  const cards = items.map(item => `
    <article class="visual-evidence-item">
      <img class="visual-evidence-img" data-visual-role="${escapeHtmlAttr(item.role)}" src="${escapeHtmlAttr(item.url)}" alt="${escapeHtmlAttr(item.title)}" data-lightbox-open data-image-error="media" loading="lazy" decoding="async" referrerpolicy="no-referrer">
      <div class="visual-evidence-body">
        <span class="visual-evidence-kind">${escapeHtmlText(item.kind)}</span>
        <p class="visual-evidence-title">${escapeHtmlText(item.title)}</p>
        <p class="visual-evidence-prompt">${item.prompt}</p>
        ${item.sourceUrl ? `<a class="visual-evidence-link" href="${escapeHtmlAttr(item.sourceUrl)}" target="_blank" rel="noopener">ver fuente</a>` : ''}
      </div>
    </article>
  `).join('');
  return `<section class="visual-evidence-gallery" aria-label="Galería de evidencia visual">
    <div class="visual-evidence-head">
      <div>
        <h4>Lectura visual de la evidencia</h4>
        <p>Observa la imagen fósil y distingue el fondo regional actual. El fondo no marca hallazgos ni delimita distribución fósil.</p>
      </div>
      <span class="visual-evidence-badge">${items.length} recursos</span>
    </div>
    <div class="visual-evidence-grid">${cards}</div>
  </section>`;
}

function renderSpeciesMediaFigure(sp) {
  const media = getSpeciesMedia(sp);
  const licenseProfile = getMediaLicenseProfile(media);
  return `<figure class="species-media-figure">
    <div class="species-media-frame">
      <img src="${escapeHtmlAttr(media.url)}" class="species-header-image" alt="${escapeHtmlAttr(media.titulo)}" data-lightbox-open data-image-error="media" loading="lazy" decoding="async" referrerpolicy="no-referrer">
      <span class="species-media-badge">${escapeHtmlAttr(media.tipo)}</span>
    </div>
    <figcaption class="species-media-caption">
      <strong>${escapeHtmlAttr(media.titulo)}</strong>
      <span>${escapeHtmlAttr(media.nota)}</span>
      <span class="species-media-quality ${escapeHtmlAttr(licenseProfile.level)}" title="${escapeHtmlAttr(licenseProfile.title)}">${escapeHtmlText(licenseProfile.label)}</span>
      <span class="species-media-meta">Fuente: ${escapeHtmlAttr(media.fuente)} · Licencia: ${escapeHtmlAttr(media.licencia)} ${media.sourceUrl ? `· <a class="species-media-link" href="${escapeHtmlAttr(media.sourceUrl)}" target="_blank" rel="noopener">ver fuente</a>` : ''} · <a class="species-media-link" href="${escapeHtmlAttr(media.commons)}" target="_blank" rel="noopener">buscar alternativa en Commons</a></span>
    </figcaption>
  </figure>`;
}

