// ════════════════════════════════════════════════════════════════════════
//  PALEOBOT — Módulos de Producción v1.0
//  Arquitectura: Namespace IIFE con seis módulos desacoplados
//  Cada módulo retorna un objeto con API pública explícita.
//  Ningún módulo accede al DOM directamente (excepto ExportManager.downloadFile).
// ════════════════════════════════════════════════════════════════════════
const PaleoBot = (() => {
  'use strict';

  // ── Constantes compartidas ──────────────────────────────────────────
  const REQUIRED_FIELDS  = ['id', 'clado', 'nombre', 'anos', 'ubicacion', 'holo', 'val_time'];
  const VALID_CLADOS     = new Set(['basal', 'australo', 'paran', 'homo']);
  const CC_MIN = 100, CC_MAX = 2000;
  const TIME_MIN = 0, TIME_MAX = 30; // Ma

  // ════════════════════════════════════════════════════════════════════
  // 1. DataStore — Repositorio validado con múltiples índices
  // ════════════════════════════════════════════════════════════════════
  const DataStore = (() => {
    let _db       = [];          // array canónico de todas las especies
    let _index    = {};          // {id: species}  — acceso O(1)
    let _byClado  = {};          // {clado: [species]}
    let _timeline = [];          // orden de fuente; no es una escala cronológica científica
    let _errors   = [];          // advertencias de validación

    /** Valida un registro de especie. Retorna array de mensajes de error. */
    function _validate(sp) {
      const errs = [];
      const tag  = `[${sp.id || '?'}]`;

      // Campos requeridos
      REQUIRED_FIELDS.forEach(f => {
        if (sp[f] === undefined || sp[f] === null || sp[f] === '') {
          errs.push(`${tag} Campo requerido ausente: ${f}`);
        }
      });

      // Clado válido
      if (sp.clado && !VALID_CLADOS.has(sp.clado)) {
        errs.push(`${tag} Clado inválido: "${sp.clado}". Válidos: ${[...VALID_CLADOS].join(', ')}`);
      }

      // val_time heredado: validación estructural únicamente; no se usa como evidencia científica
      if (sp.val_time !== undefined && sp.val_time !== null) {
        const vt = Number(sp.val_time);
        if (!Number.isFinite(vt) || vt < TIME_MIN || vt > TIME_MAX) {
          errs.push(`${tag} val_time fuera de rango [${TIME_MIN}–${TIME_MAX} Ma]: ${sp.val_time}`);
        }
      }

      // Capacidad craneal: null permitido (casos sin datos), pero si existe debe ser biológicamente plausible
      if (sp.cc !== null && sp.cc !== undefined) {
        const cc = Number(sp.cc);
        if (!Number.isFinite(cc) || cc < CC_MIN || cc > CC_MAX) {
          errs.push(`${tag} cc fuera de rango biológico [${CC_MIN}–${CC_MAX} cc]: ${sp.cc}`);
        }
      }

      return errs;
    }

    /**
     * Carga y valida el array de especies.
     * @param {Object[]} rawDB - Array literal de la base de datos.
     * @returns {{ count: number, errors: string[] }}
     */
    function load(rawDB) {
      _errors   = [];
      _db       = [];
      _index    = {};
      _byClado  = { basal: [], australo: [], paran: [], homo: [] };

      rawDB.forEach((sp, i) => {
        const errs = _validate(sp);
        if (errs.length) {
          _errors.push(...errs);
          errs.forEach(e => Logger.warn(`DataStore validación: ${e}`));
        }
        _db.push(sp);
        _index[sp.id] = sp;
        if (_byClado[sp.clado]) _byClado[sp.clado].push(sp);
      });

      _timeline = [..._db]; // A3-C4.3: source order only; val_time is not a scientific ordering key.

      Logger.log(`DataStore: ${_db.length} registros cargados. ${_errors.length} advertencia(s) de validación.`);
      return { count: _db.length, errors: _errors };
    }

    /** Estadísticas de la BD para diagnóstico y presentación. */
    function getStats() {
      const withCC  = _db.filter(s => s.cc != null).length;
      const withDOI = _db.filter(s => s.experto?.referencias?.some(r => r.d)).length;
      return {
        total   : _db.length,
        byClado : Object.fromEntries(Object.entries(_byClado).map(([k, v]) => [k, v.length])),
        withCC,
        withDOI,
        timeSpan: {
          status: 'NOT_ASSESSED',
          meaning: 'LEGACY_SCALAR_NOT_USED_FOR_GLOBAL_CHRONOLOGY'
        }
      };
    }

    return {
      load,
      getAll     : ()      => _db,
      getById    : (id)    => _index[id] || null,
      getByClado : (clado) => _byClado[clado] || [],
      getTimeline: ()      => _timeline,
      getErrors  : ()      => [..._errors],
      getStats,
    };
  })();


  // ════════════════════════════════════════════════════════════════════
  // 2. ComputedCache — Memoización de propiedades derivadas
  // ════════════════════════════════════════════════════════════════════
  const ComputedCache = (() => {
    const _cache = new Map();

    function _memo(key, fn) {
      if (_cache.has(key)) return _cache.get(key);
      const val = fn();
      _cache.set(key, val);
      return val;
    }

    /**
     * Fachada histórica de rango: delega el rótulo heredado a la política A3; no es evidencia científica.
     * Soporta: "3.2 Ma", "3.5–3.3 Ma", "700–200 Ka", "~20 Ma", "195 Ka"
     * @returns {{ start: number, end: number, unit: 'Ma'|'Ka' }}
     */
    function getTimeRange(sp) {
      return A3Temporal.legacyRange(sp);
    }

    /**
     * Percentil de CC (0–100) respecto al pool de especies con CC conocido.
     * @param {Object} sp - Especie a evaluar.
     * @param {Object[]} pool - Pool de referencia (normalmente todas las especies con CC).
     * @returns {number|null}
     */
    function getCCPercentile(sp, pool) {
      if (sp.cc == null) return null;
      const cacheKey = `pct:${sp.id}:${pool.map(s => s.id).join(',')}`;
      return _memo(cacheKey, () => {
        const sorted = pool.filter(s => s.cc != null).map(s => s.cc).sort((a, b) => a - b);
        if (!sorted.length) return null;
        const idx = sorted.findIndex(v => v >= sp.cc);
        return Math.round(((idx < 0 ? sorted.length : idx) / sorted.length) * 100);
      });
    }

    /**
     * Continentes en los que se han hallado restos de la especie.
     * @returns {string[]} Array de continentes canónicos.
     */
    function getContinents(sp) {
      return _memo(`cont:${sp.id}`, () => {
        if (sp.id === 'sapiens') return ['África', 'Europa', 'Asia', 'América'];
        const loc = (sp.ubicacion || '').toLowerCase()
          .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        const hits = [];
        if (/(africa|kenia|uganda|chad|etiopia|tanzania|sudafrica|zambia|marruecos)/.test(loc)) hits.push('África');
        if (/(europa|espana|italia|francia|alemania|grecia|caucaso)/.test(loc)) hits.push('Europa');
        if (/(asia|siberia|china|indonesia|filipinas|java|georgia)/.test(loc)) hits.push('Asia');
        if (/(america|nuevo mexico|yukon|idaho|chile|clovis|white sands|monte verde)/.test(loc)) hits.push('América');
        return hits.length ? [...new Set(hits)] : ['Desconocido'];
      });
    }

    /** Invalida toda la cache (útil si la BD se recarga). */
    function invalidate() { _cache.clear(); }

    return { getTimeRange, getCCPercentile, getContinents, invalidate };
  })();


  // ════════════════════════════════════════════════════════════════════
  // 3. SearchEngine — Búsqueda con scoring ponderado y debounce
  // ════════════════════════════════════════════════════════════════════
  const SearchEngine = (() => {
    const _resultCache  = new Map();
    let   _debounceTimer = null;

    /** Normaliza para comparación: minúsculas, sin acentos, sin puntuación. */
    function normalize(str) {
      return (str || '')
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-z0-9\s]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
    }

    /**
     * Puntúa una especie contra los términos de búsqueda.
     * Pesos: nombre×10, holotipo×6, ubicación×5, años×3, debate×2, descripción×1.
     * Tres niveles: exacto×3, prefijo×2, substring×1.
     */
    function _score(sp, terms) {
      const FIELDS = [
        { get: () => sp.nombre,                                   w: 10 },
        { get: () => sp.holo,                                     w: 6  },
        { get: () => sp.ubicacion,                                w: 5  },
        { get: () => A3Temporal.displayMetadata(sp).text,         w: 3  },
        { get: () => sp.experto?.debate || '',                    w: 2  },
        { get: () => sp.descripcion || sp.experto?.descripcion_tecnica || '', w: 1 },
      ];
      let score = 0;
      terms.forEach(term => {
        FIELDS.forEach(({ get, w }) => {
          const n = normalize(get());
          if (!n) return;
          if (n === term)              score += w * 3;
          else if (n.startsWith(term)) score += w * 2;
          else if (n.includes(term))   score += w;
        });
      });
      return score;
    }

    /**
     * Busca en el pool y retorna los resultados ordenados por relevancia.
     * Si query está vacío retorna el pool sin modificar.
     * @param {string} query
     * @param {Object[]} pool
     * @returns {Object[]}
     */
    function search(query, pool) {
      const poolKey = pool.map(s => s.id).join('|');
      const cacheKey = `${normalize(query)}||${poolKey}`;
      if (_resultCache.has(cacheKey)) return _resultCache.get(cacheKey);

      let result;
      if (!query.trim()) {
        result = pool;
      } else {
        const terms = normalize(query).split(' ').filter(Boolean);
        result = pool
          .map(sp => ({ sp, score: _score(sp, terms) }))
          .filter(({ score }) => score > 0)
          .sort((a, b) => b.score - a.score)
          .map(({ sp }) => sp);
      }

      _resultCache.set(cacheKey, result);
      return result;
    }

    /**
     * Versión con debounce — invoca callback tras `delay` ms sin nuevas llamadas.
     * @param {string} query
     * @param {Object[]} pool
     * @param {Function} callback - Recibe el array de resultados.
     * @param {number} [delay=280]
     */
    function debounced(query, pool, callback, delay = 280) {
      clearTimeout(_debounceTimer);
      _debounceTimer = setTimeout(() => callback(search(query, pool)), delay);
    }

    function clearCache() { _resultCache.clear(); }

    return { search, debounced, normalize, clearCache };
  })();


  // ════════════════════════════════════════════════════════════════════
  // 4. FilterPipeline — Filtros composables con cache
  // ════════════════════════════════════════════════════════════════════
  const FilterPipeline = (() => {
    const _filters    = new Map();   // name → (sp) => boolean
    let   _cacheKey   = '';
    let   _cached     = null;

    function _invalidate() { _cached = null; _cacheKey = ''; }

    /**
     * Registra o actualiza un filtro. fn=null lo elimina.
     * @param {string} name - Identificador del filtro.
     * @param {Function|null} fn - Predicado (sp) => boolean.
     */
    function setFilter(name, fn) {
      if (fn === null) _filters.delete(name);
      else { if (typeof fn !== 'function') throw new TypeError('Filter must be a function'); _filters.set(name, fn); }
      _invalidate();
    }

    function clearFilter(name) { setFilter(name, null); }
    function clearAll()        { _filters.clear(); _invalidate(); }

    /**
     * Aplica todos los filtros activos al pool. Usa cache si el pool y los filtros no cambiaron.
     * @param {Object[]} pool
     * @returns {Object[]}
     */
    function apply(pool) {
      if (!Array.isArray(pool)) throw new TypeError('FilterPipeline requires an array');
      const fns = [..._filters.values()];
      return pool.filter(sp => fns.every(fn => {
        const result = fn(sp);
        if (typeof result !== 'boolean') throw new TypeError('Filter predicate must return boolean');
        return result;
      }));
    }

    /** Fábrica de predicados reutilizables. */
    const Filters = {
      byClado     : (clado)         => (sp) => clado === 'all' || sp.clado === clado,
      hasCC       : ()              => (sp) => sp.cc != null,
      hasDOI      : ()              => (sp) => sp.experto?.referencias?.some(r => r.d),
      byEstado    : (estado)        => (sp) => (sp.estado || 'sin_revision') === estado,
      byContinent : (cont)          => (sp) => ComputedCache.getContinents(sp).includes(cont),
      byTimeRange : (minMa, maxMa)  => (sp) => A3Temporal.include(sp, minMa, maxMa),
    };

    return { setFilter, clearFilter, clearAll, apply, Filters };
  })();


  // ════════════════════════════════════════════════════════════════════
  // 5. ErrorBoundary — Decorador para funciones críticas de UI
  // ════════════════════════════════════════════════════════════════════
  const ErrorBoundary = (() => {
    const _log = [];

    function _record(context, err) {
      const entry = { ts: Date.now(), context, message: err.message, stack: err.stack };
      _log.push(entry);
      Logger.error(`ErrorBoundary [${context}]:`, err);
      return entry;
    }

    function _renderFallback(containerId, context) {
      const el = containerId ? document.getElementById(containerId) : null;
      if (el) {
        el.innerHTML = `<div class="render-error">
          <span class="ico" aria-hidden="true"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg></span>
          <div>
            <strong>Error al renderizar "${context}".</strong><br>
            El resto de la aplicación sigue operativa.
            <button type="button" class="render-error-action" data-reload-page>Recargar</button>
          </div>
        </div>`;
      }
    }

    /**
     * Envuelve una función síncrona con manejo de errores.
     * @param {Function} fn - Función a proteger.
     * @param {string} context - Nombre descriptivo (ej: 'renderTimeline').
     * @param {*} [fallback=null] - Valor de retorno en caso de error.
     *   Si es un string, se interpreta como el id de un contenedor DOM donde mostrar el error.
     * @returns {Function}
     */
    function wrap(fn, context = 'unknown', fallback = null) {
      return (...args) => {
        try {
          return fn(...args);
        } catch (err) {
          _record(context, err);
          if (typeof fallback === 'string') _renderFallback(fallback, context);
          return typeof fallback === 'string' ? null : (typeof fallback === 'function' ? fallback(err, ...args) : fallback);
        }
      };
    }

    /**
     * Versión para funciones async.
     */
    function wrapAsync(fn, context = 'unknown') {
      return async (...args) => {
        try   { return await fn(...args); }
        catch (err) { _record(context, err); return null; }
      };
    }

    return {
      wrap,
      wrapAsync,
      getLog    : () => [..._log],
      hasErrors : () => _log.length > 0,
      clearLog  : () => _log.splice(0),
    };
  })();


  // ════════════════════════════════════════════════════════════════════
  // 6. ExportManager — Exportación segura de datos y bibliografía
  // ════════════════════════════════════════════════════════════════════
  const ExportManager = (() => {
    // Expansión de abreviaturas de revistas para APA 7
    const JOURNAL_FULL = {
      'Nature'             : 'Nature',
      'Science'            : 'Science',
      'PNAS'               : 'Proceedings of the National Academy of Sciences',
      'J Hum Evol'         : 'Journal of Human Evolution',
      'Am J Phys Anthropol': 'American Journal of Physical Anthropology',
      'PLoS One'           : 'PLOS ONE',
      'PLoS ONE'           : 'PLOS ONE',
      'Sci Adv'            : 'Science Advances',
      'Curr Biol'          : 'Current Biology',
      'CRAS'               : 'Comptes Rendus de l\'Académie des Sciences',
      'Evol Anthropol'     : 'Evolutionary Anthropology',
    };

    /** Formatea una referencia en APA 7. */
    function formatAPA(ref) {
      if (!ref || typeof ref !== 'object') return '';
      const journal = JOURNAL_FULL[ref.j] || ref.j || '';
      const doi     = ref.d ? ` https://doi.org/${ref.d}` : '';
      return `${ref.a || ''} (${ref.y || 's.f.'}). ${ref.t || ''}. ${journal}.${doi}`;
    }

    /**
     * Convierte un array de especies a CSV (RFC 4180).
     * Tolerante a campos ausentes o nulos.
     * @param {Object[]} species
     * @param {string[]} [fields] - Columnas a incluir.
     * @returns {string}
     */
    function toCSV(species, fields) {
      const escapeCell = v => {
        const s = (v === null || v === undefined) ? '' : String(v);
        return (s.includes(',') || s.includes('"') || s.includes('\n') || s.includes('\r'))
          ? `"${s.replace(/"/g, '""')}"` : s;
      };
      if (fields) {
        const header = fields.join(',');
        const rows = species.map(sp => fields.map(f => escapeCell(sp[f])).join(','));
        return [header, ...rows].join('\r\n');
      }
      const COLS=['id','clado','nombre','cronologia','cronologia_estado','cronologia_tipo','cronologia_geometria_json','legacy_anos','legacy_val_time_Ma','ubicacion','material_localidad_sin_tipo_verificado','datacion','cc','dieta','herramientas','estado'];
      const rows=species.map(sp=>{
        const c=A3Temporal.exportChronology(sp);
        const row={id:sp.id,clado:sp.clado,nombre:sp.nombre,cronologia:c.texto,cronologia_estado:c.source_status,cronologia_tipo:c.kind,cronologia_geometria_json:JSON.stringify(c.geometry),legacy_anos:c.legacy_text,legacy_val_time_Ma:c.legacy_val_time_Ma,ubicacion:sp.ubicacion,material_localidad_sin_tipo_verificado:sp.holo,datacion:sp.datacion,cc:sp.cc,dieta:sp.dieta,herramientas:sp.herramientas,estado:sp.estado};
        return COLS.map(f=>escapeCell(row[f])).join(',');
      });
      return [COLS.join(','),...rows].join('\r\n');
    }

    /**
     * Convierte un array de especies a JSON estructurado canónico.
     * @param {Object[]} species
     * @returns {string}
     */
    function toJSON(species) {
      const canonical = species.map(sp => ({
        id               : sp.id,
        clado            : sp.clado,
        nombre           : sp.nombre,
        cronologia       : A3Temporal.exportChronology(sp),
        ubicacion        : sp.ubicacion || '',
        material_localidad_sin_tipo_verificado : sp.holo || '',
        metodo_datacion  : sp.datacion || '',
        cc_cc            : sp.cc ?? null,
        dieta            : sp.dieta || '',
        cultura_material : sp.herramientas || '',
        estado_taxonomico: sp.estado || 'sin_revision',
        referencias      : (sp.experto?.referencias || []).map(r => ({
          autores: r.a || '', año: r.y || '', titulo: r.t || '',
          revista: r.j || '', doi: r.d || ''
        }))
      }));
      return JSON.stringify(canonical, null, 2);
    }

    function safeFilename(filename, fallback = 'paleobot_export.txt') {
      const raw = String(filename || fallback).trim() || fallback;
      return raw
        .replace(/[<>:"/\\|?*\u0000-\u001F]/g, '_')
        .replace(/\s+/g, ' ')
        .slice(0, 120);
    }

    /**
     * Descarga un archivo en el navegador del usuario.
     * Libera el Object URL a los 5 segundos para evitar memory leaks.
     * @returns {boolean} true si se pudo disparar la descarga.
     */
    function downloadFile(content, filename, mimeType) {
      let url = null;
      try {
        if (content == null) throw new Error('Contenido vacío');
        const blob = new Blob([content], { type: mimeType });
        url  = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = safeFilename(filename);
        window.PaleoBotStyleState.display(a, 'none');
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        setTimeout(() => { if (url) URL.revokeObjectURL(url); }, 5000);
        return true;
      } catch (err) {
        if (url) URL.revokeObjectURL(url);
        Logger.error('ExportManager — error al descargar:', err);
        alert('No se pudo generar el archivo. Comprueba los permisos del navegador.');
        return false;
      }
    }

    /**
     * Exporta el array de especies como CSV y lo descarga.
     */
    function exportCSV(species, filename = 'paleobot_export.csv') {
      if (!species?.length) { alert('No hay datos visibles para exportar.'); return; }
      downloadFile(toCSV(species), filename, 'text/csv;charset=utf-8;');
    }

    /**
     * Exporta el array de especies como JSON estructurado y lo descarga.
     */
    function exportJSON(species, filename = 'paleobot_export.json') {
      if (!species?.length) { alert('No hay datos visibles para exportar.'); return; }
      downloadFile(toJSON(species), filename, 'application/json;charset=utf-8;');
    }

    /**
     * Copia la bibliografía de una especie al portapapeles en formato APA 7.
     * Fallback sin Clipboard API: selección temporal de textarea.
     * @param {Object} sp - Especie (necesita sp.experto.referencias).
     * @param {'apa'|'chicago'} [format='apa']
     */
    function copyBibliography(sp, format = 'apa') {
      const refs = sp?.experto?.referencias;
      if (!refs?.length) {
        alert('Esta especie no tiene referencias registradas.');
        return;
      }

      const text = format === 'apa'
        ? refs.map(formatAPA).join('\n\n')
        : refs.map(r => `${r.a || ''} (${r.y || 's.f.'}). "${r.t || ''}." ${r.j || ''}.${r.d ? ' DOI: ' + r.d : ''}`).join('\n\n');

      const onSuccess = () => {
        // Feedback visual mínimo — no bloquea con alert
        const flash = document.createElement('div');
        flash.textContent = `✅ ${refs.length} referencia(s) copiadas (${format.toUpperCase()})`;
        flash.classList.add('pb-r78-copy-flash');
        document.body.appendChild(flash);
        setTimeout(() => {
          flash.classList.add('pb-r78-copy-flash--out');
          setTimeout(() => flash.remove(), 400);
        }, 2200);
      };

      if (navigator.clipboard?.writeText) {
        navigator.clipboard.writeText(text).then(onSuccess).catch(() => _fallbackCopy(text, onSuccess));
      } else {
        _fallbackCopy(text, onSuccess);
      }
    }

    function _fallbackCopy(text, onSuccess) {
      const ta = Object.assign(document.createElement('textarea'), { value: text });
      ta.classList.add('pb-r79-copy-textarea');
      document.body.appendChild(ta);
      ta.focus(); ta.select();
      try { document.execCommand('copy'); onSuccess(); } catch(e) { alert('No se pudo acceder al portapapeles.'); }
      document.body.removeChild(ta);
    }

    return {
      exportCSV,
      exportJSON,
      copyBibliography,
      formatAPA,
      toCSV,
      toJSON,
      downloadFile,
    };
  })();


  // ════════════════════════════════════════════════════════════════════
  // API pública del namespace
  // ════════════════════════════════════════════════════════════════════
  return {
    DataStore,
    ComputedCache,
    SearchEngine,
    FilterPipeline,
    ErrorBoundary,
    ExportManager,
    version: '29.0.0',

    /**
     * Punto de entrada único. Llama a esto después de definir DB[].
     * @param {Object[]} rawDB
     * @returns {{ count: number, errors: string[] }}
     */
    init(rawDB) {
      const t0 = performance.now();
      const result = DataStore.load(rawDB);
      FilterPipeline.setFilter('clado', FilterPipeline.Filters.byClado('all'));
      Logger.log(`PaleoBot v${this.version} inicializado en ${(performance.now() - t0).toFixed(1)}ms`);
      return result;
    }
  };
})();


