/**
 * Rango temporal en Ma. Delegado a ComputedCache para memoización automática.
 * Misma API pública que la versión anterior.
 */
function getSpeciesTimeRange(sp) {
  return PaleoBot.ComputedCache.getTimeRange(sp);
}

function formatTimePoint(ma) {
  const value = Number(ma);
  if (value === 0) return 'Hoy';
  if (value < 1) return `${Math.round(value * 1000)} ka`;
  return `${Number.isInteger(value) ? value.toFixed(0) : value.toFixed(2).replace(/0+$/,'').replace(/\.$/,'')} Ma`;
}

function speciesInTimeFilter(sp) {
  return A3Temporal.include(sp, timeFilter.young, timeFilter.old);
}

function updateTimeFilterUI() {
  const oldInput = document.getElementById('timeRangeOld');
  const youngInput = document.getElementById('timeRangeYoung');
  const fill = document.getElementById('timeSliderFill');
  const readout = document.getElementById('timeFilterReadout');
  if (oldInput) oldInput.value = String(timeFilter.old);
  if (youngInput) youngInput.value = String(timeFilter.young);
  if (fill) {
    window.PaleoBotGeometryStyle.set(fill, 'time-filter-fill', {
      left: `${(timeFilter.young / 23) * 100}%`,
      right: `${100 - (timeFilter.old / 23) * 100}%`
    });
  }
  if (readout) {
    readout.textContent = timeFilter.old === timeFilter.young
      ? `Instantánea: ${formatTimePoint(timeFilter.old)}`
      : `${formatTimePoint(timeFilter.young)} – ${formatTimePoint(timeFilter.old)}`;
  }
  const notice = document.getElementById('a3TimeEvidenceNotice');
  if (notice) {
    const result = A3Temporal.filterRows(DB, timeFilter.young, timeFilter.old);
    notice.textContent = `${result.counts.possible} registros con soporte temporal compatible; ${result.counts.no_reported_overlap} sin solapamiento en las ventanas documentadas; ${result.counts.indeterminate} indeterminados. Los resultados no prueban presencia ni ausencia histórica.`;
  }
  document.querySelectorAll('.time-chip-btn').forEach(btn => btn.classList.remove('active'));
}

/**
 * Actualiza el filtro temporal desde los sliders de rango.
 * Sincroniza valores y atributos ARIA (FIX C-3a — WCAG 2.1 §4.1.2).
 * @param {'old'|'young'} changed - Qué slider se modificó
 */
function setTimeRangeFromInputs(changed) {
  const oldInput   = document.getElementById('timeRangeOld');
  const youngInput = document.getElementById('timeRangeYoung');
  if (!oldInput || !youngInput) return;

  let oldVal   = parseFloat(oldInput.value);
  let youngVal = parseFloat(youngInput.value);

  // Garantizar que el límite antiguo >= límite reciente
  if (changed === 'old'   && oldVal   < youngVal) youngVal = oldVal;
  if (changed === 'young' && youngVal > oldVal)   oldVal   = youngVal;

  // Sincronizar los valores de los inputs si se corrigieron
  oldInput.value   = oldVal;
  youngInput.value = youngVal;

  // FIX C-3a: actualizar atributos ARIA en tiempo real para lectores de pantalla
  oldInput.setAttribute('aria-valuenow',   oldVal.toFixed(1));
  oldInput.setAttribute('aria-valuetext',  oldVal.toFixed(1) + ' Ma');
  youngInput.setAttribute('aria-valuenow',  youngVal.toFixed(1));
  youngInput.setAttribute('aria-valuetext', youngVal.toFixed(1) + ' Ma');

  timeFilter = { old: +oldVal.toFixed(2), young: +youngVal.toFixed(2) };
  updateTimeFilterUI();
  applyFilters();
}

function setTimePreset(oldMa, youngMa) {
  timeFilter = {
    old: Math.max(oldMa, youngMa),
    young: Math.min(oldMa, youngMa)
  };
  updateTimeFilterUI();
  applyFilters();
}

/**
 * Determina si una especie pasa los filtros activos.
 * Usa SearchEngine para scoring multi-campo (antes era solo substring en 6 campos).
 * Retrocompatible: sigue siendo llamable con un solo argumento.
 */
function matchesActiveFilters(sp) {
  const term = document.getElementById('searchInput')?.value || '';
  const matchClado  = cladoFilter === 'all' || sp.clado === cladoFilter;
  if (!matchClado) return false;
  if (!speciesInTimeFilter(sp)) return false;
  if (!term.trim()) return true;
  // SearchEngine.search devuelve array ordenado por score; score>0 = match
  const results = PaleoBot.SearchEngine.search(term, [sp]);
  return results.length > 0;
}

function getSpeciesContinents(sp) {
  if (CONTINENT_OVERRIDES[sp.id]) return CONTINENT_OVERRIDES[sp.id];
  const loc = normalizeForSearch(sp.ubicacion || '');
  const hits = [];
  if (/(africa|kenia|uganda|chad|etiopia|tanzania|sudafrica|zambia|marruecos)/.test(loc)) hits.push('africa');
  if (/(europa|espana|italia|francia|alemania|georgia|grecia|caucaso)/.test(loc)) hits.push('europe');
  if (/(asia|siberia|china|indonesia|filipinas|java|sudeste asiat|caucaso)/.test(loc)) hits.push('asia');
  if (!hits.length && sp.id === 'sapiens') hits.push('africa', 'europe', 'asia');
  return [...new Set(hits)];
}

// A3-C4.2: safe presentation of scientific evidence. Coordinates are SVG-only.
function a3C42Rows(pool) { return A3Temporal.chronologicalRows(pool); }
function a3C42Summary(pool) {
  const s = A3Temporal.presentationSummary(pool);
  return `${s.reviewed} cronologías revisadas · ${s.legacy_unreviewed} referencias heredadas sin revisión · No se infiere duración ni presencia`;
}
function a3C42Label(sp) {
  const p=A3Temporal.presentation(sp);
  return p.label + (p.reviewed ? ' [A2 revisada]' : ' [R92 sin revisión cronológica]');
}
function a3C42Glyph(sp,{width=640,height=38,maxMa=23.5}={}) {
  const p=A3Temporal.presentation(sp),y=height/2;
  const x=ma=>12+(maxMa-Math.max(0,Math.min(maxMa,ma)))/maxMa*(width-24);
  const safe=escapeHtmlText(p.label);
  const lines=[];
  for(const g of p.geometry){
    if(g.kind==='reported_window'){
      const a=x(g.old_ma),b=x(g.young_ma);
      lines.push(`<line x1="${a}" y1="${y}" x2="${b}" y2="${y}" stroke="#1d4ed8" stroke-width="5" stroke-linecap="round"/><circle cx="${a}" cy="${y}" r="3" fill="#1d4ed8"/><circle cx="${b}" cy="${y}" r="3" fill="#1d4ed8"/>`);
    } else if(g.kind==='point'){
      const px=x(g.ma);
      if(Number.isFinite(g.uncertainty_ka)){
        const left=x(g.ma+g.uncertainty_ka/1000),right=x(Math.max(0,g.ma-g.uncertainty_ka/1000));
        lines.push(`<line x1="${left}" y1="${y}" x2="${right}" y2="${y}" stroke="#64748b" stroke-width="2"/><line x1="${left}" y1="${y-5}" x2="${left}" y2="${y+5}" stroke="#64748b"/><line x1="${right}" y1="${y-5}" x2="${right}" y2="${y+5}" stroke="#64748b"/>`);
      }
      lines.push(`<circle cx="${px}" cy="${y}" r="5" fill="#1d4ed8" stroke="white" stroke-width="1.5"/>`);
    } else if(g.kind==='minimum_age'||g.kind==='maximum_age'){
      const px=x(g.ma),older=g.kind==='minimum_age';
      lines.push(`<circle cx="${px}" cy="${y}" r="5" fill="white" stroke="#1d4ed8" stroke-width="2"/><path d="M${px+(older?-10:10)},${y} l${older?6:-6},-4 m${older?-6:6},4 l${older?6:-6},4" stroke="#1d4ed8" stroke-width="1.5" fill="none"/>`);
    }
  }
  if(!lines.length)return `<span class="a3-c42-unreviewed">${p.reviewed?'Sin intervalo finito representable':'Cronología sin revisión; no se representa duración'}</span>`;
  const ticks=[23,10,5,2,1,0.3,0].map(t=>`<line x1="${x(t)}" y1="${height-7}" x2="${x(t)}" y2="${height-3}" stroke="#94a3b8"/>`).join('');
  return `<svg class="a3-c42-glyph" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escapeHtmlAttr(p.label)}"><title>${safe}. Evidencia de espécimen; no duración de taxón.</title>${ticks}${lines.join('')}</svg>`;
}
function a3C42OpenButton(sp,label='Abrir ficha') {
  return `<button type="button" data-open-species="${escapeHtmlAttr(sp.id)}">${escapeHtmlText(label)}</button>`;
}
function a3C42EvidenceTable(pool) {
 return `<div class="a3-c42-table-wrap"><table class="a3-evidence-table"><thead><tr><th>Ficha</th><th>Tipo y cronología</th><th>Evidencia representable</th><th>Consulta</th></tr></thead><tbody>${a3C42Rows(pool).map(({sp,presentation:p})=>`<tr><td>${escapeHtmlText(sp.nombre)}</td><td>${escapeHtmlText(p.label)}${p.reviewed?'':' · Sin revisión A1/A2'}</td><td>${a3C42Glyph(sp)}</td><td>${a3C42OpenButton(sp)}</td></tr>`).join('')}</tbody></table></div>`;
}

function renderContinentsView() {
  const host=document.getElementById('continentBoard');if(!host)return;
  const pool=DB.filter(matchesActiveFilters);
  const count=document.getElementById('continentVisibleCount'),hint=document.getElementById('continentRangeHint');
  if(count)count.textContent=String(pool.length);
  if(hint)hint.textContent=a3C42Summary(pool);
  host.innerHTML=`<div class="a3-evidence-note">Las agrupaciones continentales son etiquetas heredadas de consulta, no áreas de ocupación comprobadas. Las ventanas representan soporte cronológico de especímenes, no duración ni presencia continental continua.</div>`+
   CONTINENT_LANES.map(lane=>{
    const rows=pool.filter(sp=>getSpeciesContinents(sp).includes(lane.id));
    return `<section class="a3-c42-panel"><h3>${escapeHtmlText(lane.label)}</h3><p>${escapeHtmlText(lane.summary)}</p><p>${a3C42Summary(rows)}</p>${a3C42EvidenceTable(rows)}</section>`;
   }).join('');
}

