function renderAfricaLearningRoutes(visibleAfricaTaxa) {
  const visibleIds = new Set(visibleAfricaTaxa.map(sp => sp.id));
  const regionById = Object.fromEntries(AFRICA_REGIONS.map(region => [region.id, region]));
  const cards = AFRICA_LEARNING_ROUTES.map(route => {
    const steps = route.regions.map((regionId, index) => {
      const region = regionById[regionId];
      if (!region) return '';
      const visibleCount = region.taxa.filter(id => visibleIds.has(id)).length;
      const active = region.id === africaActiveRegionId ? 'active' : '';
      return `<button type="button" class="africa-route-step ${active}" data-africa-region="${escapeHtmlAttr(region.id)}" title="${escapeHtmlAttr(region.label)}">${index + 1}. ${escapeHtmlText(region.tag)} · ${visibleCount}</button>`;
    }).join('');
    const evidence = route.evidence.map(item => `<span class="africa-evidence-chip">${escapeHtmlText(item)}</span>`).join('');
    return `<article class="africa-route-card">
      <h4>${escapeHtmlText(route.title)}</h4>
      <p>${escapeHtmlText(route.focus)}</p>
      <div class="africa-route-steps">${steps}</div>
      <div class="africa-evidence-row">${evidence}</div>
      <div class="africa-route-question">
        <strong>Pregunta guía</strong>
        <p>${escapeHtmlText(route.question)}</p>
      </div>
      <div class="africa-route-output">
        <strong>Producto académico breve</strong>
        <p>${escapeHtmlText(route.product)}</p>
      </div>
      <button type="button" class="africa-question-open" data-africa-question-region="${escapeHtmlAttr(route.regions[0] || '')}">Abrir primera región</button>
    </article>`;
  }).join('');

  return `<section class="africa-learning-card" aria-label="Rutas didácticas del registro africano">
    <div class="africa-learning-head">
      <div>
        <h3>Rutas didácticas de lectura del registro africano</h3>
        <p>Selecciona una secuencia para convertir el mapa en una actividad: cada ruta enlaza regiones, evidencias y una pregunta investigable. Los botones de cada paso activan la región correspondiente en el panel.</p>
      </div>
      <span class="africa-learning-badge">aprendizaje guiado</span>
    </div>
    <div class="africa-route-grid">${cards}</div>
  </section>`;
}

