function getCharacterProfile(sp) {
  const profile = new Set(CHARACTER_BASE[sp.clado] || []);
  const override = CHARACTER_OVERRIDES[sp.id] || {};
  (override.add || []).forEach(charId => profile.add(charId));
  (override.remove || []).forEach(charId => profile.delete(charId));
  return profile;
}

function formatCharacterPills(ids, cssClass, emptyText) {
  if (!ids.length) return `<div class="cmp-empty">${emptyText}</div>`;
  return `<div class="cmp-pill-list">${ids.map(id => `<span class="cmp-pill ${cssClass}">${CHARACTER_CATALOG[id]?.label || id}</span>`).join('')}</div>`;
}

function buildCladisticSummary(A, B) {
  const profileA = getCharacterProfile(A);
  const profileB = getCharacterProfile(B);
  const shared = [...profileA].filter(id => profileB.has(id) && CHARACTER_CATALOG[id]);
  const primitiveShared = shared.filter(id => CHARACTER_CATALOG[id].kind === 'primitive').sort((a, b) => CHARACTER_CATALOG[a].label.localeCompare(CHARACTER_CATALOG[b].label, 'es'));
  const derivedShared = shared.filter(id => CHARACTER_CATALOG[id].kind === 'derived').sort((a, b) => CHARACTER_CATALOG[a].label.localeCompare(CHARACTER_CATALOG[b].label, 'es'));
  const uniqueA = [...profileA].filter(id => !profileB.has(id) && CHARACTER_CATALOG[id]?.kind === 'derived').sort((a, b) => CHARACTER_CATALOG[a].label.localeCompare(CHARACTER_CATALOG[b].label, 'es'));
  const uniqueB = [...profileB].filter(id => !profileA.has(id) && CHARACTER_CATALOG[id]?.kind === 'derived').sort((a, b) => CHARACTER_CATALOG[a].label.localeCompare(CHARACTER_CATALOG[b].label, 'es'));

  let note = '';
  if (A.clado === B.clado && derivedShared.length) {
    note = `La coincidencia en <strong>${derivedShared.length}</strong> rasgos derivados refuerza su agrupación dentro de <strong>${CLADE_NAMES[A.clado] || A.clado}</strong>.`;
  } else if (derivedShared.length) {
    note = `Comparten <strong>${derivedShared.length}</strong> rasgos derivados, pero la comparación combina afinidades evolutivas amplias con trayectorias adaptativas propias.`;
  } else if (primitiveShared.length) {
    note = `Predominan las <strong>plesiomorfías compartidas</strong>: hay similitud general, pero pocas señales de agrupación cladística inmediata en esta lectura simplificada.`;
  } else {
    note = `El contraste está dominado por rasgos exclusivos de cada linaje, útil para discutir convergencias y mosaicos evolutivos.`;
  }

  return { primitiveShared, derivedShared, uniqueA, uniqueB, note };
}

/**
 * Genera un mini-resumen climático para una especie dada,
 * basado en el stack LR04 y los MIS que solapan con su rango.
 * Usado en la pestaña Ecología del panel de detalle.
 * @param {Object} sp - Objeto especie con .range.start y .range.end (Ma)
 * @returns {string} HTML del bloque climático
 */
function buildClimateContext(sp) {
  const p=A3Temporal.presentation(sp);
  if (!p.reviewed) {
    return `<div class="detail-climate-card"><div class="detail-climate-head"><h4>🌡 Contexto climático</h4></div><p>La cronología de esta ficha todavía no ha sido cualificada para relacionarla automáticamente con series paleoclimáticas. Se conserva el rótulo histórico únicamente como dato descriptivo.</p></div>`;
  }
  if (!p.geometry.length || p.geometry.some(g=>g.kind==='minimum_age'||g.kind==='maximum_age')) {
    return `<div class="detail-climate-card"><div class="detail-climate-head"><h4>🌡 Contexto climático</h4></div><p>${escapeHtmlText(p.label)} no define una ventana temporal cerrada. No se calcula un clima medio ni un conjunto de MIS a partir de una edad mínima, máxima o cronología indeterminada.</p></div>`;
  }
  const windows=p.geometry.map(g=>g.kind==='point'?{youngKa:g.ma*1000,oldKa:g.ma*1000,label:p.label}:{youngKa:g.young_ma*1000,oldKa:g.old_ma*1000,label:`${formatMaValue(g.old_ma)}–${formatMaValue(g.young_ma)}`});
  const rows=windows.map(w=>{
    const values=LR04.filter(([ma])=>{const ka=ma*1000;return ka>=w.youngKa&&ka<=w.oldKa;});
    const mean=values.length?(values.reduce((s,[,v])=>s+v,0)/values.length).toFixed(2):'N/D';
    const mis=MIS_STAGES.filter(m=>m.start>=w.youngKa&&m.end<=w.oldKa).slice(0,6).map(m=>`MIS ${m.stage}`).join(', ')||'sin MIS resumidos';
    return `<li><strong>${escapeHtmlText(w.label)}</strong>: δ¹⁸O medio ${escapeHtmlText(mean)} ‰; ${escapeHtmlText(mis)}.</li>`;
  }).join('');
  return `<div class="detail-climate-card"><div class="detail-climate-head"><h4>🌡 Contexto climático de la evidencia revisada</h4><a class="detail-climate-link" href="#view-clima" data-climate-link>Ver gráfico completo →</a></div><p>La comparación se limita a la edad o a las ventanas documentadas de la evidencia; no representa la duración del taxón ni demuestra ocupación continua.</p><ul>${rows}</ul></div>`;
}

function renderContextTimeline() {
 const svg=document.getElementById('contextSvg');if(!svg)return;
 const pool=DB.filter(matchesActiveFilters);
 const events=CONTEXT_EVENTS;
 const count=document.getElementById('contextVisibleCount'),hint=document.getElementById('contextRangeHint');
 if(count)count.textContent=String(pool.length);
 if(hint)hint.textContent=a3C42Summary(pool);
 const W=1440,LEFT=330,ROW=45,TOP=100,H=TOP+ROW*(events.length+pool.length+1)+65;
 const x=ma=>LEFT+(23.5-Math.max(0,Math.min(23.5,ma)))/23.5*(W-LEFT-45);
 const parts=[`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Cronologías de especímenes revisados y referencias heredadas"><title>La evidencia cronológica no representa duración de taxones ni coexistencia biológica</title><rect width="${W}" height="${H}" fill="#faf9f7"/><text x="20" y="24" font-size="17" fill="#172554">Cronología de evidencias · A3-C4.2 experimental</text><text x="20" y="45" font-size="12" fill="#334155">Las barras heredadas se han retirado; los procesos ambientales requieren fuentes independientes.</text><text x="20" y="64" font-size="12" fill="#334155">${escapeHtmlText(a3C42Summary(pool))}</text>`];
 [23,10,5,2,1,.3,0].forEach(ma=>{parts.push(`<line x1="${x(ma)}" y1="${TOP-12}" x2="${x(ma)}" y2="${H-35}" stroke="#e2e8f0"/><text x="${x(ma)}" y="${TOP-22}" font-size="11" text-anchor="middle" fill="#475569">${ma===0?'Hoy':ma+' Ma'}</text>`);});
 events.forEach((event,i)=>{
  const y=TOP+i*ROW+ROW/2;
  parts.push(`<g data-context-event="${i}" aria-label="Contexto heredado sin validación cronológica independiente"><title>${escapeHtmlText(event.label)}. ${escapeHtmlText(event.note)}. Intervalo heredado: ${escapeHtmlText(event.start)}–${escapeHtmlText(event.end)} Ma.</title><text x="20" y="${y+4}" font-size="12" fill="#334155">${escapeHtmlText(event.label)}</text><text x="${LEFT+10}" y="${y+4}" font-size="11" fill="#64748b">Contexto heredado · ${escapeHtmlText(event.start)}–${escapeHtmlText(event.end)} Ma · sin revisión independiente</text></g>`);
 });
 pool.forEach((sp,i)=>{
  const y=TOP+(events.length+i)*ROW+ROW/2,p=A3Temporal.presentation(sp),color=CLADE_COLORS[sp.clado]||'#64748b';
  parts.push(`<g class="context-species-bar" data-open-species="${escapeHtmlAttr(sp.id)}" role="button" tabindex="0" aria-label="Ver ficha de ${escapeHtmlAttr(sp.nombre)}"><text x="20" y="${y+4}" font-size="12" fill="${color}">${escapeHtmlText(sp.nombre)}</text><title>${escapeHtmlText(p.label)}</title>`);
  for(const g of p.geometry){
   if(g.kind==='reported_window')parts.push(`<line x1="${x(g.old_ma)}" y1="${y}" x2="${x(g.young_ma)}" y2="${y}" stroke="${color}" stroke-width="5" stroke-linecap="round"/>`);
   else if(g.kind==='point'||g.kind==='minimum_age'||g.kind==='maximum_age'){
    const px=x(g.ma);if(g.kind==='point'&&Number.isFinite(g.uncertainty_ka))parts.push(`<line x1="${x(g.ma+g.uncertainty_ka/1000)}" y1="${y}" x2="${x(Math.max(0,g.ma-g.uncertainty_ka/1000))}" y2="${y}" stroke="${color}" stroke-width="2"/>`);
    parts.push(`<circle cx="${px}" cy="${y}" r="5" fill="${g.kind==='point'?color:'white'}" stroke="${color}" stroke-width="2"/>`);
   }
  }
  if(!p.geometry.length)parts.push(`<text x="${LEFT+10}" y="${y+4}" font-size="11" fill="#64748b">${p.reviewed?'Sin intervalo representable':'Sin revisión cronológica'}</text>`);
  parts.push(`<text x="${W-30}" y="${y+4}" text-anchor="end" font-size="11" fill="#475569">${escapeHtmlText(p.label)}</text></g>`);
 });
 parts.push(`</svg>`);
 svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.setAttribute('height',H);
 // Preserve the existing SVG element and its delegated opening/keyboard handlers.
 svg.innerHTML=parts.join('').replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'');
}

function formatMaValue(ma) {
  if (!Number.isFinite(ma)) return 's/d';
  if (ma >= 1) return `${ma.toFixed(ma >= 10 ? 0 : 1).replace(/\.0$/, '')} Ma`;
  return `${Math.round(ma * 1000)} ka`;
}

function formatMaRange(start, end) {
  if (!Number.isFinite(start) || !Number.isFinite(end)) return 'Cronología variable';
  if (Math.abs(start - end) < 0.01) return formatMaValue(start);
  return `${formatMaValue(start)}–${formatMaValue(end)}`;
}

function getSiteSpecies(site) {
  return (site.species || []).map(id => DB_INDEX[id]).filter(Boolean);
}

function getVisibleSiteSpecies(site, term) {
  const cladeFiltered = getSiteSpecies(site).filter(sp => cladoFilter === 'all' || sp.clado === cladoFilter);
  if (!term) return cladeFiltered;

  const speciesMatches = cladeFiltered.filter(sp =>
    normalizeForSearch([sp.nombre, A3Temporal.displayMetadata(sp).text, sp.holo, sp.ubicacion].join(' ')).includes(term)
  );
  if (speciesMatches.length) return speciesMatches;

  const siteText = normalizeForSearch([
    site.nombre,
    site.region,
    site.resumen,
    site.estratigrafia,
    ...(site.metodos || [])
  ].join(' '));
  return siteText.includes(term) ? cladeFiltered : [];
}

function renderSiteView() {
  const grid = document.getElementById('siteGrid');
  if (!grid) return;
  const term = normalizeForSearch(document.getElementById('searchInput')?.value || '');
  const cards = SITE_CATALOG
    .map(site => {
      const visibleSpecies = getVisibleSiteSpecies(site, term);
      if (!visibleSpecies.length) return null;
      const allSpecies = getSiteSpecies(site);
      const reviewed = allSpecies.map(sp=>A3Temporal.presentation(sp)).filter(p=>p.reviewed);
      return { site, visibleSpecies, allSpecies, reviewed };
    })
    .filter(Boolean)
    .sort((a,b)=>String(a.site.nombre).localeCompare(String(b.site.nombre),'es'));
  if (!cards.length) {
    grid.innerHTML = `<div class="site-empty">No hay yacimientos que coincidan con esta búsqueda o con el filtro de clado activo.</div>`;
    return;
  }
  grid.innerHTML = cards.map(({ site, visibleSpecies, allSpecies, reviewed }) => `
    <article class="site-card">
      <div class="site-card-top"><div><h3>${escapeHtmlText(site.nombre)}</h3><div class="site-meta">${escapeHtmlText(site.region)} · ${reviewed.length}/${allSpecies.length} cronologías revisadas</div></div><div class="site-badge">${escapeHtmlText(visibleSpecies.length)}/${escapeHtmlText(allSpecies.length)} taxones</div></div>
      <div class="site-section"><strong>Valor metodológico</strong><p>${safeGlossary(site.resumen)}</p></div>
      <div class="site-section"><strong>Estratigrafía resumida</strong><p>${safeGlossary(site.estratigrafia)}</p></div>
      <div class="site-section"><strong>Cronología</strong><p>No se fabrica un rango global del yacimiento a partir de los extremos de fichas heterogéneas. Consulte cada evidencia y su método de datación.</p></div>
      <div class="site-species-list">${visibleSpecies.map(sp=>`<button type="button" data-open-species="${escapeHtmlAttr(sp.id)}">${escapeHtmlText(sp.nombre)} · ${escapeHtmlText(A3Temporal.presentation(sp).label)}</button>`).join('')}</div>
    </article>`).join('');
}

function renderDebateView() {
  const grid = document.getElementById('debateGrid');
  if (!grid) return;

  const term = normalizeForSearch(document.getElementById('searchInput')?.value || '');
  const cards = ACTIVE_DEBATES.filter(item => {
    const matchClado = cladoFilter === 'all' || (item.clados || []).includes(cladoFilter);
    if (!matchClado) return false;
    if (!term) return true;
    const haystack = normalizeForSearch([
      item.titulo,
      item.resumen,
      item.pro,
      item.con,
      ...(item.temas || []),
      ...(item.refs || []).map(ref => `${ref.a} ${ref.t} ${ref.j} ${ref.y}`)
    ].join(' '));
    return haystack.includes(term);
  });

  if (!cards.length) {
    grid.innerHTML = `<div class="debate-empty">No hay controversias activas que coincidan con esta búsqueda o con el filtro de clado.</div>`;
    return;
  }

  grid.innerHTML = cards.map(item => `
    <article class="debate-card">
      <h3>${escapeHtmlText(item.titulo)}</h3>
      <div class="debate-meta">
        ${(item.temas || []).map(tag => `<span class="debate-meta-pill">${escapeHtmlText(tag)}</span>`).join('')}
      </div>
      <p class="debate-summary">${safeGlossary(item.resumen)}</p>

      <div class="debate-side-box pro">
        <span class="debate-side-title">Tesis A</span>
        <p>${safeGlossary(item.pro)}</p>
      </div>

      <div class="debate-side-box con">
        <span class="debate-side-title">Tesis B</span>
        <p>${safeGlossary(item.con)}</p>
      </div>

      <span class="debate-side-title">Referencias recientes</span>
      <ul class="debate-ref-list">
        ${(item.refs || []).map(renderReferenceListItem).join('')}
      </ul>
    </article>
  `).join('');
}

