let resourceLinkFilter = 'all';

function renderResourceAction(item) {
  if (item.view) return `<button type="button" class="resource-action" data-view="${escapeHtmlAttr(item.view)}">Abrir recurso</button>`;
  if (item.action) return `<button type="button" class="resource-action" data-action="${escapeHtmlAttr(item.action)}">Abrir recurso</button>`;
  if (item.href) return `<a class="resource-action secondary" href="${escapeHtmlAttr(item.href)}" target="_blank" rel="noopener">Abrir fuente</a>`;
  return '';
}

function renderResourceThumb(item) {
  if (!item.domain) {
    return `<span class="resource-link-thumb fallback" aria-hidden="true">${escapeHtmlText((item.title || '?').slice(0, 1))}</span>`;
  }
  // R90-P5: monograma local. El servicio google.com/s2/favicons estaba bloqueado
  // por la CSP (img-src) y además revelaba a terceros los dominios consultados.
  // Se conserva el dominio como metadato, sin petición de red.
  return `<span class="resource-link-thumb fallback" aria-hidden="true" data-resource-domain="${escapeHtmlAttr(item.domain)}">${escapeHtmlText((item.title || '?').slice(0, 1))}</span>`;
}

function renderResourceLinksSection() {
  const kinds = ['all', ...new Set(RESOURCE_LINKS.map(item => item.kind))];
  const visibleLinks = resourceLinkFilter === 'all'
    ? RESOURCE_LINKS
    : RESOURCE_LINKS.filter(item => item.kind === resourceLinkFilter);
  const groupedLinks = visibleLinks.reduce((acc, item) => {
    const group = item.group || 'Enlaces';
    if (!acc[group]) acc[group] = [];
    acc[group].push(item);
    return acc;
  }, {});
  return `<section class="resource-links-panel">
    <h3>Enlaces recomendados</h3>
    <div class="resource-link-tools" aria-label="Filtrar enlaces por tipo">
      ${kinds.map(kind => `<button type="button" class="resource-link-filter ${resourceLinkFilter === kind ? 'active' : ''}" data-resource-link-filter="${escapeHtmlAttr(kind)}">${escapeHtmlText(kind === 'all' ? 'Todos' : kind)}</button>`).join('')}
    </div>
    ${Object.entries(groupedLinks).map(([group, items]) => `
      <div class="resources-section-head pb-r70-gen-0ee7f66ad9" >
        <h3>${escapeHtmlText(group)}</h3>
        <span>${escapeHtmlText(items.length)} enlaces</span>
      </div>
      <div class="resource-link-list">
        ${items.map(item => {
          const flags = `<span class="resource-link-flags">${item.recommended ? '<span class="resource-link-priority">prioritario</span>' : ''}<span class="resource-link-kind">${escapeHtmlText(item.kind || 'Enlace')}</span>${item.href ? `<button type="button" class="resource-link-copy" data-copy-link="${escapeHtmlAttr(item.href)}">copiar</button>` : ''}</span>`;
          const inner = `${renderResourceThumb(item)}
            <span><span class="resource-link-title">${escapeHtmlText(item.title)}</span><span class="resource-link-note">${escapeHtmlText(item.note || '')}</span></span>
            ${flags}`;
          if (item.href) return `<a class="resource-link-row" href="${escapeHtmlAttr(item.href)}" target="_blank" rel="noopener">${inner}</a>`;
          return `<button type="button" class="resource-link-row" data-view="${escapeHtmlAttr(item.view || 'aula')}">${inner}</button>`;
        }).join('')}
      </div>
    `).join('')}
  </section>`;
}

function renderResourceBank() {
  const host = document.getElementById('resourceBankContent');
  if (!host) return;
  const term = normalizeForSearch(document.getElementById('searchInput')?.value || '');
  const resources = RESOURCE_BANK.filter(item => {
    if (!term) return true;
    return normalizeForSearch([item.category, item.kind, item.title, item.summary, item.use, ...(item.tags || [])].join(' ')).includes(term);
  });
  const byCategory = resources.reduce((acc, item) => {
    const category = item.category || 'Recursos';
    if (!acc[category]) acc[category] = [];
    acc[category].push(item);
    return acc;
  }, {});
  const categories = Object.entries(byCategory);
  const primaryCount = RESOURCE_BANK.filter(item => item.href).length;
  host.innerHTML = `
    <div class="resources-header">
      <h2>Banco de recursos</h2>
      <p>Selección práctica para preparar clases, trabajos y debates: combina herramientas internas del atlas, actividades didácticas y fuentes recientes verificadas. El buscador global también filtra este banco.</p>
    </div>
    <div class="resources-kpis" aria-label="Resumen del banco de recursos">
      <div class="resources-kpi"><strong>${escapeHtmlText(RESOURCE_BANK.length)}</strong><span>recursos</span></div>
      <div class="resources-kpi"><strong>${escapeHtmlText(categories.length)}</strong><span>categorías visibles</span></div>
      <div class="resources-kpi"><strong>${escapeHtmlText(primaryCount)}</strong><span>fuentes externas</span></div>
      <div class="resources-kpi"><strong>${escapeHtmlText(resources.length)}</strong><span>filtrados</span></div>
    </div>
    ${renderResourceLinksSection()}
    ${resources.length ? categories.map(([category, items]) => `
      <section class="resources-section">
        <div class="resources-section-head">
          <h3>${escapeHtmlText(category)}</h3>
          <span>${escapeHtmlText(items.length)} recursos</span>
        </div>
        <div class="resources-grid">
          ${items.map(item => `
            <article class="resource-card">
              <div class="resource-card-top">
                <h4>${escapeHtmlText(item.title)}</h4>
                <span class="resource-kind">${escapeHtmlText(item.kind)}</span>
              </div>
              <p>${escapeHtmlText(item.summary)}</p>
              <div class="resource-use"><strong>Uso recomendado:</strong> ${escapeHtmlText(item.use)}</div>
              <div class="resource-tags">${(item.tags || []).map(tag => `<span class="resource-tag">${escapeHtmlText(tag)}</span>`).join('')}</div>
              <div class="resource-actions">${renderResourceAction(item)}</div>
            </article>
          `).join('')}
        </div>
      </section>
    `).join('') : '<div class="resource-empty">No hay recursos que coincidan con la búsqueda actual.</div>'}
  `;
}

function getResearchGapProfile(sp) {
  const expert = getSpeciesExpert(sp);
  const custom = RESEARCH_GAPS[sp.id] || {};
  const missing = [...(custom.missing || [])];
  const dating = [...(custom.dating || [])];
  const biomolecular = [...(custom.biomolecular || [])];
  const fieldwork = [...(custom.fieldwork || [])];

  if (sp.cc == null) missing.push('No se dispone de una estimación de capacidad craneal suficientemente segura.');
  if ((expert.anatomia_craneal || '').includes('Desconocida')) missing.push('La anatomía craneal conocida sigue siendo parcial o insuficiente.');
  if ((expert.anatomia_postcraneal || '').includes('No recuperada')) missing.push('El postcráneo disponible es inexistente o demasiado fragmentario.');
  if (['Bio', 'Biocronología', 'Reloj'].includes(sp.datacion) || sp.estado === 'revision') dating.push('La cronología depende de métodos indirectos o de revisión taxonómica en curso.');
  if (sp.estado === 'debatida') dating.push('La interpretación cronológica y filogenética debe leerse con cautela por su estatus debatido.');
  biomolecular.push(A3Temporal.biomolecularCaution(sp));
  if (sp.id === 'denisova') biomolecular.push('El reto actual no es obtener más ADN, sino ligar señal genómica y anatomía diagnóstica.');
  if (sp.id === 'sapiens') fieldwork.push('Conviene integrar fósiles, genómica y paleoambiente en marcos regionales panafricanos más finos.');

  const dedupe = arr => [...new Set(arr)];
  return {
    missing: dedupe(missing),
    dating: dedupe(dating),
    biomolecular: dedupe(biomolecular),
    fieldwork: dedupe(fieldwork)
  };
}

function renderResearchGapModal() {
  const container = document.getElementById('researchGapContent');
  if (!container || !currentSpecies) return;

  const sp = currentSpecies;
  const gaps = getResearchGapProfile(sp);
  const renderList = items => items.length
    ? `<ul>${items.map(item => `<li>${safeGlossary(item)}</li>`).join('')}</ul>`
    : `<div class="gap-empty">No hay una laguna destacada cargada manualmente para este bloque.</div>`;

  container.innerHTML = `
    <div class="gap-intro">
      <strong class="pb-r70-gen-1dcb1f70ef" >${sp.nombre}</strong>
      Esta síntesis convierte la ficha en una agenda de investigación: qué material falta, qué cronologías siguen abiertas y dónde puede crecer el registro en próximos años.
    </div>
    <div class="gap-grid">
      <div class="gap-card">
        <h4>Material fósil ausente</h4>
        ${renderList(gaps.missing)}
      </div>
      <div class="gap-card">
        <h4>Datación y revisión cronológica</h4>
        ${renderList(gaps.dating)}
      </div>
      <div class="gap-card">
        <h4>Vacíos biomoleculares</h4>
        ${renderList(gaps.biomolecular)}
      </div>
      <div class="gap-card">
        <h4>Excavación y agenda futura</h4>
        ${renderList(gaps.fieldwork)}
      </div>
    </div>
  `;
}

function openResearchGapModal() {
  if (!currentSpecies) return;
  renderResearchGapModal();
  document.getElementById('researchGapModal').classList.add('active');
}

function openSpeciesViaPublicApiOrService(sp, source = 'generic-open-core', options = {}) {
  if (!sp) return false;
  const opts = Object.assign({ closeModal: true }, options || {});

  if (window.PaleoBot && typeof window.PaleoBot.openSpecies === 'function') {
    const result = window.PaleoBot.openSpecies(sp.id, {
      source,
      closeModal: opts.closeModal
    });
    if (result && result.ok) return true;
  }

  if (window.PaleoBotV40SpeciesOpen &&
      typeof window.PaleoBotV40SpeciesOpen.openSpeciesById === 'function') {
    return !!window.PaleoBotV40SpeciesOpen.openSpeciesById(
      sp.id,
      source,
      { closeModal: opts.closeModal }
    );
  }

  Logger.warn('Apertura canónica de taxón no disponible:', sp.id, source);
  return false;
}

