function getSpeciesComparisonCandidate(sp) {
  A3Temporal.identity(sp);
  const candidates = DB.filter(other => other && other.id !== sp.id);
  if (!candidates.length) return null;
  return candidates
    .map(other => {
      const sameClade = other.clado === sp.clado ? 0 : 8;
      const statusPenalty = other.estado === 'revision' ? 0.7 : 0;
      const evidencePenalty = A3Temporal.presentation(other).reviewed ? 0 : 0.2;
      return { other, score: sameClade + statusPenalty + evidencePenalty };
    })
    .sort((a, b) => a.score - b.score || String(a.other.nombre).localeCompare(String(b.other.nombre), 'es'))[0]?.other || null;
}

function getSpeciesMidpointMa(sp) {
  A3Temporal.identity(sp);
  return NaN;
}

function getDetailTimeRange(sp) {
  return A3Temporal.legacyRange(sp);
}

function getComparisonAgeGapLabel(a, b) {
  A3Temporal.identity(a); A3Temporal.identity(b);
  const d = A3Temporal.reportedOverlap(a, b);
  if (d.status === A3Temporal.states.POSSIBLE) return 'Las evidencias publicadas presentan solapamiento posible; no se demuestra coexistencia biológica.';
  if (d.status === A3Temporal.states.NONE) return 'Las ventanas documentadas no se solapan; no se demuestra ausencia histórica.';
  return 'Cronología no comparable sin un modelo de evidencia específico; compatibilidad indeterminada. No se infiere coexistencia ni una secuencia evolutiva.';
}

function renderGuidedScientificComparison(sp, expert = getSpeciesExpert(sp)) {
  const other = getSpeciesComparisonCandidate(sp);
  if (!other) return '';
  const otherExpert = getSpeciesExpert(other);
  const statusA = ESTADO_LABEL[sp.estado || 'sin_revision'] || 'Aceptada';
  const statusB = ESTADO_LABEL[other.estado || 'sin_revision'] || 'Aceptada';
  const ccA = Number.isFinite(Number(sp.cc)) ? `${sp.cc} cc` : 'sin dato';
  const ccB = Number.isFinite(Number(other.cc)) ? `${other.cc} cc` : 'sin dato';
  const rows = [
    ['Cronología', A3Temporal.displayMetadata(sp).text, A3Temporal.displayMetadata(other).text, `¿Qué permite afirmar la evidencia publicada y qué permanece indeterminado? (${getComparisonAgeGapLabel(sp, other)})`],
    ['Región', sp.ubicacion || 's/d', other.ubicacion || 's/d', 'Pregunta: ¿comparar regiones ayuda o introduce sesgo geográfico?'],
    ['Material', sp.holo || 's/d', other.holo || 's/d', 'Pregunta: ¿los restos son equivalentes o uno permite inferencias más fuertes?'],
    ['Capacidad craneal', ccA, ccB, 'Pregunta: ¿qué se puede discutir sin convertir el volumen en ranking de inteligencia?'],
    ['Cultura / tecnología', sp.herramientas || expert.cultura || 's/d', other.herramientas || otherExpert.cultura || 's/d', 'Pregunta: ¿la asociación cultural es directa, contextual o ausente?'],
    ['Estado científico', statusA, statusB, 'Pregunta: ¿qué afirmación exige más cautela taxonómica?']
  ];
  const rowHtml = rows.map(([criterion, a, b, question]) => `<tr>
    <td>${escapeHtmlText(criterion)}</td>
    <td>${safeGlossary(a)}</td>
    <td>${safeGlossary(b)}</td>
    <td>${escapeHtmlText(question)}</td>
  </tr>`).join('');
  const cladeA = CLADE_NAMES[sp.clado] || sp.clado || 'clado no indicado';
  const cladeB = CLADE_NAMES[other.clado] || other.clado || 'clado no indicado';
  return `<section class="data-section species-guided-comparison" aria-label="Comparación científica guiada">
    <h4>Comparación científica recomendada</h4>
    <p>Usa esta pareja para aprender por contraste: no memorices dos fichas; compara criterios equivalentes y decide qué inferencia está mejor sostenida.</p>
    <div class="cmp-headers">
      <article class="cmp-card ${escapeHtmlAttr(sp.clado || '')}">
        <div class="cmp-card-kicker">${escapeHtmlText(cladeA)}</div>
        <div class="cmp-card-name">${escapeHtmlText(sp.nombre)}</div>
        <div class="cmp-card-sub">${escapeHtmlText(A3Temporal.displayMetadata(sp).text)} · ${escapeHtmlText(sp.ubicacion || 's/d')}</div>
      </article>
      <article class="cmp-card ${escapeHtmlAttr(other.clado || '')}">
        <div class="cmp-card-kicker">${escapeHtmlText(cladeB)}</div>
        <div class="cmp-card-name">${escapeHtmlText(other.nombre)}</div>
        <div class="cmp-card-sub">${escapeHtmlText(A3Temporal.displayMetadata(other).text)} · ${escapeHtmlText(other.ubicacion || 's/d')}</div>
      </article>
    </div>
    <div class="matrix-scroll">
      <table class="cmp-table">
        <thead><tr><th>Criterio</th><th>${escapeHtmlText(sp.nombre)}</th><th>${escapeHtmlText(other.nombre)}</th><th>Uso didáctico-científico</th></tr></thead>
        <tbody>${rowHtml}</tbody>
      </table>
    </div>
    <div class="ai-action-row">
      <button type="button" class="research-gap-btn" data-open-species="${escapeHtmlAttr(other.id)}">Abrir ficha comparada</button>
    </div>
  </section>`;
}

function renderSpeciesExitTicket(sp, expert = getSpeciesExpert(sp)) {
  const comparison = getSpeciesComparisonCandidate(sp);
  const comparisonName = comparison ? comparison.nombre : 'otro taxón cercano del atlas';
  const evidenceAnchor = [
    sp.holo ? `material/localidad consignados: ${sp.holo}` : '',
    sp.datacion ? `datación: ${sp.datacion}` : '',
    sp.ubicacion ? `localización: ${sp.ubicacion}` : ''
  ].filter(Boolean).join(' · ') || 'un dato directo de la ficha';
  const debateAnchor = expert.debate
    ? expert.debate.split(/[.?!]/).find(Boolean)?.trim()
    : 'una inferencia que necesite más evidencia';
  const tickets = [
    {
      level: 'Universidad',
      time: '8 min',
      title: 'Comparación crítica',
      purpose: `Compara ${sp.nombre} con ${comparisonName}.`,
      prompts: [
        'Elige dos evidencias comparables: cronología, anatomía, cultura o moléculas.',
        `Incluye una cautela: ${debateAnchor}.`,
        'Formula qué dato nuevo cambiaría tu interpretación.'
      ],
      criterion: 'Bien si compara criterios equivalentes y reconoce incertidumbre.'
    }
  ];
  const cards = tickets.map(ticket => `<article class="teaching-ticket-card">
    <div class="teaching-ticket-meta">
      <span class="teaching-ticket-chip">${escapeHtmlText(ticket.level)}</span>
      <span class="teaching-ticket-chip">${escapeHtmlText(ticket.time)}</span>
    </div>
    <h4>${escapeHtmlText(ticket.title)}</h4>
    <p>${escapeHtmlText(ticket.purpose)}</p>
    <ol>${ticket.prompts.map(prompt => `<li>${escapeHtmlText(prompt)}</li>`).join('')}</ol>
    <p><strong>Criterio:</strong> ${escapeHtmlText(ticket.criterion)}</p>
  </article>`).join('');
  return `<section class="data-section species-exit-ticket" aria-label="Ticket de salida por niveles">
    <h4>Ticket de salida</h4>
    <p>Última tarea breve para comprobar comprensión: elige el nivel, responde por escrito y revisa el criterio antes de entregar.</p>
    <div class="teaching-ticket-grid">${cards}</div>
  </section>`;
}

function buildPrereadingConcepts(sp, expert = getSpeciesExpert(sp)) {
  const context = [
    sp.nombre, sp.descripcion, sp.dieta, sp.herramientas, sp.datacion, sp.holo,
    expert.descripcion_tecnica, expert.anatomia_craneal, expert.anatomia_postcraneal,
    expert.cultura, expert.paleogenomica, expert.paleoproteomica, expert.debate
  ].filter(Boolean).join(' ');
  const rules = [
    { term: 'holotipo', label: 'holotipo', tag: 'taxonomia', reason: 'Ancla el nombre científico a un material concreto.', check: 'Localiza qué resto sostiene el nombre de la especie.', when: () => false },
    { term: 'estratigrafia', label: 'estratigrafía', tag: 'datacion', reason: 'Ayuda a ordenar capas, yacimientos y edades.', check: 'Distingue fecha absoluta, capa y asociación faunística.', when: () => /dataci[oó]n|estratigraf|sediment|nivel|capa|ar-ar|k-ar|esr|osl|uranio|biocronolog/i.test(context) },
    { term: 'bipedismo', label: 'bipedismo', tag: 'anatomia', reason: 'Es clave para interpretar locomoción sin simplificar la evolución.', check: 'Busca qué parte del esqueleto permite discutir postura o marcha.', when: () => /b[ií]ped|locomoc|foramen|f[eé]mur|pelvis|pie|hallux|postcrane/i.test(context) },
    { term: 'capacidad craneal', label: 'capacidad craneal', tag: 'anatomia', reason: 'No equivale por sí sola a inteligencia: exige comparación cautelosa.', check: 'Compara volumen, cronología y contexto antes de sacar conclusiones.', when: () => !!sp.cc && String(sp.cc) !== '?' },
    { term: 'industria lítica', label: 'industria lítica', tag: 'tecnologia', reason: 'Conecta restos materiales con conducta, aprendizaje y transmisión cultural.', check: 'Separa herramienta asociada, tradición técnica e inferencia conductual.', when: () => /herramient|l[ií]tic|Olduvayense|Achelense|Musteriense|Levallois|bifaz|lascas?|modo\s*[1-5]/i.test(context) },
    { term: 'paleogenómica', label: 'paleogenómica', tag: 'paleogenomica', reason: 'Permite estudiar parentesco y mezcla, pero depende de preservación.', check: 'Pregunta si la evidencia es ADN directo o comparación indirecta.', when: () => /adn|gen[oó]m|paleogen|denisov|neandertal|mitocondrial|nuclear|introgresi/i.test(context) },
    { term: 'paleoproteomica', label: 'paleoproteómica', tag: 'paleogenomica', reason: 'Aporta evidencia molecular cuando el ADN antiguo no se conserva.', check: 'Identifica si se habla de proteínas, colágeno o esmalte dental.', when: () => /prote[oó]m|col[aá]geno|prote[ií]na|esmalte/i.test(context) },
    { term: 'clado', label: 'clado', tag: 'filogenia', reason: 'Evita leer la evolución como una escalera lineal.', check: 'Formula parentesco como hipótesis de ramas, no como ranking de progreso.', when: () => true },
    { term: 'mosaico', label: 'mosaico evolutivo', tag: 'filogenia', reason: 'Muchas especies combinan rasgos antiguos y derivados.', check: 'Busca un rasgo primitivo y otro derivado en la misma ficha.', when: () => /mosaico|primitiv|derivad|ancestral|moderno|arcaic/i.test(context) }
  ];
  const selected = [];
  const seen = new Set();
  const addRule = rule => {
    if (seen.has(rule.term)) return;
    const definition = getGlossaryDefinition(rule.term);
    if (!definition) return;
    seen.add(rule.term);
    const learning = getGlossaryLearningEntry(rule.term, [rule.tag]);
    selected.push({ ...rule, definition, learning });
  };
  rules.filter(rule => rule.when()).forEach(addRule);
  rules.forEach(rule => {
    if (selected.length < 4) addRule(rule);
  });
  return selected.slice(0, 4);
}

function renderPrereadingConceptCard(sp, expert = getSpeciesExpert(sp)) {
  const concepts = buildPrereadingConcepts(sp, expert);
  if (!concepts.length) return '';
  const cards = concepts.map(concept => {
    const safeTerm = escapeHtmlAttr(concept.term.replace(/[\s()\/]+/g, '_'));
    const def = escapeHtmlAttr(concept.definition);
    return `<article class="teaching-ticket-card">
      <div class="teaching-ticket-meta">
        <span class="teaching-ticket-chip">Antes de leer</span>
        <span class="teaching-ticket-chip">${escapeHtmlText(concept.tag)}</span>
      </div>
      <h4><span class="glossary-term" data-def="${def}" data-gterm="${safeTerm}" title="${def.substring(0, 72)}…">${escapeHtmlText(concept.label)}</span></h4>
      <p>${escapeHtmlText(concept.definition)}</p>
      <ol>
        <li>${escapeHtmlText(concept.reason)}</li>
        <li>${escapeHtmlText(concept.check)}</li>
      </ol>
    </article>`;
  }).join('');
  return `<section class="data-section species-prereading-card" aria-label="Conceptos previos para leer la ficha">
    <h4>Antes de leer: conceptos llave</h4>
    <p>Activa vocabulario básico antes de interpretar la ficha. Pulsa cada concepto si necesitas abrir su entrada del glosario.</p>
    <div class="teaching-ticket-grid">${cards}</div>
  </section>`;
}

function firstReadableSentence(text, fallback) {
  const clean = String(text || '').replace(/\s+/g, ' ').trim();
  if (!clean) return fallback;
  const first = clean.split(/(?<=[.!?])\s+/).find(Boolean) || clean;
  return first.length > 230 ? `${first.slice(0, 227).trim()}...` : first;
}

function getPlainLanguageCaution(sp, expert = getSpeciesExpert(sp)) {
  const status = sp.estado || 'sin_revision';
  if (status !== 'aceptada') {
    return `El estado de esta especie es ${ESTADO_LABEL[status] || status}: conviene hablar de hipótesis, no de certeza cerrada.`;
  }
  if (expert.debate) {
    return firstReadableSentence(expert.debate, 'Hay debate científico: revisa qué datos apoyan cada interpretación.');
  }
  if (/no documentada|ninguna|sin/i.test(sp.herramientas || expert.cultura || '')) {
    return 'No confundas ausencia de herramientas conservadas con ausencia total de conducta compleja.';
  }
  return 'No ordenes las especies como una escalera de progreso: compara evidencias concretas.';
}

function renderPlainLanguageSummary(sp, expert = getSpeciesExpert(sp)) {
  const evidence = getEvidenceProfile(sp);
  const cards = [
    {
      title: 'Qué es',
      body: `${sp.nombre} es un taxón del grupo ${CLADE_NAMES[sp.clado] || sp.clado || 'hominino'}.`,
      cue: 'Identidad antes que detalle.'
    },
    {
      title: 'Cuándo',
      body: A3Temporal.displayMetadata(sp).text,
      cue: 'Sitúalo antes de comparar.'
    },
    {
      title: 'Dónde',
      body: sp.ubicacion || 'Localización no indicada en la ficha.',
      cue: 'Un yacimiento no equivale a todo el territorio.'
    },
    {
      title: 'Por qué importa',
      body: firstReadableSentence(expert.debate || expert.cultura || sp.herramientas || sp.dieta, 'Ayuda a discutir evolución humana con datos, no como lista de nombres.'),
      cue: 'Conecta dato, inferencia y límite.'
    },
    {
      title: 'Cuidado',
      body: getPlainLanguageCaution(sp, expert),
      cue: 'Frase obligatoria de cautela.'
    }
  ];
  const html = cards.map(card => `<article>
    <span>${escapeHtmlText(card.title)}</span>
    <p>${safeGlossary(card.body)}</p>
    <small>${escapeHtmlText(card.cue)}</small>
  </article>`).join('');
  return `<section class="data-section species-clear-reading" aria-label="Resumen de lectura clara">
    <h4>Ficha rápida</h4>
    <p>Lectura inicial en cinco respuestas: qué es, cuándo, dónde, por qué importa y qué cautela debe acompañar la explicación.</p>
    <div class="detail-quick-read">${html}</div>
  </section>`;
}

function renderTimeBoxedLearningPath(sp, expert = getSpeciesExpert(sp)) {
  const hasDebate = !!expert.debate || (sp.estado && sp.estado !== 'aceptada');
  const hasMolecular = /adn|gen[oó]m|prote[oó]m|col[aá]geno|denisov|neandertal/i.test([
    expert.paleogenomica, expert.paleoproteomica, sp.paleogenomica, sp.holo
  ].filter(Boolean).join(' '));
  const paths = [
    {
      time: '3 min',
      title: 'Orientarse',
      goal: 'Entender la ficha sin perderse.',
      steps: [
        'Lee “Lectura clara”: cuándo, dónde y cuidado principal.',
        'Mira una imagen y di qué tipo de documento es: fósil, reconstrucción o mapa.',
        `Escribe una frase: “${sp.nombre} se sitúa en…”`
      ],
      product: 'Producto: una frase correcta + una duda.'
    },
    {
      time: '10 min',
      title: 'Explicar con evidencia',
      goal: 'Pasar de descripción a argumento.',
      steps: [
        'Elige un dato directo: holotipo, datación, yacimiento, rasgo o tecnología.',
        'Formula una inferencia y marca su límite.',
        'Completa el ticket de salida del nivel que corresponda.'
      ],
      product: 'Producto: miniargumento dato → inferencia → cautela.'
    },
    {
      time: '20 min',
      title: hasDebate || hasMolecular ? 'Investigar una controversia' : 'Comparar y revisar',
      goal: hasDebate || hasMolecular
        ? 'Distinguir consenso, debate y tipo de evidencia.'
        : 'Comparar dos taxones con criterios equivalentes.',
      steps: [
        'Usa la comparación científica recomendada.',
        hasMolecular ? 'Separa evidencia fósil, molecular y contextual.' : 'Compara cronología, región, material y cultura.',
        hasDebate ? 'Escribe qué dato resolvería mejor el debate.' : 'Propón qué dato nuevo cambiaría la interpretación.'
      ],
      product: 'Producto: comparación razonada + pregunta investigable.'
    }
  ];
  const cards = paths.map(path => `<article class="teaching-ticket-card">
    <div class="teaching-ticket-meta">
      <span class="teaching-ticket-chip">${escapeHtmlText(path.time)}</span>
      <span class="teaching-ticket-chip">Ruta</span>
    </div>
    <h4>${escapeHtmlText(path.title)}</h4>
    <p>${escapeHtmlText(path.goal)}</p>
    <ol>${path.steps.map(step => `<li>${escapeHtmlText(step)}</li>`).join('')}</ol>
    <p><strong>${escapeHtmlText(path.product)}</strong></p>
  </article>`).join('');
  return `<section class="data-section species-learning-path" aria-label="Rutas de trabajo por tiempo">
    <h4>Ruta de trabajo</h4>
    <p>Elige una ruta según el tiempo disponible. Sirve para clase rápida, actividad guiada o investigación breve.</p>
    <div class="teaching-ticket-grid">${cards}</div>
  </section>`;
}

function renderUnderstandingTrafficLight(sp, expert = getSpeciesExpert(sp)) {
  const status = sp.estado || 'sin_revision';
  const hasDebate = !!expert.debate || status !== 'aceptada';
  const checks = [
    {
      level: 'Verde',
      title: 'Puedo avanzar',
      test: `Explico cuándo y dónde aparece ${sp.nombre}, y cito un dato directo.`,
      next: 'Abre la comparación recomendada o completa el ticket de salida.'
    },
    {
      level: 'Ámbar',
      title: 'Necesito reforzar',
      test: 'Tengo una idea general, pero no distingo bien dato, inferencia y límite.',
      next: 'Vuelve a “Lectura clara” y subraya un holotipo, una datación o una imagen.'
    },
    {
      level: 'Rojo',
      title: 'Debo parar',
      test: hasDebate
        ? 'Estoy presentando una hipótesis debatida como si fuera consenso.'
        : 'Estoy usando palabras como “más evolucionado” o comparando sin criterio común.',
      next: hasDebate
        ? 'Lee “Errores que debes evitar” y localiza qué evidencia resolvería el debate.'
        : 'Reformula con cronología, región, material fósil o tecnología.'
    }
  ];
  const cards = checks.map(item => `<article class="teaching-ticket-card">
    <div class="teaching-ticket-meta">
      <span class="teaching-ticket-chip">${escapeHtmlText(item.level)}</span>
      <span class="teaching-ticket-chip">Autoevaluación</span>
    </div>
    <h4>${escapeHtmlText(item.title)}</h4>
    <p>${escapeHtmlText(item.test)}</p>
    <ol><li>${escapeHtmlText(item.next)}</li></ol>
  </article>`).join('');
  return `<section class="data-section species-understanding-light" aria-label="Semáforo de comprensión">
    <h4>Semáforo de comprensión</h4>
    <p>Antes de cambiar de especie, comprueba en qué punto estás. No es una nota: es una decisión sobre el siguiente paso.</p>
    <div class="teaching-ticket-grid">${cards}</div>
  </section>`;
}

