let currentNavFamily = 'explorar';

function updateNavFamilyUI(family) {
  document.body.dataset.navFamily = family || '';
  document.querySelectorAll('.nav-family-btn[data-nav-family], .nav-objective[data-nav-family]').forEach(btn => {
    const active = btn.dataset.navFamily === family;
    const available = familyHasAvailableViews(btn.dataset.navFamily);
    const isObjectiveButton = btn.classList.contains('nav-objective');
    if (!isObjectiveButton) btn.hidden = !available;
    btn.disabled = !available;
    btn.classList.toggle('active', active);
    btn.setAttribute('aria-pressed', active ? 'true' : 'false');
    if (isObjectiveButton) btn.setAttribute('aria-disabled', available ? 'false' : 'true');
  });
  document.querySelectorAll('.view-switch .view-btn').forEach(btn => {
    const meta = VIEW_META[btn.dataset.view];
    btn.hidden = Boolean(meta && (meta.family !== family || !isViewAvailableForLevel(btn.dataset.view)));
  });
}

function updateViewOrientation(viewId) {
  const meta = VIEW_META[viewId];
  if (!meta) return;
  const familyMeta = NAV_FAMILY_META[meta.family] || {};
  const tierEl = document.getElementById('viewOrientationTier');
  const titleEl = document.getElementById('viewOrientationTitle');
  const familyEl = document.getElementById('viewOrientationFamily');
  const copyEl = document.getElementById('viewOrientationCopy');
  const audienceEl = document.getElementById('viewOrientationAudience');
  const goalEl = document.getElementById('viewOrientationGoal');
  if (tierEl) tierEl.textContent = familyMeta.tier || 'Vista';
  if (titleEl) titleEl.textContent = meta.title;
  if (familyEl) familyEl.textContent = familyMeta.label || meta.family;
  if (copyEl) copyEl.textContent = meta.description;
  if (audienceEl) audienceEl.textContent = meta.audience;
  if (goalEl) goalEl.textContent = meta.goal;
}

function syncNavigationState(viewId) {
  const meta = VIEW_META[viewId];
  if (!meta) return;
  currentNavFamily = meta.family;
  updateNavFamilyUI(currentNavFamily);
  updateViewOrientation(viewId);
}

function setNavFamily(family, options = {}) {
  if (!NAV_FAMILY_META[family]) return;
  if (!familyHasAvailableViews(family)) {
    const fallback = COMPLEXITY_MODES[nivelActual]?.defaultView || 'timeline';
    switchView(fallback, getViewButton(fallback));
    return;
  }
  currentNavFamily = family;
  updateNavFamilyUI(family);
  const activeView = getActiveViewId();
  if (options.forceDefault || !VIEW_META[activeView] || VIEW_META[activeView].family !== family) {
    const nextView = isViewAvailableForLevel(NAV_FAMILY_META[family].defaultView)
      ? NAV_FAMILY_META[family].defaultView
      : firstAvailableViewForFamily(family);
    if (nextView) {
      switchView(nextView, getViewButton(nextView));
      return;
    }
  }
  updateViewOrientation(activeView);
}

function ensureViewHero(viewId) {
  const section = document.getElementById('view-' + viewId);
  const meta = VIEW_META[viewId];
  if (!section || !meta) return;
  const heroMeta = VIEW_HERO_META[viewId] || {};
  let hero = section.querySelector('.view-hero');
  if (!hero) {
    hero = document.createElement('section');
    hero.className = 'view-hero';
    section.prepend(hero);
  }
  const pills = (heroMeta.pills || []).map(item => `<span class="view-hero-pill">${escapeHtmlText(item)}</span>`).join('');
  const steps = (heroMeta.steps || []).map((item, index) => `<span><b>${index + 1}.</b> ${escapeHtmlText(item)}</span>`).join('');
  const exitProduct = VIEW_EXIT_PRODUCTS[viewId] || 'Una conclusión breve con evidencia, razonamiento y cautela.';
  const nextActions = '';
  hero.dataset.family = meta.family;
  hero.innerHTML = `
    <div class="view-hero-grid">
      <div>
        <div class="view-hero-kicker">${escapeHtmlText(heroMeta.kicker || NAV_FAMILY_META[meta.family]?.label || 'Vista')}</div>
        <div class="view-hero-title-row">
          <h2>${escapeHtmlText(meta.title)}</h2>
          <span class="view-hero-badge">${escapeHtmlText(heroMeta.badge || meta.audience)}</span>
        </div>
        <p class="view-hero-description">${escapeHtmlText(meta.description)}</p>
        <div class="view-hero-pills">${pills}</div>
        ${nextActions ? `<div class="view-hero-actions" aria-label="Siguientes pasos recomendados">${nextActions}</div>` : ''}
      </div>
      <div class="view-hero-side">
        <div class="view-hero-card">
          <strong>Pregunta guía</strong>
          <p>${escapeHtmlText(heroMeta.question || meta.goal)}</p>
        </div>
        <div class="view-hero-card">
          <strong>Cómo leer esta vista</strong>
          <div class="view-hero-list">${steps}</div>
        </div>
        <div class="view-hero-card">
          <strong>Producto evaluable</strong>
          <p>${escapeHtmlText(exitProduct)}</p>
        </div>
      </div>
    </div>`;
}

function switchView(v, btn) {
    const previousView = getActiveViewId();
    if (!isViewAvailableForLevel(v)) {
        const fallback = firstAvailableViewForFamily(VIEW_META[v]?.family || 'explorar');
        v = fallback || 'timeline';
        btn = getViewButton(v);
    }
    if (!suppressViewHistory && previousView && previousView !== v) {
        viewHistoryStack.push(previousView);
        if (viewHistoryStack.length > 40) viewHistoryStack.shift();
    }
    const resolvedBtn = btn || getViewButton(v);
    document.querySelectorAll('.view-section').forEach(e => e.classList.remove('active'));
    document.getElementById('view-'+v)?.classList.add('active');
    document.querySelectorAll('.view-btn').forEach(b => {
      b.classList.remove('active');
      b.setAttribute('aria-pressed', 'false');
      b.removeAttribute('aria-current');              /* v60: WCAG 1.3.1 */
    });
    if (resolvedBtn) {
      resolvedBtn.classList.add('active');
      resolvedBtn.setAttribute('aria-pressed', 'true');
      resolvedBtn.setAttribute('aria-current', 'page');  /* v60: WCAG 1.3.1 */
    }
    syncNavigationState(v);
    // FIX v23-1: evento central en lugar de monkey-patching encadenado
    // v58-fix: marcar pbV50UserNavigated en switchView principal para evitar resets
    document.body.dataset.pbV50UserNavigated = '1';
    document.dispatchEvent(new CustomEvent('paleobot:viewchange', { detail: { view: v, btn: resolvedBtn } }));
    renderActiveView(v);
    updateBackButtonState();
}

function filterSpecies(txt) { applyFilters(); }
// FIX v23-5: debounce de búsqueda — evita re-renders en cada pulsación
let _applyDebounceTimer = null;
function debouncedApplyFilters() {
  clearTimeout(_applyDebounceTimer);
  _applyDebounceTimer = setTimeout(applyFilters, 240);
}

