/**
 * Copia la bibliografía de la especie actualmente abierta en APA 7.
 */
function copySpeciesBibliography() {
    if (!currentSpecies) { alert('Abre primero la ficha de una especie.'); return; }
    PaleoBot.ExportManager.copyBibliography(currentSpecies, 'apa');
}

function buildFacialPrompt(sp) {
    return `Redacta una descripción científica de la morfología facial de ${sp.nombre} para nivel ${nivelActual}. Usa solo estos datos de la ficha: ${sp.experto?.anatomia_craneal || ''} ${sp.experto?.descripcion_tecnica || ''}. Indica incertidumbres y evita reconstrucciones no documentadas.`;
}

function localFacialDescription(sp) {
    const cranial = sp.experto?.anatomia_craneal || 'La ficha no conserva una descripción craneal suficiente.';
    const tech = sp.experto?.descripcion_tecnica || '';
    const debate = sp.experto?.debate || '';
    const levelLead = {
      basico: 'En lectura básica, conviene imaginar la cara a partir de rasgos observables y evitar detalles especulativos.',
      universitario: 'En lectura universitaria, la reconstrucción debe separar rasgos diagnósticos, inferencias comparativas e incertidumbre tafonómica.',
      doctorado: 'En lectura de doctorado, la descripción debe tratarse como una hipótesis morfológica condicionada por preservación, muestra y debate taxonómico.'
    }[nivelActual] || '';
    return `${levelLead} Para ${sp.nombre}, los datos craneofaciales cargados indican: ${cranial} ${tech ? `Como complemento técnico: ${tech}` : ''} ${debate ? `Punto crítico de interpretación: ${debate}` : ''}`;
}

async function generateFacialDescription() {
    if (!currentSpecies) return;
    const panel = document.getElementById('aiFacialPanel');
    if (!panel) return;
    panel.classList.add('active');
    panel.innerHTML = `<h4>Reconstrucción facial IA</h4><p>Generando descripción adaptada al nivel <strong>${nivelActual}</strong>…</p>`;

    const endpoint = window.PALEOBOT_CLAUDE_ENDPOINT;
    if (endpoint) {
      try {
        const res = await fetch(endpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            task: 'facial_reconstruction_description',
            speciesId: currentSpecies.id,
            level: nivelActual,
            prompt: buildFacialPrompt(currentSpecies)
          })
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        // FIX C-1: sanitizeText() antes de innerHTML — prevención de XSS
        const _rawText = data.text || data.descripcion || localFacialDescription(currentSpecies);
        const _safeText = sanitizeText(String(_rawText));
        panel.innerHTML = `<h4>Reconstrucción facial IA</h4><p>${aplicarGlosario(_safeText)}</p><small>Generado mediante endpoint Claude configurado en <code>window.PALEOBOT_CLAUDE_ENDPOINT</code>. Revisión docente recomendada.</small>`;
        return;
      } catch (err) {
        Logger.warn('Claude endpoint no disponible:', err);
      }
    }

    // FIX C-1: sanitizeText() en modo local (datos internos — prevención defensiva)
    const _localText = sanitizeText(localFacialDescription(currentSpecies));
    panel.innerHTML = `<h4>Reconstrucción facial IA</h4><p>${aplicarGlosario(_localText)}</p><small>Modo local seguro: no hay endpoint Claude configurado. Para usar Claude sin exponer claves en el navegador, define un proxy propio en <code>window.PALEOBOT_CLAUDE_ENDPOINT</code>.</small>`;
}

function buildAcademicPrintSheet(sp) {
    const narrative = A3Temporal.narrative(sp);
    const chronology = A3Temporal.displayMetadata(sp);
    const disc = DISCOVERY_DATES[sp.id];
    const refs = (narrative.experto?.referencias || []).slice(0, 5);
    const doiList = refs.length
      ? refs.map(renderReferencePrintItem).join('')
      : '<li>Sin referencias DOI cargadas para esta ficha.</li>';
    const resourceUrl = `${window.location.href.split('#')[0]}#${encodeURIComponent(sp.id)}`;
    const safePrintName = escapeHtmlText(sp.nombre);
    const safePrintDate = escapeHtmlText(new Date().toLocaleDateString('es-ES'));
    const safeResourceUrl = escapeHtmlText(resourceUrl);
    const safePrintClade = escapeHtmlText(CLADE_NAMES[sp.clado] || sp.clado);
    const safePrintYears = escapeHtmlText(chronology.text);
    const safePrintLocation = escapeHtmlText(sp.ubicacion);
    const safePrintHolotype = escapeHtmlText(sp.holo);
    const safePrintDating = escapeHtmlText(chronology.source_status === 'A2_REVIEWED' ? chronology.method || 'No consta' : 'Método heredado: '+(sp.datacion||'No consta')+'. Revisión pendiente.');
    const safePrintCc = escapeHtmlText(sp.cc ? sp.cc + ' cc' : 'No disponible');
    const safePrintDiscovery = escapeHtmlText(disc ? `${disc.anio} · ${disc.autor}` : 'No cargado');
    const safePrintStatus = escapeHtmlText(ESTADO_LABEL[sp.estado || 'sin_revision'] || 'Aceptada');
    const safePrintSummary = escapeHtmlText(narrative.descripcion);
    const safePrintCranial = escapeHtmlText(narrative.experto?.anatomia_craneal || 'Datos no disponibles.');
    return `<div class="academic-page">
      <div class="academic-head">
        <div>
          <h1>${safePrintName}</h1>
          <p>PaleoBot · ficha académica de una página · ${safePrintDate}</p>
        </div>
        <div class="academic-resource-link" role="note">
          <strong>Enlace del recurso</strong>
          <span>${safeResourceUrl}</span>
        </div>
      </div>
      <div class="academic-grid">
        <div>
          <img class="academic-img" src="${escapeHtmlAttr(getSpeciesImage(sp))}" alt="${escapeHtmlAttr(sp.nombre)}" decoding="async" referrerpolicy="no-referrer">
          <div class="academic-section">
            <h2>Recurso</h2>
            <p>${safeResourceUrl}</p>
          </div>
        </div>
        <div>
          <div class="academic-kpis">
            <div class="academic-kpi"><strong>Clado</strong>${safePrintClade}</div>
            <div class="academic-kpi"><strong>Cronología</strong>${safePrintYears}</div>
            <div class="academic-kpi"><strong>Yacimiento / región</strong>${safePrintLocation}</div>
            <div class="academic-kpi"><strong>Material / localidad</strong>${safePrintHolotype}</div>
            <div class="academic-kpi"><strong>Datación</strong>${safePrintDating}</div>
            <div class="academic-kpi"><strong>CC</strong>${safePrintCc}</div>
            <div class="academic-kpi"><strong>Descubrimiento</strong>${safePrintDiscovery}</div>
            <div class="academic-kpi"><strong>Estado</strong>${safePrintStatus}</div>
          </div>
          <div class="academic-section"><h2>Alcance y procedencia cronológica</h2><p>${escapeHtmlText(chronology.scope_note)}</p><p>${escapeHtmlText(chronology.source_label)}</p><p>Los restantes contenidos históricos no constituyen una revisión científica integral.</p></div>
          <div class="academic-section"><h2>Resumen</h2><p>${safePrintSummary}</p></div>
          <div class="academic-section"><h2>Anatomía craneal</h2><p>${safePrintCranial}</p></div>
          <div class="academic-section"><h2>Referencias</h2><ul>${doiList}</ul></div>
        </div>
      </div>
      <div class="academic-footer">
        <span>Exportado desde PaleoBot</span>
        <span>Usar “Guardar como PDF” en el diálogo de impresión</span>
      </div>
    </div>`;
}

function exportAcademicPDF() {
    if (!currentSpecies) { alert('Abre primero la ficha de una especie.'); return; }
    const sheet = document.getElementById('academicPrintSheet');
    if (!sheet) return;
    sheet.innerHTML = buildAcademicPrintSheet(currentSpecies);
    document.body.classList.add('pdf-academic-mode');
    setTimeout(() => {
      window.print();
      setTimeout(() => document.body.classList.remove('pdf-academic-mode'), 300);
    }, 80);
}

// FIX #8: printFicha con guardia — avisa si no hay panel abierto
function printFicha() {
    const panel = document.getElementById('detailView');
    if (!panel || !panel.classList.contains('active') || !currentSpecies) {
        alert('Abre primero la ficha de una especie para poder imprimirla.');
        return false;
    }
    exportAcademicPDF();
    return true;
}

