/** v58: Genera preguntas guía para la ficha de especie */
function renderSpeciesGuideQuestions(sp) {
  if (!sp) return '';
  const isDebated = sp.estado === 'debatida' || sp.estado === 'revision';
  const hasDebate = sp.experto && sp.experto.debate && sp.experto.debate.length > 30;
  const isBipedal = sp.clado === 'basal' || sp.clado === 'australo';
  const isHomo    = sp.clado === 'homo';

  const questions = [];

  // Pregunta sobre evidencia
  if (sp.holo && sp.holo !== 'N/A') {
    questions.push(`¿Qué puedes afirmar con certeza a partir del material o localidad consignados <strong>${escapeHtmlText(sp.holo)}</strong>? ¿Qué inferencias son razonables pero no directamente observables?`);
  }

  // Pregunta sobre contexto africano (DEA)
  if (sp.ubicacion && sp.ubicacion.toLowerCase().includes('áfrica') || ['Kenia','Etiopía','Tanzania','Sudáfrica','Chad','Uganda','Zambia','Marruecos'].some(r => (sp.ubicacion||'').includes(r))) {
    questions.push(`¿Qué nos dice la localización de ${escapeHtmlText(sp.nombre)} en ${escapeHtmlText(sp.ubicacion)} sobre la distribución geográfica de la hominización?`);
  }

  // Pregunta sobre debate si existe
  if (hasDebate) {
    questions.push(`¿Cuál es el debate científico central sobre ${escapeHtmlText(sp.nombre)}? ¿Qué nuevo hallazgo resolvería mejor la controversia?`);
  }

  // Pregunta sobre bipedismo para basales/australos
  if (isBipedal) {
    questions.push(`¿Qué evidencias apoyan el bipedismo en ${escapeHtmlText(sp.nombre)} y cuáles siguen siendo inferidas o debatidas?`);
  }

  // Pregunta sobre cognición para Homo
  if (isHomo && sp.cc && sp.cc > 600) {
    questions.push(`La capacidad craneal de ${escapeHtmlText(sp.nombre)} es ${sp.cc} cc. ¿Implica necesariamente mayor complejidad cognitiva? ¿Qué otras evidencias acompañarían esa inferencia?`);
  }

  if (questions.length === 0) return '';

  const qHtml = questions.slice(0, 3).map((q, i) =>
    `<li class="pb-r70-gen-d2a7a25d47" >${q}</li>`
  ).join('');

  return `
  <details class="species-guide-questions pb-r70-gen-adec3e761b" >
    <summary class="pb-r70-gen-3e158da2c0"  aria-label="Preguntas guía para reflexionar sobre esta especie">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/><path d="M12 17h.01"/></svg>
      Preguntas para reflexionar sobre ${escapeHtmlText(sp.nombre)}
    </summary>
    <ul class="pb-r70-gen-c58143fb26" >${qHtml}</ul>
  </details>`;
}

function runExam() {
    window.PaleoBotStyleState.display(document.getElementById('examIntro'), 'none');
    const examDiv = document.getElementById('examQ');
    window.PaleoBotStyleState.display(examDiv, 'block');
    examDiv.innerHTML = '';
    // Contador de sesión
    const sessionCount = parseInt(window.PaleoBotStorage?.getSession('paleobot_quiz_session_count', '0') || '0', 10) + 1;
    window.PaleoBotStorage?.setSession('paleobot_quiz_session_count', String(sessionCount));
    // Mostrar indicador en el header del modal si existe
    const headerTitle = document.getElementById('examModal-title');
    if (headerTitle) {
      headerTitle.textContent = 'Autoevaluación de repaso — Pregunta ' + sessionCount;
    }

    // Cada tipo declara también la pestaña de la ficha más relevante (mejora v26)
    const tipos = [
        sp => ({
            q: `¿Cuál es la capacidad craneal aproximada de ${sp.nombre}?`,
            a: sp.cc ? sp.cc + ' cc' : null,
            pool: DB.filter(s => s.cc).map(s => s.cc + ' cc'),
            tab: 'anat',
            explanation: `La capacidad craneal (cc) de ${sp.nombre} es ${sp.cc || 'desconocida'} cc. El valor consignado requiere comprobación del ejemplar y del método de estimación; describe volumen endocraneal, sin equivalencia directa con capacidad cognitiva.`
        }),
        sp => ({
            q: `¿En qué país o región se descubrieron los fósiles de ${sp.nombre}?`,
            a: sp.ubicacion,
            pool: [...new Set(DB.map(s => s.ubicacion))],
            tab: 'gen',
            explanation: `Los fósiles de ${sp.nombre} proceden de ${sp.ubicacion}. La localización geográfica es clave para entender la distribución africana de los homininos, aunque no implica que la especie se limitara a esa región.`
        }),
        sp => ({
            q: `¿A qué clado pertenece ${sp.nombre}?`,
            a: CLADE_NAMES[sp.clado],
            pool: Object.values(CLADE_NAMES),
            tab: 'gen',
            explanation: `${sp.nombre} pertenece al clado ${CLADE_NAMES[sp.clado]}. Recuerda: el clado agrupa taxones por relación de parentesco, no necesariamente por secuencia temporal ni por ancestralidad directa.`
        }),
        sp => ({
            q: `¿Qué material o localidad consigna la ficha de ${sp.nombre}?`,
            a: /^(N\/A|ADN)$/i.test(sp.holo) ? null : sp.holo,
            pool: DB.map(s => s.holo).filter(x => !/^(N\/A|ADN)$/i.test(x)),
            tab: 'anat',
            explanation: `La ficha consigna ${sp.holo} como referencia de material o localidad. La condición de holotipo solo puede afirmarse tras contrastar la descripción original o una revisión nomenclatural.`
        }),
        sp => {
            const p = A3Temporal.presentation(sp);
            if (!p.reviewed) return { q:'Cronología no cualificada', a:null, pool:[], tab:'gen', explanation:'' };
            const pool = DB.map(s => A3Temporal.presentation(s)).filter(x => x.reviewed && x.id !== sp.id).map(x => x.label);
            return {
              q: `¿Qué cronología revisada se presenta para ${sp.nombre}?`,
              a: p.label,
              pool,
              tab: 'gen',
              explanation: `La ficha revisada presenta ${p.label}. Esta evidencia corresponde a ${p.entity_type || 'la entidad documentada'} y no debe transformarse automáticamente en duración taxonómica.`
            };
        }
    ];

    const sp = DB[Math.floor(Math.random() * DB.length)];
    const tipo = tipos[Math.floor(Math.random() * tipos.length)](sp);
    if (!tipo.a) { runExam(); return; }

    const correcta   = tipo.a;
    const tabDestino = tipo.tab || 'gen';
    const distractores = [...new Set(tipo.pool.filter(x => x !== correcta))]
        .sort(() => Math.random() - 0.5).slice(0, 3);
    const opts = [correcta, ...distractores].sort(() => Math.random() - 0.5);

    const qEl = document.createElement('p');
    qEl.className = 'exam-question-title';
    qEl.textContent = tipo.q;
    examDiv.appendChild(qEl);

    opts.forEach(o => {
        const btn = document.createElement('button');
        btn.className = 'exam-opt';
        btn.textContent = o;
        btn.addEventListener('click', () => {
            const ok = o === correcta;
            QuizProgress.record(sp.id, ok, 'classic');
            examDiv.querySelectorAll('.exam-opt').forEach(b => b.disabled = true);
            btn.classList.add(ok ? 'exam-correct' : 'exam-wrong');
            if (!ok) examDiv.querySelectorAll('.exam-opt').forEach(b => {
                if (b.textContent === correcta) b.classList.add('exam-correct');
            });
            const tabLabels = { gen:'General', anat:'Anatomía', eco:'Ecología', biblio:'Investigación' };
            const explanation = tipo.explanation || '';
            const res = document.createElement('div');
            res.className = 'exam-feedback';
            res.innerHTML = `
              <p class="exam-feedback-title">
                ${ok ? '✅ Correcto' : '❌ Incorrecto'}
              </p>
              ${!ok ? `<p class="exam-feedback-note">
                Respuesta correcta: <strong>${correcta}</strong>
              </p>` : ''}
              ${explanation ? `<div class="exam-feedback-card pb-r70-gen-c9d92b4425" >
                <p class="pb-r70-gen-1b5e02db9f" >📖 ¿Por qué?</p>
                <p class="pb-r70-gen-2538f5f612" >${escapeHtmlText(explanation)}</p>
              </div>` : ''}
              <div class="exam-action-row">
                <button type="button" class="exam-btn" data-quiz-next="classic">Siguiente pregunta</button>
                <button type="button" class="exam-btn linked"
                  data-quiz-open-species="${escapeHtmlAttr(sp.id)}"
                  data-quiz-tab="${escapeHtmlAttr(tabDestino)}"
                  title="Abrir la ficha de ${escapeHtmlAttr(sp.nombre)} en la pestaña ${escapeHtmlAttr(tabLabels[tabDestino])}">
                  Ver ficha de <em>${escapeHtmlText(sp.nombre)}</em> → ${escapeHtmlText(tabLabels[tabDestino])}
                </button>
              </div>`;
            examDiv.appendChild(res);
        });
        examDiv.appendChild(btn);
    });
}

function getVisibleQuizPool() {
    const pool = DB.filter(matchesActiveFilters);
    return pool.length >= 4 ? pool : DB.filter(sp => cladoFilter === 'all' || sp.clado === cladoFilter);
}

/**
 * Construye una pregunta generativa a partir del pool visible.
 * v26: añade campo `tab` y `_spId` para enlazar la ficha tras responder.
 */
function buildGenerativeQuestion(pool) {
    const candidates = pool.filter(sp => sp.holo && !/^(N\/A|ADN)$/i.test(sp.holo) && sp.ubicacion && sp.experto);
    const sp = candidates[Math.floor(Math.random() * candidates.length)] || pool[Math.floor(Math.random() * pool.length)];
    const templates = {
      basico: [
        { q:`¿Qué especie se asocia con ${sp.ubicacion}?`,
          a:sp.nombre, pool:pool.map(s=>s.nombre),
          why:`${sp.nombre} aparece registrado con ubicación principal: ${sp.ubicacion}.`,
          tab:'gen' },
        { q:`¿A qué clado pertenece ${sp.nombre}?`,
          a:CLADE_NAMES[sp.clado], pool:Object.values(CLADE_NAMES),
          why:`Está clasificado dentro del clado ${CLADE_NAMES[sp.clado]}.`,
          tab:'gen' }
      ],
      universitario: [
        { q:`¿Qué material o localidad consigna la ficha de ${sp.nombre}?`,
          a:sp.holo, pool:pool.map(s=>s.holo),
          why:`La ficha consigna ${sp.holo}; no se ha comprobado aquí su condición de holotipo.`,
          tab:'anat' },
        { q:`¿Qué tecnología o cultura se asocia a ${sp.nombre}?`,
          a:sp.herramientas, pool:[...new Set(pool.map(s=>s.herramientas))],
          why:`La ficha registra: ${sp.herramientas}.`,
          tab:'eco' }
      ],
      doctorado: [
        { q:`¿Qué taxón permite discutir este problema: "${(getSpeciesExpert(sp).debate || '').slice(0, 150)}…"?`,
          a:sp.nombre, pool:pool.map(s=>s.nombre),
          why:`La cita procede del bloque de debate de ${sp.nombre}. Evalúa hipótesis, no solo memoria factual.`,
          tab:'biblio' },
        { q:`¿Qué método de datación está asociado a ${sp.nombre}?`,
          a:sp.datacion, pool:[...new Set(pool.map(s=>s.datacion))],
          why:`La ficha registra ${sp.datacion} como método o marco de datación principal.`,
          tab:'anat' }
      ]
    };
    const options = templates[nivelActual] || templates.doctorado;
    const q = options[Math.floor(Math.random() * options.length)];
    return { ...q, _spId: sp.id };
}

async function runGenerativeQuiz() {
    window.PaleoBotStyleState.display(document.getElementById('examIntro'), 'none');
    const examDiv = document.getElementById('examQ');
    window.PaleoBotStyleState.display(examDiv, 'block');
    examDiv.innerHTML = '';

    const pool = getVisibleQuizPool();
    if (pool.length < 2) {
        examDiv.innerHTML = `<p class="quiz-status-copy">No hay suficientes especies visibles para generar un quiz. Amplía el filtro temporal o de clado.</p><button type="button" class="exam-btn" data-quiz-back="intro">Volver</button>`;
        return;
    }
    let q = null;
    const endpoint = window.PALEOBOT_CLAUDE_ENDPOINT;
    if (endpoint) {
      examDiv.innerHTML = `<p class="quiz-status-copy">Solicitando pregunta al endpoint Claude configurado…</p>`;
      try {
        const res = await fetch(endpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            task: 'visible_species_quiz',
            level: nivelActual,
            species: pool.map(sp => ({
              id: sp.id,
              nombre: sp.nombre,
              clado: CLADE_NAMES[sp.clado] || sp.clado,
              anos: A3Temporal.displayMetadata(sp).text,
              ubicacion: sp.ubicacion,
              holo: sp.holo,
              datacion: sp.datacion,
              debate: sp.experto?.debate || ''
            }))
          })
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        if (data.question && data.answer) {
          // FIX C-1: sanitizar respuesta de la API antes de usar en innerHTML
          q = {
            q:    sanitizeText(String(data.question)),
            a:    sanitizeText(String(data.answer)),
            pool: Array.isArray(data.options)
                    ? data.options.map(o => sanitizeText(String(o)))
                    : [sanitizeText(String(data.answer))],
            why:  sanitizeText(String(
                    data.feedback || data.justification ||
                    'Pregunta generada mediante endpoint Claude configurado.'
                  )),
            tab:  'gen',
            _spId: null
          };
        }
      } catch (err) {
        Logger.warn('Quiz Claude no disponible:', err);
      }
    }
    if (!q) q = buildGenerativeQuestion(pool);
    let distractores = [...new Set(q.pool.filter(x => x && x !== q.a))]
        .sort(() => Math.random() - 0.5)
        .slice(0, 3);
    if (distractores.length < 3) {
      distractores = [...new Set([...distractores, ...pool.map(sp => sp.nombre).filter(x => x !== q.a)])]
        .sort(() => Math.random() - 0.5)
        .slice(0, 3);
    }
    const opts = [q.a, ...distractores].sort(() => Math.random() - 0.5);
    const encodedAnswer = encodeURIComponent(q.a).replace(/'/g, '%27');
    const encodedWhy    = encodeURIComponent(q.why).replace(/'/g, '%27');
    const encodedSpId   = encodeURIComponent(q._spId || '').replace(/'/g, '%27');
    const encodedTab    = encodeURIComponent(q.tab || 'gen').replace(/'/g, '%27');

    examDiv.innerHTML = `
      <div class="quiz-card">
        <div class="quiz-card-kicker">Quiz generativo local · ${nivelActual}</div>
        <p class="quiz-card-question">${q.q}</p>
      </div>
      ${opts.map(o => `<button type="button" class="exam-opt" data-quiz-answer="${escapeHtmlAttr(encodedAnswer)}" data-quiz-why="${escapeHtmlAttr(encodedWhy)}" data-quiz-species="${escapeHtmlAttr(encodedSpId)}" data-quiz-tab="${escapeHtmlAttr(encodedTab)}">${escapeHtmlText(o)}</button>`).join('')}
      <p class="quiz-footnote">Se genera desde las especies visibles por búsqueda, clado y filtro temporal.</p>
    `;
}

/**
 * Evalúa la respuesta del quiz generativo y muestra el enlace a la ficha (v26).
 * @param {HTMLElement} btn
 * @param {string} encodedAnswer - Respuesta correcta (encodeURIComponent)
 * @param {string} encodedWhy    - Justificación (encodeURIComponent)
 * @param {string} encodedSpId   - ID de la especie (encodeURIComponent)
 * @param {string} encodedTab    - Pestaña destino (encodeURIComponent)
 */
function answerGenerativeQuiz(btn, encodedAnswer, encodedWhy, encodedSpId, encodedTab) {
    const examDiv = document.getElementById('examQ');
    const answer  = decodeURIComponent(encodedAnswer);
    const why     = decodeURIComponent(encodedWhy);
    const spId    = decodeURIComponent(encodedSpId || '');
    const tabId   = decodeURIComponent(encodedTab  || 'gen') || 'gen';
    const ok      = btn.textContent === answer;
    QuizProgress.record(spId || null, ok, 'generative');
    examDiv.querySelectorAll('.exam-opt').forEach(b => {
      b.disabled = true;
      if (b.textContent === answer) b.classList.add('exam-correct');
    });
    if (!ok) btn.classList.add('exam-wrong');
    const tabLabels = { gen:'General', anat:'Anatomía', eco:'Ecología', biblio:'Investigación' };
    const sp = spId ? DB_INDEX[spId] : null;
    const fb = document.createElement('div');
    fb.className = 'exam-feedback-card';
    fb.innerHTML = `
      <p class="exam-feedback-title strong">${ok ? 'Correcto' : 'Incorrecto'}</p>
      <p class="exam-feedback-body">${why}</p>
      <div class="exam-action-row left">
        <button type="button" class="exam-btn" data-quiz-next="generative">Nueva pregunta generativa</button>
        ${sp ? `<button type="button" class="exam-btn linked"
            data-quiz-open-species="${escapeHtmlAttr(sp.id)}"
            data-quiz-tab="${escapeHtmlAttr(tabId)}"
            title="Ver ficha en pestaña ${escapeHtmlAttr(tabLabels[tabId])}">
            Ver ficha de <em>${escapeHtmlText(sp.nombre)}</em> → ${escapeHtmlText(tabLabels[tabId])}
          </button>` : ''}
      </div>`;
    examDiv.appendChild(fb);
}

