let chartZoom = { minMa: 0, maxMa: 23.5, minCC: 0, maxCC: 1750 };
let chartSelectMode = false;
let chartSelectedIds = null; // null = all selected
let chartHoverSp = null;
let chartData = []; // cached points with pixel coords

function setChartZoom(mode, btn) {
  document.querySelectorAll('.chart-ctrl-btn[id^="zoom-"]').forEach(b => {
    b.classList.remove('active');
    b.setAttribute('aria-pressed', 'false');
  });
  if (btn) {
    btn.classList.add('active');
    btn.setAttribute('aria-pressed', 'true');
  }
  const z = { minCC: 0, maxCC: 1750 };
  if (mode === 'all')   { z.minMa = 0;    z.maxMa = 23.5; }
  if (mode === 'mio')   { z.minMa = 4.5;  z.maxMa = 23.5; z.maxCC = 500; }
  if (mode === 'plio')  { z.minMa = 1.3;  z.maxMa = 5.2;  z.maxCC = 900; }
  if (mode === 'pleis') { z.minMa = 0;    z.maxMa = 2.2;  }
  chartZoom = z;
  drawEncefChart();
}

function toggleSelectMode() {
  chartSelectMode = !chartSelectMode;
  const btn = document.getElementById('btn-select-mode');
  btn.classList.toggle('active', chartSelectMode);
  btn.setAttribute('aria-pressed', chartSelectMode ? 'true' : 'false');
  const canvas = document.getElementById('encefChart');
  canvas.classList.toggle('select-mode', chartSelectMode);
  window.PaleoBotStyleState.display(document.getElementById('btn-reset-sel'), chartSelectMode ? '' : 'none');
  if (!chartSelectMode) {
    chartSelectedIds = null;
    window.PaleoBotStyleState.display(document.getElementById('chart-sel-info'), 'none');
  }
  drawEncefChart();
}

function resetChartSelection() {
  chartSelectedIds = null;
  window.PaleoBotStyleState.display(document.getElementById('chart-sel-info'), 'none');
  drawEncefChart();
}

function linReg(pts) {
  // pts: [{x, y}] — x = val_time, y = cc
  const n = pts.length;
  if (n < 2) return null;
  const sx = pts.reduce((s,p)=>s+p.x,0), sy = pts.reduce((s,p)=>s+p.y,0);
  const sxy = pts.reduce((s,p)=>s+p.x*p.y,0), sxx = pts.reduce((s,p)=>s+p.x*p.x,0);
  const denom = n*sxx - sx*sx;
  if (Math.abs(denom) < 1e-12) return null;
  const m = (n*sxy - sx*sy) / denom;
  const b = (sy - m*sx) / n;
  return { m, b }; // y = m*x + b
}

function drawEncefChart() {
 const canvas=document.getElementById('encefChart');if(!canvas)return;
 const W=canvas.getBoundingClientRect().width||860,H=420,DPR=window.devicePixelRatio||1;
 canvas.width=W*DPR;canvas.height=H*DPR;canvas.classList.add('pb-r74-encef-height-420');
 const ctx=canvas.getContext('2d');ctx.scale(DPR,DPR);
 const PAD={top:20,right:20,bottom:48,left:62},pw=W-PAD.left-PAD.right,ph=H-PAD.top-PAD.bottom;
 const {minMa,maxMa,minCC,maxCC}=chartZoom;
 const xs=ma=>PAD.left+(maxMa-ma)/(maxMa-minMa)*pw,ys=cc=>PAD.top+ph-(cc-minCC)/(maxCC-minCC)*ph;
 const source=A3Temporal.ccSeries(DB.filter(matchesActiveFilters));
 const points=source.points.filter(p=>p.ma>=minMa&&p.ma<=maxMa&&p.cc>=minCC&&p.cc<=maxCC);
 ctx.fillStyle='#faf9f7';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#cbd5e1';ctx.lineWidth=1;
 for(const cc of [0,400,800,1200,1600])if(cc>=minCC&&cc<=maxCC){ctx.beginPath();ctx.moveTo(PAD.left,ys(cc));ctx.lineTo(W-PAD.right,ys(cc));ctx.stroke();ctx.fillStyle='#475569';ctx.fillText(String(cc),8,ys(cc)+4);}
 for(const ma of [0,.1,.3,.5,1,2,5,10,15,20,23])if(ma>=minMa&&ma<=maxMa){ctx.beginPath();ctx.moveTo(xs(ma),PAD.top);ctx.lineTo(xs(ma),H-PAD.bottom);ctx.stroke();ctx.fillStyle='#475569';ctx.textAlign='center';ctx.fillText(ma===0?'Hoy':ma+' Ma',xs(ma),H-27);}
 ctx.fillStyle='#172554';ctx.textAlign='center';ctx.font='11px sans-serif';ctx.fillText('Edad de espécimen (Ma); no duración de taxón',W/2,H-8);
 ctx.save();ctx.translate(14,H/2);ctx.rotate(-Math.PI/2);ctx.fillText('Capacidad craneal (cc)',0,0);ctx.restore();
 chartData=[];
 for(const p of points){
  const sp=DB_INDEX[p.id],cx=xs(p.ma),cy=ys(p.cc),selected=!chartSelectedIds||chartSelectedIds.has(p.id),hover=chartHoverSp?.id===p.id;
  const col=CLADE_COLORS[p.clado]||'#64748b';ctx.save();ctx.globalAlpha=selected?1:.2;
  if(Number.isFinite(p.uncertainty_ka)){
   const a=xs(p.ma+p.uncertainty_ka/1000),b=xs(Math.max(0,p.ma-p.uncertainty_ka/1000));ctx.strokeStyle=col;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(Math.max(PAD.left,a),cy);ctx.lineTo(Math.min(W-PAD.right,b),cy);ctx.stroke();
  }
  ctx.beginPath();ctx.arc(cx,cy,hover?9:7,0,Math.PI*2);ctx.fillStyle=col;ctx.fill();ctx.strokeStyle='white';ctx.stroke();ctx.restore();
  chartData.push({sp,cx,cy,r:8});
 }
 const legend=document.getElementById('chartLegendEnhanced');
 if(legend)legend.innerHTML=`<p class="a3-evidence-note">${escapeHtmlText(a3C42Summary(DB.filter(matchesActiveFilters)))}. ${points.length} puntos de edad puntual con CC. Sin regresión evolutiva; los demás registros no se imputan. La incertidumbre de Kabwe se muestra con su definición publicada.</p>`;
 const info=document.getElementById('chart-hover-info');if(info&&chartHoverSp)info.textContent=a3C42Label(chartHoverSp);
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x+r, y); ctx.lineTo(x+w-r, y);
  ctx.arcTo(x+w, y, x+w, y+r, r);
  ctx.lineTo(x+w, y+h-r); ctx.arcTo(x+w, y+h, x+w-r, y+h, r);
  ctx.lineTo(x+r, y+h); ctx.arcTo(x, y+h, x, y+h-r, r);
  ctx.lineTo(x, y+r); ctx.arcTo(x, y, x+r, y, r);
  ctx.closePath();
}

function exportChartPNG() {
  const canvas = document.getElementById('encefChart');
  if (!canvas) return;
  const link = document.createElement('a');
  link.download = 'paleobot_encefalización.png';
  link.href = canvas.toDataURL('image/png');
  link.click();
}

function abrirEstadisticas() {
  chartZoom = { minMa: 0, maxMa: 23.5, minCC: 0, maxCC: 1750 };
  chartSelectMode = false;
  chartSelectedIds = null;
  chartHoverSp = null;
  document.getElementById('statsModal').classList.add('active');
  // Reset control states
  document.querySelectorAll('.chart-ctrl-btn[id^="zoom-"]').forEach(b => {
    b.classList.remove('active');
    b.setAttribute('aria-pressed', 'false');
  });
  const zAll = document.getElementById('zoom-all');
  if (zAll) {
    zAll.classList.add('active');
    zAll.setAttribute('aria-pressed', 'true');
  }
  const bsm = document.getElementById('btn-select-mode');
  if (bsm) {
    bsm.classList.remove('active');
    bsm.setAttribute('aria-pressed', 'false');
  }
  const brs = document.getElementById('btn-reset-sel');
  if (brs) window.PaleoBotStyleState.display(brs, 'none');
  const csi = document.getElementById('chart-sel-info');
  if (csi) window.PaleoBotStyleState.display(csi, 'none');
  requestAnimationFrame(() => {
    drawEncefChart();
    setupChartInteraction();
  });
}

let _chartInteractionSetup = false;
function setupChartInteraction() {
  if (_chartInteractionSetup) return;
  _chartInteractionSetup = true;
  const canvas = document.getElementById('encefChart');
  if (!canvas) return;

  canvas.addEventListener('mousemove', e => {
    const r = canvas.getBoundingClientRect();
    const mx = e.clientX - r.left, my = e.clientY - r.top;
    let found = null;
    for (const pt of chartData) {
      const d = Math.hypot(pt.cx - mx, pt.cy - my);
      if (d <= pt.r + 3) { found = pt.sp; break; }
    }
    chartHoverSp = found;
    const info = document.getElementById('chart-hover-info');
    if (info) info.textContent = found ? `${found.nombre} · ${found.cc} cc · ${a3C42Label(found)}` : '';
    canvas.classList.toggle('pb-r74-cursor-pointer', !!found);
    canvas.classList.toggle('pb-r74-cursor-crosshair', !found && chartSelectMode);
    canvas.classList.toggle('pb-r74-cursor-default', !found && !chartSelectMode);
    drawEncefChart();
  });

  canvas.addEventListener('mouseleave', () => {
    chartHoverSp = null;
    const info = document.getElementById('chart-hover-info');
    if (info) info.textContent = '';
    drawEncefChart();
  });

  canvas.addEventListener('click', e => {
    const r = canvas.getBoundingClientRect();
    const mx = e.clientX - r.left, my = e.clientY - r.top;
    let found = null;
    for (const pt of chartData) {
      if (Math.hypot(pt.cx - mx, pt.cy - my) <= pt.r + 3) { found = pt.sp; break; }
    }
    if (!found) return;
    if (chartSelectMode) {
      if (!chartSelectedIds) chartSelectedIds = new Set(chartData.map(p => p.sp.id));
      if (chartSelectedIds.has(found.id)) chartSelectedIds.delete(found.id);
      else chartSelectedIds.add(found.id);
      const cnt = chartSelectedIds.size;
      const selInfo = document.getElementById('chart-sel-info');
      const selCnt = document.getElementById('chart-sel-count');
      if (selInfo) window.PaleoBotStyleState.display(selInfo, '');
      if (selCnt) selCnt.textContent = cnt;
      drawEncefChart();
    } else {
      const statsModal = document.getElementById('statsModal');
      if (statsModal?.classList.contains('active')) {
        if (window.PaleoBot && typeof window.PaleoBot.closeModal === 'function') {
          window.PaleoBot.closeModal('statsModal');
        } else if (typeof toggleModal === 'function') {
          toggleModal('statsModal');
        } else {
          statsModal.classList.remove('active');
        }
      }
      openSpeciesViaPublicApiOrService(
        found,
        'stats-encephalization-core',
        { closeModal: false }
      );
    }
  });

  // Resize
  const obs = new ResizeObserver(() => drawEncefChart());
  obs.observe(canvas.parentElement);
}

