function cladeTeachingLabel(clado) {
  return ({ basal: 'Basales / Mioceno', australo: 'Australopithecus', paran: 'Paranthropus', homo: 'Homo' })[clado] || clado || 'Sin clado';
}

function getTeachingDoiCount(sp) {
  // Count DOI strings with valid syntax; no link or bibliographic resolution check.
  const baseRefs = Array.isArray(sp?.experto?.referencias) ? sp.experto.referencias : [];
  const extraRefs = (typeof EXTRA_REFS !== 'undefined' && Array.isArray(EXTRA_REFS[sp.id])) ? EXTRA_REFS[sp.id] : [];
  return [...baseRefs, ...extraRefs].filter(ref => safeDoi(ref.d)).length;
}

function getTeachingCompletenessLabel(sp) {
  const profile = getFossilCompletenessProfile(sp);
  const count = Object.values(profile).filter(Boolean).length;
  if (count >= 3) return { label: 'Alta', cls: 'high', note: `${count}/4 modulos` };
  if (count === 2) return { label: 'Media', cls: 'medium', note: `${count}/4 modulos` };
  return { label: 'Baja', cls: 'low', note: `${count}/4 modulos` };
}

function getTeachingGenomicsLabel(sp) {
  const directIds = (typeof GENOMICS_DATA !== 'undefined' && Array.isArray(GENOMICS_DATA))
    ? new Set(GENOMICS_DATA.map(item => item.id))
    : new Set();
  if (directIds.has(sp.id)) return 'ADN/proteomica directa o contextual';
  return 'Sin datos genomicos directos';
}

function getTeachingProteomicsLabel(sp) {
  if (typeof getPaleoproteomicsProfile !== 'function') return 'Sin datos paleoproteómicos directos';
  const profile = getPaleoproteomicsProfile(sp);
  if (profile.status === 'directa') return 'Paleoproteómica directa';
  if (profile.status === 'contextual') return 'Paleoproteómica contextual / posible';
  return 'Sin datos paleoproteómicos directos';
}

function buildTeachingDataset(species = DB.filter(matchesActiveFilters)) {
  return species.map(sp => {
    const chronology = A3Temporal.exportChronology(sp);
    const completeness = getTeachingCompletenessLabel(sp);
    const expert = getSpeciesExpert(sp);
    const confidence = Object.fromEntries(getInferenceConfidenceProfile(sp, expert).map(item => [item.label, item.level]));
    return {
      id: sp.id,
      taxon: sp.nombre,
      clado: cladeTeachingLabel(sp.clado),
      cronologia: chronology.texto,
      cronologia_estado: chronology.source_status,
      cronologia_tipo: chronology.kind,
      inicio_ma: chronology.single_interval_ma?.old ?? '',
      fin_ma: chronology.single_interval_ma?.young ?? '',
      ubicacion: sp.ubicacion || '',
      material_localidad_sin_tipo_verificado: sp.holo || '',
      datacion: sp.datacion || '',
      evidencia: completeness.label,
      modulos_fosiles: completeness.note,
      paleogenomica: getTeachingGenomicsLabel(sp),
      paleoproteomica: getTeachingProteomicsLabel(sp),
      doi_consignados: getTeachingDoiCount(sp),
      confianza_cronologia: confidence.Cronología || '',
      confianza_anatomia: confidence.Anatomía || '',
      confianza_taxonomia: confidence.Taxonomía || '',
      confianza_conducta_cultura: confidence['Conducta/cultura'] || '',
      confianza_paleogenomica: confidence.Paleogenómica || '',
      debate_abierto: expert.debate || ''
    };
  });
}

function teachingRowsToCSV(rows) {
  const headers = ['id','taxon','clado','cronologia','inicio_ma','fin_ma','ubicacion','material_localidad_sin_tipo_verificado','datacion','evidencia','modulos_fosiles','paleogenomica','paleoproteomica','doi_consignados','confianza_cronologia','confianza_anatomia','confianza_taxonomia','confianza_conducta_cultura','confianza_paleogenomica','debate_abierto'];
  const esc = value => `"${String(value ?? '').replace(/"/g, '""')}"`;
  return [headers.join(','), ...rows.map(row => headers.map(h => esc(row[h])).join(','))].join('\n');
}

function exportTeachingDatasetCSV() {
  const rows = buildTeachingDataset();
  if (!rows.length) { alert('No hay taxones visibles para exportar. Ajusta filtros o búsqueda.'); return; }
  PaleoBot.ExportManager.downloadFile(
    teachingRowsToCSV(rows),
    'paleobot_banco_datos_docente_' + new Date().toISOString().slice(0,10) + '.csv',
    'text/csv;charset=utf-8;'
  );
}

function buildTeachingGuideText() {
  const visible = DB.filter(matchesActiveFilters);
  const lines = [
    'PaleoBot - Guía docente e investigadora',
    'Fecha: ' + new Date().toISOString().slice(0,10),
    '',
    'Taxones visibles: ' + visible.length,
    'Filtro de clado: ' + (cladoFilter === 'all' ? 'todos' : cladeTeachingLabel(cladoFilter)),
    'Intervalo temporal: ' + timeFilter.old + '-' + timeFilter.young + ' Ma',
    '',
    'MATERIALES POR NIVEL'
  ];
  TEACHING_MATERIALS.forEach(item => {
    lines.push('', item.level + ' - ' + item.title, 'Objetivo: ' + item.objective, 'Producto: ' + item.product, 'Criterios: ' + item.assessment.join(' | '));
  });
  lines.push('', 'SECUENCIA DIDÁCTICA BREVE');
  TEACHING_CLASS_SEQUENCE.forEach(item => {
    lines.push('', item.session + ' - ' + item.focus, 'Docente: ' + item.teacher, 'Alumnado: ' + item.student, 'Evidencia: ' + item.evidence);
  });
  lines.push('', 'RUTINA AERC DE ARGUMENTACIÓN CIENTÍFICA');
  TEACHING_ARGUMENT_ROUTINE.forEach(item => {
    lines.push('', item.step + ' - ' + item.title, 'Consigna: ' + item.prompt, 'Ejemplo: ' + item.example, 'Comprobacion: ' + item.check);
  });
  lines.push('', 'SEMÁFORO DE IDEAS PREVIAS Y ERRORES FRECUENTES');
  TEACHING_MISCONCEPTION_CHECKS.forEach(item => {
    lines.push('', 'Idea previa: ' + item.misconception, 'Correccion: ' + item.correction, 'Evidencia para reconducir: ' + item.evidence, 'Microtarea: ' + item.prompt);
  });
  lines.push('', 'TICKETS DE SALIDA METACOGNITIVOS');
  TEACHING_EXIT_TICKETS.forEach(item => {
    lines.push('', item.level + ' - ' + item.title, 'Finalidad: ' + item.purpose, 'Preguntas: ' + item.prompts.join(' | '));
  });
  lines.push('', 'COEVALUACION RÁPIDA ENTRE PARES');
  TEACHING_PEER_REVIEW.forEach(item => {
    lines.push('', item.title, 'Pregunta: ' + item.question, 'Feedback: ' + item.feedback, 'Niveles: ' + item.levels.join(' / '));
  });
  lines.push('', 'AUDITORIA DIDÁCTICA POR PARTES DEL ATLAS');
  getTeachingSectionAuditRows().forEach(row => {
    lines.push(
      '',
      row.title + ' [' + row.family + ']',
      'Fortaleza: ' + row.strength,
      'Riesgo didáctico: ' + row.risk,
      'Mejora accionable: ' + row.improvement,
      'Producto evaluable: ' + row.product,
      'Prioridad: ' + row.priority
    );
  });
  lines.push('', 'BANCO DE ACTIVIDADES EVALUABLES');
  TEACHING_ACTIVITY_BANK.forEach(item => {
    lines.push('', item.level + ' - ' + item.title, 'Reto: ' + item.prompt, 'Producto: ' + item.product, 'Evidencia: ' + item.evidence, 'Vista de apoyo: ' + item.view);
  });
  lines.push('', 'COMPARADOR DE HIPÓTESIS CIENTÍFICAS');
  SCIENTIFIC_HYPOTHESIS_COMPARATOR.forEach(model => {
    lines.push('', model.title, 'Hipotesis: ' + model.claim, 'Evidencia: ' + model.evidence, 'Prueba: ' + model.test, 'Vistas: ' + model.views.join(', '));
  });
  lines.push('', 'ANDAMIAJES Y ADAPTACIONES DE ACCESO');
  TEACHING_ACCESS_SUPPORTS.forEach(item => {
    lines.push('', item.profile, 'Objetivo: ' + item.goal, 'Apoyos: ' + item.supports.join(' | '), 'Cautela: ' + item.warning);
  });
  lines.push('', 'RÚBRICA COMPETENCIAL');
  TEACHING_COMPETENCY_RUBRIC.forEach(item => {
    lines.push('', item.criterion, 'Inicial: ' + item.basic, 'Adecuado/avanzado: ' + item.advanced, 'Experto: ' + item.expert);
  });
  lines.push('', 'RUTAS DE INVESTIGACIÓN');
  TEACHING_RESEARCH_ROUTES.forEach(route => {
    lines.push('', route.title, 'Pregunta: ' + route.question, 'Datos: ' + route.data, 'Vistas: ' + route.views.join(', '));
  });
  lines.push('', 'PLANTILLAS DESCARGABLES');
  TEACHING_DOWNLOADABLE_TEMPLATES.forEach(template => {
    lines.push('', template.title, 'Publico: ' + template.audience, 'Finalidad: ' + template.purpose, 'Apartados: ' + template.sections.join(' | '));
  });
  return lines.join('\n');
}

function exportTeachingGuideTXT() {
  PaleoBot.ExportManager.downloadFile(
    buildTeachingGuideText(),
    'paleobot_guia_docente_' + new Date().toISOString().slice(0,10) + '.txt',
    'text/plain;charset=utf-8;'
  );
}

function buildTeachingTemplateText(templateId) {
  const template = TEACHING_DOWNLOADABLE_TEMPLATES.find(item => item.id === templateId);
  if (!template) return '';
  const visible = buildTeachingDataset().slice(0, 8);
  const lines = [
    'PaleoBot - ' + template.title,
    'Publico recomendado: ' + template.audience,
    'Finalidad: ' + template.purpose,
    'Fecha: ' + new Date().toISOString().slice(0,10),
    '',
    'INSTRUCCIONES',
    'Completa cada apartado con evidencia visible en PaleoBot. Distingue siempre dato observado, inferencia e incertidumbre.',
    '',
    'APARTADOS'
  ];
  template.sections.forEach((section, index) => {
    lines.push(`${index + 1}. ${section}`, 'Respuesta / evidencia:', '');
  });
  if (visible.length) {
    lines.push('TAXONES VISIBLES SUGERIDOS');
    visible.forEach(row => lines.push('- ' + row.taxon + ' | ' + row.cronologia + ' | ' + row.ubicacion + ' | evidencia ' + row.evidencia + ' | confianza anatomía ' + row.confianza_anatomia + ' | confianza taxonomía ' + row.confianza_taxonomia));
  }
  lines.push('', 'CRITERIO DE CALIDAD', 'La respuesta debe citar al menos una ficha, un yacimiento o mapa, distinguir dato directo/inferencia y justificar la confianza de dos afirmaciones.');
  return lines.join('\n');
}

function exportTeachingTemplateTXT(templateId) {
  const template = TEACHING_DOWNLOADABLE_TEMPLATES.find(item => item.id === templateId);
  const text = buildTeachingTemplateText(templateId);
  if (!template || !text) { alert('No se encontro la plantilla solicitada.'); return; }
  PaleoBot.ExportManager.downloadFile(
    text,
    'paleobot_plantilla_' + template.id + '_' + new Date().toISOString().slice(0,10) + '.txt',
    'text/plain;charset=utf-8;'
  );
}

