function auditInteractiveControls(root = document) {
  const buttons = Array.from(root.querySelectorAll('button'));
  const selectorList = INTERACTIVE_BUTTON_CONTRACTS.join(',');
  const issues = buttons.filter(btn => {
    if (btn.disabled || btn.getAttribute('type') === 'submit' || btn.hasAttribute('onclick')) return false;
    return !btn.matches(selectorList);
  }).map(btn => {
    const label = (btn.textContent || btn.getAttribute('aria-label') || btn.className || 'botón sin etiqueta')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, 80);
    return label || 'botón sin etiqueta';
  });
  return { total: buttons.length, ok: buttons.length - issues.length, issues };
}

function getActionContractMap() {
  return {
    /* R94: exportaciones SVG del módulo v66 (063). Sin estas entradas, el delegado
       general de data-action anulaba el clic y no se descargaba nada. */
    exportPhyloSvg: function() { if (typeof window.exportPhyloSvg === 'function') window.exportPhyloSvg(); },
    exportBuilderSvg: function() { if (typeof window.exportBuilderSvg === 'function') window.exportBuilderSvg(); },
    openPresentation,
    startExam,
    openGlossary,
    openMatrix,
    abrirEstadisticas,
    abrirBiblio,
    exportToCSV,
    printFicha,
    runSelfAudit,
    resetGlobalFilters,
    scrollToTop,
    activateClassMode,
    exportQuizProgress,
    /* v59: guía del alumnado */
    openStudentGuide: typeof openStudentGuide === 'function' ? openStudentGuide : function() {
      if (typeof window.openStudentGuide === 'function') window.openStudentGuide();
    },
  };
}

function auditButtonConnectivity(root = document) {
  const buttons = Array.from(root.querySelectorAll('button'));
  const actionContracts = getActionContractMap();
  const issues = [];
  buttons.forEach(btn => {
    const label = (btn.textContent || btn.getAttribute('aria-label') || btn.className || 'botón sin etiqueta')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, 80) || 'botón sin etiqueta';
    if (btn.dataset.view && !document.getElementById('view-' + btn.dataset.view)) {
      issues.push(`${label}: vista no encontrada (${btn.dataset.view})`);
    }
    if (btn.dataset.action && typeof actionContracts[btn.dataset.action] !== 'function') {
      issues.push(`${label}: acción no conectada (${btn.dataset.action})`);
    }
    if (btn.dataset.navFamily && !NAV_FAMILY_META[btn.dataset.navFamily]) {
      issues.push(`${label}: familia no encontrada (${btn.dataset.navFamily})`);
    }
    if (btn.dataset.backAction !== undefined && typeof navigateBack !== 'function') {
      issues.push(`${label}: volver no conectado`);
    }
  });
  return { total: buttons.length, ok: buttons.length - issues.length, issues };
}

function auditFloatingPanelControls(root = document) {
  const buttons = Array.from(root.querySelectorAll('.fab-group button'));
  const actionContracts = getActionContractMap();
  const issues = [];
  buttons.forEach(btn => {
    const label = (btn.getAttribute('aria-label') || btn.textContent || 'botón flotante sin etiqueta')
      .replace(/\s+/g, ' ')
      .trim();
    if (btn.dataset.action && typeof actionContracts[btn.dataset.action] !== 'function') {
      issues.push(`${label}: acción no conectada (${btn.dataset.action})`);
    } else if (btn.dataset.modalToggle && !document.getElementById(btn.dataset.modalToggle)) {
      issues.push(`${label}: modal no encontrado (${btn.dataset.modalToggle})`);
    } else if (!btn.dataset.action && !btn.dataset.modalToggle) {
      issues.push(`${label}: sin destino`);
    }
  });
  const panel = root.querySelector('.fab-group');
  if (!panel) issues.push('Panel flotante no encontrado');
  const zIndex = panel ? Number.parseInt(getComputedStyle(panel).zIndex, 10) : 0;
  if (panel && Number.isFinite(zIndex) && zIndex < 500) {
    issues.push(`Panel flotante con prioridad visual insuficiente (${zIndex})`);
  }
  return { total: buttons.length, ok: buttons.length - issues.length, issues };
}

function auditButtonTypeSafety(root = document) {
  const buttons = Array.from(root.querySelectorAll('button'));
  const missingType = buttons.filter(btn => !btn.hasAttribute('type')).map(btn => {
    const label = (btn.textContent || btn.getAttribute('aria-label') || btn.className || 'botón sin etiqueta')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, 80);
    return label || 'botón sin etiqueta';
  });
  return { total: buttons.length, missingType };
}

function normalizeButtonTypes(root = document) {
  root.querySelectorAll('button:not([type])').forEach(btn => {
    btn.setAttribute('type', 'button');
  });
}

function syncKnownPressedStates(root = document) {
  [
    '.view-btn',
    '.filter-chip',
    '.map-layer-btn',
    '.chart-ctrl-btn[id^="zoom-"]',
    '.bib-filter-btn',
    '.nav-family-btn',
    '.nav-objective'
  ].forEach(selector => {
    root.querySelectorAll(selector).forEach(btn => {
      btn.setAttribute('aria-pressed', btn.classList.contains('active') ? 'true' : 'false');
    });
  });
  const selectModeBtn = root.getElementById?.('btn-select-mode') || document.getElementById('btn-select-mode');
  if (selectModeBtn) {
    selectModeBtn.setAttribute('aria-pressed', selectModeBtn.classList.contains('active') ? 'true' : 'false');
  }
}

function watchDynamicButtonTypes() {
  normalizeButtonTypes();
  if (!window.MutationObserver || !document.body) return;
  const observer = new MutationObserver(mutations => {
    mutations.forEach(mutation => {
      mutation.addedNodes.forEach(node => {
        if (!(node instanceof HTMLElement)) return;
        if (node.matches?.('button:not([type])')) node.setAttribute('type', 'button');
        normalizeButtonTypes(node);
      });
    });
  });
  observer.observe(document.body, { childList: true, subtree: true });
}

function auditRenderedImageAltText(root = document) {
  const images = Array.from(root.querySelectorAll('img'));
  const missingAlt = images.filter(img => !img.hasAttribute('alt')).map(img => {
    return (img.currentSrc || img.src || img.className || 'imagen sin identificar')
      .toString()
      .slice(0, 90);
  });
  return { total: images.length, missingAlt };
}

function auditPressedStateControls(root = document) {
  const candidates = Array.from(root.querySelectorAll('.active, .on, [aria-pressed]'))
    .filter(el => el.matches('button,[role="button"]'));
  const missingState = candidates.filter(el => !el.hasAttribute('aria-pressed')).map(el => {
    return (el.textContent || el.getAttribute('aria-label') || el.className || 'control sin etiqueta')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, 80);
  });
  return { total: candidates.length, missingState };
}

function auditDomIdSafety() {
  const unsafeSpeciesIds = DB
    .map(sp => sp.id)
    .filter(id => safeDomIdPart(id) !== String(id));
  return { total: DB.length, unsafeSpeciesIds };
}

function auditDidacticScientificImprovements() {
  const sampleRow = buildTeachingDataset(DB.slice(0, 1))[0] || {};
  const checks = [
    ['evidencia vs interpretación', typeof renderEvidenceInterpretationPanel === 'function'],
    ['escala de confianza', typeof renderConfidenceScale === 'function'],
    ['comparador de hipótesis', Array.isArray(SCIENTIFIC_HYPOTHESIS_COMPARATOR) && SCIENTIFIC_HYPOTHESIS_COMPARATOR.length >= 5],
    ['actividades por nivel', Array.isArray(TEACHING_ACTIVITY_BANK) && TEACHING_ACTIVITY_BANK.length >= 6],
    ['bibliografía comentada', typeof getReferenceTeachingNote === 'function'],
    ['confianza exportable', 'confianza_anatomia' in sampleRow && 'confianza_taxonomia' in sampleRow],
    ['agenda de investigación por taxón', typeof renderResearchAgendaPanel === 'function' && typeof getResearchGapProfile === 'function'],
    ['guía visual de uso', Boolean(document.querySelector('.visual-use-guide'))],
    ['protocolo de verificación científica', typeof renderScientificVerificationProtocol === 'function' && Array.isArray(SCIENTIFIC_VERIFICATION_PROTOCOL) && SCIENTIFIC_VERIFICATION_PROTOCOL.length >= 6],
    ['trazabilidad de fuentes por ficha', typeof renderSourceTraceabilityPanel === 'function' && typeof getSourceTraceabilityProfile === 'function'],
    ['matriz de riesgo de afirmaciones', typeof renderScientificClaimRiskMatrix === 'function' && Array.isArray(SCIENTIFIC_CLAIM_RISK_MATRIX) && SCIENTIFIC_CLAIM_RISK_MATRIX.length >= 4],
    ['dispersión asiática verificada', typeof renderAsiaView === 'function' && Array.isArray(ASIA_CASES) && ASIA_CASES.length >= 5 && Array.isArray(ASIA_SOURCES) && ASIA_SOURCES.length >= 6],
    ['poblamiento europeo verificado', typeof renderEuropeView === 'function' && Array.isArray(EUROPE_CASES) && EUROPE_CASES.length >= 5 && Array.isArray(EUROPE_SOURCES) && EUROPE_SOURCES.length >= 7],
    ['entrada por perfiles rediseñada', Boolean(document.querySelector('.design-entry-panel'))],
    ['navegación por objetivos', Boolean(document.querySelector('.nav-objective-strip'))],
    ['modo clase funcional', typeof activateClassMode === 'function' && Boolean(document.querySelector('[data-action="activateClassMode"]'))],
    ['ficha rápida de especie', typeof renderPlainLanguageSummary === 'function'],
    ['verificación global ciencia didáctica diseño', typeof renderGlobalQualityDashboard === 'function' && Array.isArray(GLOBAL_QUALITY_AUDIT) && GLOBAL_QUALITY_AUDIT.length === 3],
    ['estructura visual simplificada', Boolean(document.querySelector('.atlas-workbench'))],
    ['portada principal independiente', Boolean(document.querySelector('.main-cover')) && !document.querySelector('.main-cover')?.closest('.container')]
  ];
  const missing = checks.filter(([, ok]) => !ok).map(([label]) => label);
  return { total: checks.length, missing };
}

function buildSelfAuditReport() {
  normalizeButtonTypes();
  syncKnownPressedStates();
  const buttonViews = Array.from(document.querySelectorAll('[data-view]'))
    .map(el => el.dataset.view)
    .filter(Boolean);
  const uniqueViews = [...new Set(buttonViews)];
  const missingViewSections = uniqueViews.filter(view => !document.getElementById('view-' + view));
  const ids = Array.from(document.querySelectorAll('[id]')).map(el => el.id).filter(Boolean);
  const duplicatedIds = Object.entries(ids.reduce((acc, id) => {
    acc[id] = (acc[id] || 0) + 1;
    return acc;
  }, {})).filter(([, count]) => count > 1).map(([id, count]) => `${id} (${count})`);
  const templateIds = new Set(TEACHING_DOWNLOADABLE_TEMPLATES.map(item => item.id));
  const missingStaticTemplates = Array.from(document.querySelectorAll('[data-teaching-export]'))
    .map(el => el.dataset.teachingExport || '')
    .filter(value => value.startsWith('template:'))
    .map(value => value.split(':')[1])
    .filter(id => !templateIds.has(id));
  const mediaAudit = auditSpeciesMedia();
  const controlAudit = auditInteractiveControls();
  const connectivityAudit = auditButtonConnectivity();
  const floatingPanelAudit = auditFloatingPanelControls();
  const buttonTypeAudit = auditButtonTypeSafety();
  const imageAltAudit = auditRenderedImageAltText();
  const pressedStateAudit = auditPressedStateControls();
  const domIdAudit = auditDomIdSafety();
  const didacticAudit = auditDidacticScientificImprovements();
  const didacticAuditSummary = 'evidencia, confianza, hipótesis, actividades, bibliografía comentada, trazabilidad por ficha, dispersión asiática/europea, verificación global y estructura visual simplificada';
  const doiTotal = DB.reduce((sum, sp) => sum + getTeachingDoiCount(sp), 0);
  const directGenomics = DB.filter(sp => getTeachingGenomicsLabel(sp) !== 'Sin datos genomicos directos').length;
  return [
    { label: 'Vistas navegables', status: missingViewSections.length ? 'bad' : 'ok', value: missingViewSections.length ? 'Faltan: ' + missingViewSections.join(', ') : `${uniqueViews.length} vistas con sección asociada.` },
    { label: 'Botones funcionales', status: controlAudit.issues.length ? 'bad' : 'ok', value: controlAudit.issues.length ? 'Sin contrato: ' + controlAudit.issues.join(' | ') : `${controlAudit.ok}/${controlAudit.total} botones del DOM actual con contrato funcional.` },
    { label: 'Botones interconectados', status: connectivityAudit.issues.length ? 'bad' : 'ok', value: connectivityAudit.issues.length ? connectivityAudit.issues.join(' | ') : `${connectivityAudit.ok}/${connectivityAudit.total} botones enlazan con una vista, acción o familia real.` },
    { label: 'Panel flotante', status: floatingPanelAudit.issues.length ? 'bad' : 'ok', value: floatingPanelAudit.issues.length ? floatingPanelAudit.issues.join(' | ') : `${floatingPanelAudit.ok}/${floatingPanelAudit.total} botones flotantes con destino real y capa interactiva correcta.` },
    { label: 'Tipos de botón', status: buttonTypeAudit.missingType.length ? 'warn' : 'ok', value: buttonTypeAudit.missingType.length ? `${buttonTypeAudit.missingType.length}/${buttonTypeAudit.total} botones sin type explícito. No hay formularios activos, pero conviene tiparlos si se integran formularios.` : 'Todos los botones declaran type explícito.' },
    { label: 'Estados pulsados', status: pressedStateAudit.missingState.length ? 'warn' : 'ok', value: pressedStateAudit.missingState.length ? `${pressedStateAudit.missingState.length}/${pressedStateAudit.total} controles activos sin aria-pressed: ${pressedStateAudit.missingState.join(' | ')}` : `${pressedStateAudit.total} controles con estado activo exponen aria-pressed.` },
    { label: 'Identificadores DOM', status: duplicatedIds.length ? 'warn' : 'ok', value: duplicatedIds.length ? duplicatedIds.join(' | ') : 'Sin duplicados reales en el DOM actual.' },
    { label: 'IDs de datos', status: domIdAudit.unsafeSpeciesIds.length ? 'warn' : 'ok', value: domIdAudit.unsafeSpeciesIds.length ? `Normalización DOM activa para: ${domIdAudit.unsafeSpeciesIds.join(', ')}` : `${domIdAudit.total} IDs de taxón compatibles con DOM directo.` },
    { label: 'Mejoras didácticas/científicas', status: didacticAudit.missing.length ? 'bad' : 'ok', value: didacticAudit.missing.length ? 'Faltan: ' + didacticAudit.missing.join(', ') : `${didacticAudit.total}/${didacticAudit.total} mejoras activas: ${didacticAuditSummary}.` },
    { label: 'Texto alternativo', status: imageAltAudit.missingAlt.length ? 'bad' : 'ok', value: imageAltAudit.missingAlt.length ? `${imageAltAudit.missingAlt.length}/${imageAltAudit.total} imagen(es) renderizadas sin alt: ${imageAltAudit.missingAlt.join(' | ')}` : `${imageAltAudit.total} imagen(es) renderizadas con alt declarado.` },
    { label: 'Plantillas docentes', status: missingStaticTemplates.length ? 'bad' : 'ok', value: missingStaticTemplates.length ? 'No encontradas: ' + missingStaticTemplates.join(', ') : `${TEACHING_DOWNLOADABLE_TEMPLATES.length} plantillas disponibles.` },
    { label: 'Imágenes de fichas', status: mediaAudit.issues.length ? 'bad' : 'ok', value: `${mediaAudit.ok}/${mediaAudit.total} taxones con imagen, miniatura y fuente.` },
    { label: 'Licencias visuales', status: mediaAudit.warnings.length ? 'warn' : 'ok', value: mediaAudit.warnings.length ? `${mediaAudit.warnings.length} imagen(es) con reutilización por revisar: ${mediaAudit.warnings.map(item => item.nombre).join(', ')}.` : 'Todas las imágenes tienen licencia abierta trazable.' },
    { label: 'DOI trazables', status: doiTotal ? 'ok' : 'warn', value: `${doiTotal} DOI asociados al conjunto de fichas y referencias.` },
    { label: 'Paleogenómica', status: directGenomics ? 'ok' : 'warn', value: `${directGenomics} taxones con lectura paleogenómica directa, contextual o indirecta.` }
  ];
}

function renderSelfAuditReport(report = buildSelfAuditReport()) {
  return `<div class="teaching-audit-panel">
    <h4>Diagnóstico técnico rápido</h4>
    <p class="pb-r70-gen-9a121dfd1c" >Comprobación local ejecutada en el navegador: navegación, botones, estados pulsados, duplicados reales, IDs de datos, mejoras didácticas/científicas, texto alternativo, plantillas, imágenes, licencias visuales, DOI y paleogenómica.</p>
    <div class="teaching-audit-list">${report.map(item => `<div class="teaching-audit-item teaching-audit-${escapeHtmlAttr(item.status)}">
      <strong>${escapeHtmlText(item.label)}</strong>${escapeHtmlText(item.value)}
    </div>`).join('')}</div>
  </div>`;
}

function runSelfAudit() {
  const report = buildSelfAuditReport();
  const host = document.getElementById('teachingAuditReport');
  if (host) {
    host.innerHTML = renderSelfAuditReport(report);
    host.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    return;
  }
  alert(report.map(item => `${item.label}: ${item.value}`).join('\n'));
}

