let currentItinerary = null;
let currentStop = 0;

function getItineraryCatalogSnapshot() {
  return ITINERARIES.map(itin => ({
    id: itin.id,
    title: itin.title,
    color: itin.color,
    intro: itin.intro,
    stops: itin.stops.map(stop => ({ id: stop.id, transition: stop.transition }))
  }));
}

function getItineraryStateSnapshot() {
  if (!currentItinerary) {
    return {
      selected: false,
      itineraryId: null,
      currentStop: null,
      totalStops: 0,
      currentSpeciesId: null,
      completed: false
    };
  }
  const stop = currentItinerary.stops[currentStop] || null;
  return {
    selected: true,
    itineraryId: currentItinerary.id,
    title: currentItinerary.title,
    currentStop,
    totalStops: currentItinerary.stops.length,
    currentSpeciesId: stop ? stop.id : null,
    completed: currentStop === currentItinerary.stops.length - 1
  };
}

function selectItinerary(idx) {
  const index = Number(idx);
  if (!Number.isInteger(index) || index < 0 || index >= ITINERARIES.length) return false;

  document.querySelectorAll('.itin-btn').forEach((b, i) => {
    const active = i === index;
    b.classList.toggle('active', active);
    b.setAttribute('aria-pressed', String(active));
  });
  currentItinerary = ITINERARIES[index];
  currentStop = 0;
  renderItinStop();
  return true;
}

function renderItinStop() {
  const itin = currentItinerary;
  if (!itin) return;
  const stop = itin.stops[currentStop];
  const sp = DB.find(s => s.id === stop.id);
  if (!sp) return;

  const total = itin.stops.length;
  const pct = ((currentStop + 1) / total) * 100;
  const CLADE_NM = {basal:'Basales/Mioceno',australo:'Australopithecus',paran:'Paranthropus',homo:'Homo'};
  const CLADE_BG = {basal:'#fdf3e0',australo:'#e8f8f1',paran:'#fdecea',homo:'#e8edf8'};
  const itinVars = `--itin-color:${escapeHtmlAttr(itin.color)};--itin-soft:${escapeHtmlAttr(CLADE_BG[sp.clado] || 'var(--accent-light)')}`;

  const shortDesc = sp.descripcion ? sp.descripcion.slice(0, 380) + (sp.descripcion.length > 380 ? '…' : '') : '';

  document.getElementById('itinBody').innerHTML = `
    <div class="itin-run" data-pb-r71-style="${itinVars}">
    <div class="itin-progress-label">
      <span class="itin-progress-title">${itin.title}</span>
      <span>Parada ${currentStop + 1} de ${total}</span>
    </div>
    <div class="itin-progress-bar"><div class="itin-progress-fill" data-pb-r71-style="width:${pct}%"></div></div>

    ${currentStop === 0 ? `<div class="itin-transition visible accented"><strong>Presentación del itinerario:</strong> ${itin.intro}</div>` : ''}
    ${currentStop > 0 && stop.transition ? `<div class="itin-transition visible linked">${stop.transition}</div>` : ''}

    <div class="itin-card accented">
      <img class="itin-card-img" src="${getSpeciesThumb(sp, 500)}" alt="${escapeHtmlAttr(sp.nombre)}" data-image-error="media" loading="lazy" decoding="async" referrerpolicy="no-referrer">
      <div class="itin-card-body">
        <div class="itin-card-tags">
          <span class="sp-tag">${escapeHtmlText(a3C42Label(sp))}</span>
          <span class="sp-tag itin-clade-tag">${CLADE_NM[sp.clado]||sp.clado}</span>
          <span class="sp-tag itin-location-tag">📍 ${sp.ubicacion}</span>
          ${sp.cc ? `<span class="sp-tag">🧠 ${sp.cc} cc</span>` : ''}
          ${sp.herramientas && sp.herramientas !== 'Ninguna' && sp.herramientas !== 'No' ? `<span class="sp-tag">🪨 ${sp.herramientas}</span>` : ''}
        </div>
        <h2 class="itin-card-title">${sp.nombre}</h2>
        <p class="itin-card-desc">${shortDesc}</p>
        <button type="button" class="itin-card-detail-btn" data-open-species="${escapeHtmlAttr(sp.id)}">Ver ficha completa <span class="ico" aria-hidden="true"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg></span></button>
      </div>
    </div>

    <div class="itin-nav">
      <button type="button" class="itin-nav-btn itin-btn-prev" data-itin-nav="-1" ${currentStop === 0 ? 'disabled' : ''}><span class="ico" aria-hidden="true"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><polyline points="15 18 9 12 15 6"/></svg></span> Anterior</button>
      <div class="itin-nav-center">
        ${itin.stops.map((_,i) => `<span class="itin-step-dot ${i === currentStop ? 'active' : ''}"></span>`).join('')}
      </div>
      <button type="button" class="itin-nav-btn itin-btn-next accented" data-itin-nav="1" ${currentStop === total-1 ? 'disabled' : ''}>Siguiente <span class="ico" aria-hidden="true"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><polyline points="9 18 15 12 9 6"/></svg></span></button>
    </div>
    ${currentStop === total-1 ? `
    <div class="itin-complete pb-r70-gen-ce4099f70a" >
      <p class="pb-r70-gen-f93bf46f2d" >✅ Itinerario completado</p>
      <p class="pb-r70-gen-4d08cea486" >Has recorrido ${total} especies con narración evolutiva.</p>
      <div class="pb-r70-gen-148f11ac96" >
        <p class="pb-r70-gen-a88075e042" >📝 Pregunta de síntesis</p>
        <p class="pb-r70-gen-1891971390" >¿Qué dato de este itinerario te ha resultado más sorprendente y por qué? ¿Qué pregunta te ha surgido que el atlas no responde todavía?</p>
        <textarea class="pb-r70-gen-41560ab4c6" id="itinReflection_${itin.id}" rows="3"
          
          placeholder="Escribe aquí tu reflexión (opcional — solo para ti)..."
          aria-label="Reflexión personal sobre el itinerario"></textarea>
      </div>
      <div class="pb-r70-gen-073b0396c8" >
        <button class="pb-r70-gen-ecade3207a" type="button" data-view="africa"
          >
          Continuar → Vista África
        </button>
        <button class="pb-r70-gen-3e0e6912fb" type="button" data-itinerary-select="${itin.id}"
          >
          Repetir itinerario
        </button>
        <button class="pb-r70-gen-a980994d22" type="button" data-itin-export="${itin.id}"
          >
          Exportar reflexión (.txt)
        </button>
      </div>
    </div>` : ''}
    </div>
  `;
}

function itinNav(dir) {
  if (!currentItinerary) return false;
  const numeric = Number(dir);
  if (!Number.isFinite(numeric) || numeric === 0) return false;
  const step = numeric < 0 ? -1 : 1;
  const newStop = currentStop + step;
  if (newStop < 0 || newStop >= currentItinerary.stops.length) return false;
  currentStop = newStop;
  renderItinStop();
  document.getElementById('itinBody')?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  return true;
}


