function getPaleogenomicsProfile(sp) {
  if (PALEOGENOMICS_PROFILES[sp.id]) return PALEOGENOMICS_PROFILES[sp.id];
  if (['sapiens'].includes(sp.id)) return PALEOGENOMICS_PROFILES.sapiens;
  return {
    evidence: 'ausente',
    color: CLADE_COLORS[sp.clado] || '#74685e',
    title: 'Sin datos paleogenómicos directos',
    status: 'No hay ADN antiguo publicado o cargado para esta ficha. La cronología por sí sola no permite decidir preservación molecular.',
    signal: 'La interpretación debe apoyarse en morfología, estratigrafía, datación, paleoproteómica si existe e inferencia comparativa.',
    update: 'La paleogenómica amplía el marco general, pero no añade una señal específica para este taxón sin evidencia molecular directa.',
    didactic: 'Es una oportunidad para enseñar los límites de la evidencia y separar antigüedad, preservación y disponibilidad de biomoléculas.',
    caution: 'No inferir presencia o ausencia de ADN exclusivamente desde una fecha escalar heredada.',
    chips: ['sin ADN directo', 'tafonomía', 'registro fósil', 'cautela'],
    refs: []
  };
}

function renderPaleogenomicsField(sp) {
  const profile = getPaleogenomicsProfile(sp);
  const refs = profile.refs?.length
    ? `<div class="pg-refs"><h4>Referencias paleogenómicas clave</h4><ul class="references-list">${profile.refs.map(renderReferenceListItem).join('')}</ul></div>`
    : `<div class="pg-refs"><h4>Referencias paleogenómicas clave</h4><p class="pb-r70-gen-07062094c7" >No hay una referencia genómica directa para este taxón; revisar literatura morfológica, estratigráfica o paleoproteómica específica.</p></div>`;
  const badgeLabel = {
    alta: 'Evidencia alta',
    media: 'Evidencia media',
    indirecta: 'Evidencia indirecta',
    ausente: 'Sin ADN directo'
  }[profile.evidence] || 'Evidencia';

  return `<section class="paleogenomics-panel" data-pb-r71-style="--pg-color:${escapeHtmlAttr(profile.color)}">
    <div class="paleogenomics-hero">
      <div class="paleogenomics-top">
        <div>
          <h3 class="paleogenomics-title">${escapeHtmlText(profile.title)}</h3>
          <p class="paleogenomics-subtitle">${escapeHtmlText(profile.status)}</p>
        </div>
        <span class="pg-evidence-badge ${escapeHtmlAttr(profile.evidence)}">${escapeHtmlText(badgeLabel)}</span>
      </div>
      <div class="paleogenomics-grid">
        <div class="pg-card"><strong>Señal genética</strong><p>${escapeHtmlText(profile.signal)}</p></div>
        <div class="pg-card"><strong>Actualización reciente</strong><p>${escapeHtmlText(profile.update)}</p></div>
        <div class="pg-card"><strong>Lectura didáctica</strong><p>${escapeHtmlText(profile.didactic)}</p></div>
      </div>
      <div class="pg-chip-row">${(profile.chips || []).map(chip => `<span class="pg-chip">${escapeHtmlText(chip)}</span>`).join('')}</div>
    </div>
    <div class="pg-caution"><strong>Cautela metodológica</strong>${escapeHtmlText(profile.caution)}</div>
    ${refs}
  </section>`;
}

