      <g class="${cls('postcraneo')}">
        <rect x="64" y="72" width="12" height="58" rx="6"/>
        <path d="M40 88 Q70 104 100 88 L95 110 Q70 121 45 110 Z"/>
        <path d="M48 125 Q70 142 92 125 L88 145 Q70 158 52 145 Z"/>
        <rect x="39" y="88" width="10" height="58" rx="5" transform="rotate(17 44 117)"/>
        <rect x="91" y="88" width="10" height="58" rx="5" transform="rotate(-17 96 117)"/>
        <rect x="55" y="145" width="11" height="66" rx="5" transform="rotate(5 60 178)"/>
        <rect x="74" y="145" width="11" height="66" rx="5" transform="rotate(-5 79 178)"/>
      </g>
