function noteStorageKey(id) {
  return `paleobot_notes_${id}`;
}

function clearLocalStudentData() {
  const storage = window.PaleoBotStorage;
  if (!storage) return { ok:false, reason:'storage-adapter-unavailable', notes:0, tickets:0 };

  const noteKeys = storage.persistentKeys('paleobot_notes_');
  const ticketPersistentKeys = storage.persistentKeys('pb_iff_');
  const ticketSessionKeys = storage.sessionKeys('pb_iff_');

  noteKeys.forEach(key => storage.removePersistent(key));
  ticketPersistentKeys.forEach(key => storage.removePersistent(key));
  ticketSessionKeys.forEach(key => storage.removeSession(key));

  document.querySelectorAll('[data-notes-input]').forEach(el => { el.value = ''; });
  document.querySelectorAll('[data-notes-study]').forEach(el => { el.checked = false; });
  document.querySelectorAll('.notes-status').forEach(el => { el.textContent = ''; });

  document.dispatchEvent(new CustomEvent('paleobot:studentdata-cleared', {
    detail: {
      notes: noteKeys.length,
      tickets: new Set([...ticketPersistentKeys, ...ticketSessionKeys]).size,
      scope: storage.namespace()
    }
  }));

  return {
    ok:true,
    notes:noteKeys.length,
    tickets:new Set([...ticketPersistentKeys, ...ticketSessionKeys]).size,
    scope:storage.namespace()
  };
}

window.PaleoBot.studentData = Object.freeze({
  clearLocal: clearLocalStudentData
});

/**
 * Carga las notas del alumno para una especie.
 * R63: usa PaleoBotStorage para aislamiento opcional por recurso Moodle.
 * @param {string} id - ID de la especie
 * @returns {{text: string, studied: boolean, updated: string}}
 */
function getStudentNote(id) {
  try {
    return JSON.parse(window.PaleoBotStorage?.getPersistent(noteStorageKey(id), '{}') || '{}');
  } catch (_) {
    return {};
  }
}

/**
 * Guarda las notas del alumno para una especie.
 * R63: usa PaleoBotStorage — persistencia local con degradación a memoria.
 * @param {string} id - ID de la especie
 */
function saveStudentNotes(id) {
  const domId = safeDomIdPart(id);
  const area    = document.getElementById('studentNotes_'   + domId);
  const studied = document.getElementById('studentStudied_' + domId);
  const data = {
    text:    area    ? area.value           : '',
    studied: studied ? !!studied.checked    : false,
    updated: new Date().toISOString()
  };
  let persisted = false;
  try {
    persisted = window.PaleoBotStorage?.setPersistent(noteStorageKey(id), JSON.stringify(data)) === true;
  } catch (err) {
    persisted = false;
    Logger.warn('No se pudieron persistir las notas:', err?.message || err);
  }
  const status = document.getElementById('studentNotesStatus_' + domId);
  if (status) {
    status.textContent = persisted ? '✓ guardado' : 'guardado solo en esta sesión';
    status.classList.toggle('pb-r74-status-persisted', persisted);
    status.classList.toggle('pb-r74-status-session-only', !persisted);
    setTimeout(() => { status.textContent = ''; }, 2400);
  }
  return persisted;
}

// FIX v23-6: autosave sin necesidad de pulsar botón (debounced 1.2s)
let _noteAutoSaveTimers = {};
function autoSaveStudentNotes(id) {
  clearTimeout(_noteAutoSaveTimers[id]);
  _noteAutoSaveTimers[id] = setTimeout(() => {
    const domId = safeDomIdPart(id);
    const persisted = saveStudentNotes(id);
    const st = document.getElementById(`studentNotesStatus_${domId}`);
    if (st) {
      st.textContent = persisted ? '✓ guardado automáticamente' : 'autoguardado temporal';
      st.classList.toggle('pb-r74-status-persisted', persisted);
      st.classList.toggle('pb-r74-status-session-only', !persisted);
    }
  }, 1200);
}

