let dispersalState = {
  time: 1.9,
  speed: 1,
  playing: false,
  active: { ergaster: true, erectus: true, sapiens: true, denisova: false }
};
let dispersalTimer = null;

function getDispersalRouteIds() {
  return Object.keys(DISPERSAL_ROUTES);
}

function getDispersalRoutesSnapshot() {
  return Object.fromEntries(
    Object.entries(DISPERSAL_ROUTES).map(([id, route]) => [id, {
      label: route.label,
      color: route.color,
      start: route.start,
      end: route.end,
      note: route.note,
      points: route.points.map(point => [...point])
    }])
  );
}

function getDispersalStateSnapshot() {
  return {
    time: dispersalState.time,
    speed: dispersalState.speed,
    playing: dispersalState.playing,
    active: { ...dispersalState.active }
  };
}

function setDispersalRouteActive(id, active) {
  if (!Object.prototype.hasOwnProperty.call(DISPERSAL_ROUTES, id)) return false;
  const target = !!active;
  if (dispersalState.active[id] !== target) {
    dispersalState.active[id] = target;
    renderDispersalSimulator();
  }
  return true;
}

function getPaleoEnvironmentStageForMa(ma) {
  if (ma > 5.3) return { title: 'Mioceno', note: 'Mosaicos boscosos y ambientes abiertos iniciales.', savanna: 0.22, sahara: 0.12, ice: 0.04 };
  if (ma > 2.58) return { title: 'Plioceno', note: 'Expansión C4, estacionalidad y sabanas africanas.', savanna: 0.58, sahara: 0.28, ice: 0.10 };
  if (ma > 0.126) return { title: 'Pleistoceno', note: 'Ciclos glaciales, costas desplazadas y pulsos de aridez.', savanna: 0.52, sahara: 0.62, ice: 0.70 };
  return { title: 'Pleistoceno final-Holoceno', note: 'Glaciares en retroceso y Sahara muy variable.', savanna: 0.42, sahara: 0.52, ice: 0.38 };
}

function routePath(points) {
  return points.map(([lat, lng], i) => {
    const [x, y] = mapProject(lat, lng);
    return `${i ? 'L' : 'M'}${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(' ');
}

function interpolateRoute(route, progress) {
  const pts = route.points.map(([lat, lng]) => mapProject(lat, lng));
  const p = Math.max(0, Math.min(1, progress));
  const totalSegments = pts.length - 1;
  const seg = Math.min(totalSegments - 1, Math.floor(p * totalSegments));
  const local = (p * totalSegments) - seg;
  const a = pts[seg], b = pts[seg + 1];
  return [a[0] + (b[0] - a[0]) * local, a[1] + (b[1] - a[1]) * local];
}

function speciesAliveAt(sp, ma) {
  return A3Temporal.occupancy(sp, ma).established;
}

function renderDispersalSimulator() {
  const el = document.getElementById('dispersalContent');
  if (!el) return;
  el.innerHTML = `
    <div class="sim-controls">
      <button type="button" class="sim-btn" id="simPlayBtn" data-dispersal-play>▶ Reproducir</button>
      <label class="pb-r70-gen-4bca0e604b" >Tiempo
        <input class="sim-range" id="simTimeRange" aria-label="Tiempo de dispersión (Ma)" type="range" min="0" max="1.9" step="0.01" value="${dispersalState.time}" data-dispersal-time>
      </label>
      <label class="pb-r70-gen-4bca0e604b" >Velocidad
        <input class="sim-range" id="simSpeedRange" aria-label="Velocidad de dispersión" type="range" min="0.25" max="4" step="0.25" value="${dispersalState.speed}" data-dispersal-speed>
      </label>
      ${Object.entries(DISPERSAL_ROUTES).map(([id, r]) => `<button type="button" class="sim-btn ${dispersalState.active[id] ? 'active' : ''}" data-dispersal-route="${id}" ${dispersalState.active[id] ? `data-pb-r71-style="background:${r.color};border-color:${r.color}"` : ''}>${r.label}</button>`).join('')}
    </div>
    <div class="sim-board">
      <div class="sim-map-wrap">
        <img class="pb-r70-gen-a526131d82" src="https://server.arcgisonline.com/ArcGIS/rest/services/World_Physical_Map/MapServer/export?f=image&format=png32&bbox=-180%2C-85%2C180%2C85&bboxSR=4326&imageSR=4326&size=2048%2C1024&transparent=false" alt="Mapa físico mundial" >
        <svg class="sim-svg" id="dispersalSvg" viewBox="0 0 1000 500"></svg>
      </div>
      <aside class="sim-info" id="dispersalInfo"></aside>
    </div>`;
  updateDispersalFrame();
}

function updateDispersalFrame() {
  const svg = document.getElementById('dispersalSvg');
  const info = document.getElementById('dispersalInfo');
  if (!svg || !info) return;
  const ma = dispersalState.time;
  const stage = getPaleoEnvironmentStageForMa(ma);
  const env = [
    envEllipse(0, 24, 120, 66, '#b7c66a', stage.savanna, 'sabana'),
    envPolygon([[33,-18],[32,45],[15,52],[12,-15]], '#d8a84d', stage.sahara, 'Sahara', 23, 16)
  ].join('');
  const routes = Object.entries(DISPERSAL_ROUTES).map(([id, route]) => {
    const active = dispersalState.active[id];
    const started = ma <= route.start;
    const progress = (route.start - ma) / (route.start - route.end);
    const [x, y] = interpolateRoute(route, progress);
    return `<path class="sim-route ${active ? '' : 'is-muted'}" d="${routePath(route.points)}" stroke="${route.color}"/>
      ${active && started ? `<circle class="sim-pulse" cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="9" fill="${route.color}" stroke="white" stroke-width="3"><title>${route.label}</title></circle>` : ''}`;
  }).join('');
  svg.innerHTML = `<g class="map-env-layer">${env}</g>${routes}`;

  const regionNames = { africa:'África', europa:'Europa', asia:'Asia', oceania:'Oceanía', global:'Global' };
  const regions = ['africa','europa','asia','oceania'];
  const cards = regions.map(region => {
    const evidence = A3Temporal.regionEvidence(DB, ma, region);
    const entries = evidence.supported.map(t => `${escapeHtmlText(t.name)} (${escapeHtmlText(t.place)}; ventana posible, no presencia demostrada)`);
    return `<div class="sim-region-card"><strong>${regionNames[region]}</strong>${entries.length ? entries.join('; ') : 'Sin soporte temporal puntual cualificado para esta consulta.'}<small> ${evidence.uncertain.length} registros localizados con cronología indeterminada; ${evidence.legacy_unreviewed} fichas no revisadas. No equivale a ausencia histórica.</small></div>`;
  }).join('');
  info.innerHTML = `<h3>Estado de la simulación</h3>
    <div class="sim-time">${formatTimePoint(ma)}</div>
    <p class="pb-r70-gen-ecfae0057a" ><strong>${stage.title}:</strong> ${stage.note}</p>
    <p class="pb-r70-gen-b686f1b5ce" >Simulación didáctica de rutas hipotéticas. La posición de un punto no acredita presencia, ocupación continua, velocidad real ni dirección de una migración. Los registros científicos se muestran por separado.</p>
    <div class="sim-region-list">${cards}</div>`;
  const range = document.getElementById('simTimeRange');
  if (range) range.value = ma;
  const play = document.getElementById('simPlayBtn');
  if (play) play.textContent = dispersalState.playing ? '⏸ Pausar' : '▶ Reproducir';
}

function setDispersalTime(value) {
  const numeric = Number(value);
  dispersalState.time = Number.isFinite(numeric)
    ? Math.max(0, Math.min(1.9, numeric))
    : dispersalState.time;
  updateDispersalFrame();
  return dispersalState.time;
}

function setDispersalSpeed(value) {
  const numeric = Number(value);
  dispersalState.speed = Number.isFinite(numeric)
    ? Math.max(0.25, Math.min(4, numeric))
    : dispersalState.speed;
  return dispersalState.speed;
}

function toggleDispersalRoute(id, btn) {
  if (!Object.prototype.hasOwnProperty.call(DISPERSAL_ROUTES, id)) return null;
  dispersalState.active[id] = !dispersalState.active[id];
  if (btn) btn.classList.toggle('active', dispersalState.active[id]);
  renderDispersalSimulator();
  return dispersalState.active[id];
}

function toggleDispersalPlay() {
  dispersalState.playing = !dispersalState.playing;
  clearInterval(dispersalTimer);
  if (dispersalState.playing) {
    dispersalTimer = setInterval(() => {
      dispersalState.time = +(dispersalState.time - 0.01 * dispersalState.speed).toFixed(3);
      if (dispersalState.time <= 0) {
        dispersalState.time = 0;
        dispersalState.playing = false;
        clearInterval(dispersalTimer);
      }
      updateDispersalFrame();
    }, 120);
  }
  updateDispersalFrame();
  return dispersalState.playing;
}

function setDispersalPlaying(playing) {
  const target = !!playing;
  if (dispersalState.playing !== target) toggleDispersalPlay();
  return dispersalState.playing;
}

