/** Estado del laboratorio de estratigrafía */
let _stratState = { site: 'atapuerca', selectedLayer: null, inferenceMode: false, compareMode: false };

/**
 * Construye el panel de comparación entre todos los yacimientos disponibles.
 * Muestra: capas totales, rango temporal, taxones homininos representados y métodos de datación.
 * @returns {string} HTML del panel de comparación
 */
function _buildStratComparePanel() {
  const profiles = Object.values(STRATIGRAPHY_PROFILES);
  const rows = profiles.map(p => {
    const ages = p.layers.map(l => l.age_ka).filter(Boolean);
    const minAge = ages.length ? Math.min(...ages) : 0;
    const maxAge = ages.length ? Math.max(...ages) : 0;
    const allTaxa = [...new Set(p.layers.flatMap(l => l.taxa || []))].filter(Boolean);
    const allMethods = [...new Set(p.layers.map(l => l.method).filter(Boolean))];
    const hasDebated = p.layers.some(l => l.age_label && l.age_label.includes('[DEBATIDO]'));
    return { p, minAge, maxAge, allTaxa, allMethods, hasDebated };
  });

  const tableRows = rows.map(({ p, minAge, maxAge, allTaxa, allMethods, hasDebated }) => `
    <tr>
      <td class="pb-r70-gen-a92fc9703b" >
        ${escapeHtmlText(p.site.split('—')[0].trim())}
        ${hasDebated ? '<span class="pb-r70-gen-eb9d9bb282" title="Alguna capa tiene cronología debatida" >⚠</span>' : ''}
      </td>
      <td class="pb-r70-gen-1e4001af0b" >${p.layers.length}</td>
      <td class="pb-r70-gen-97a0917387" >
        ${minAge >= 1000 ? (minAge/1000).toFixed(2)+' Ma' : minAge+' Ka'} –
        ${maxAge >= 1000 ? (maxAge/1000).toFixed(2)+' Ma' : maxAge+' Ka'}
      </td>
      <td class="pb-r70-gen-539e9a6dbc" >
        ${allTaxa.length ? allTaxa.map(t => `<span class="strat-taxa-pill pb-r70-gen-e88fe57ff2" >${escapeHtmlText(t)}</span>`).join(' ') : '<span class="pb-r70-gen-b8e42c1295" >—</span>'}
      </td>
      <td class="pb-r70-gen-b76d850c47" >
        ${allMethods.slice(0,2).join(', ')}${allMethods.length > 2 ? '…' : ''}
      </td>
    </tr>`).join('');

  return `
    <div class="strat-compare-panel" role="region" aria-label="Comparación entre yacimientos estratigráficos">
      <h4 class="pb-r70-gen-a7da564384" >
        Comparación entre yacimientos
      </h4>
      <div class="pb-r70-gen-1b1d75452f" >
        <table class="strat-compare-table" aria-label="Tabla comparativa de yacimientos">
          <thead>
            <tr>
              <th scope="col">Yacimiento</th>
              <th scope="col">Capas</th>
              <th scope="col">Rango temporal</th>
              <th scope="col">Taxones homininos</th>
              <th scope="col">Métodos de datación</th>
            </tr>
          </thead>
          <tbody>${tableRows}</tbody>
        </table>
      </div>
      <p class="pb-r70-gen-fc6f89cf28" >
        ⚠ = alguna capa tiene cronología debatida. Los rangos temporales corresponden a los valores documentados en las capas del perfil del atlas, no al yacimiento completo.
      </p>
    </div>`;
} /* fin _buildStratComparePanel */

/**
 * Renderiza el laboratorio de estratigrafía completo.
 * Llamado por renderActiveView cuando viewId === 'estratigrafia'.
 */
function renderStratigraphyLab() {
  const el = document.getElementById('stratContent');
  if (!el) return;

  const profileKeys = Object.keys(STRATIGRAPHY_PROFILES);
  const siteHtml = profileKeys.map(k => {
    const p = STRATIGRAPHY_PROFILES[k];
    return `<button type="button" class="strat-site-btn ${_stratState.site === k ? 'active' : ''}"
                    data-strat-site="${escapeHtmlAttr(k)}"
                    aria-pressed="${_stratState.site === k ? 'true' : 'false'}">
              ${escapeHtmlText(p.site.split('—')[0].trim())}
            </button>`;
  }).join('');

  const profile = STRATIGRAPHY_PROFILES[_stratState.site];
  const svgHtml = _buildStratSVG(profile);
  const detailHtml = _buildStratDetail(profile);

  el.innerHTML = `
    <div class="strat-controls">
      ${siteHtml}
      <button type="button" class="strat-mode-btn ${_stratState.inferenceMode ? 'active' : ''}"
              data-strat-toggle-inference
              aria-pressed="${_stratState.inferenceMode ? 'true' : 'false'}"
              title="Oculta las edades para practicar ordenación temporal">
        ${_stratState.inferenceMode ? '🔓 Revelar edades' : '🔒 Modo inferencia'}
      </button>
      <button type="button" class="strat-mode-btn ${_stratState.compareMode ? 'active' : ''}"
              data-strat-toggle-compare
              aria-pressed="${_stratState.compareMode ? 'true' : 'false'}"
              title="Compara el número de capas, rango temporal y métodos entre todos los yacimientos">
        📊 Comparar yacimientos
      </button>
    </div>

    <!-- Leyenda DEBATIDO: visible solo si hay capas con esa marca -->
    ${profile.layers.some(l => l.age_label && l.age_label.includes('[DEBATIDO]'))
      ? `<div class="strat-debated-legend" role="note" aria-label="Nota: algunas capas tienen cronología debatida">
           <span class="strat-debated-dot" aria-hidden="true"></span>
           <span>Borde naranja punteado y <strong>?</strong> = cronología debatida en la literatura. La datación de esa capa está sujeta a revisión.</span>
         </div>`
      : ''}

    <p class="pb-r70-gen-2845d2df97" >
      <strong>${escapeHtmlText(profile.site)}</strong> · ${escapeHtmlText(profile.location)}<br>
      ${escapeHtmlText(profile.intro)}
      ${profile.doi ? ` <a class="strat-doi-link" href="https://doi.org/${escapeHtmlAttr(profile.doi)}" target="_blank" rel="noopener" aria-label="DOI del yacimiento">DOI</a>` : ''}
    </p>

    ${_stratState.compareMode ? _buildStratComparePanel() : `
    <div class="strat-layout">
      <div class="strat-profile-wrap">
        <span class="strat-profile-label" id="strat-profile-label-${escapeHtmlAttr(_stratState.site)}">Perfil estratigráfico — más reciente arriba</span>
        <div class="strat-svg-wrap" role="img" aria-labelledby="strat-profile-label-${escapeHtmlAttr(_stratState.site)}">
          ${svgHtml}
        </div>
        ${_stratState.inferenceMode ? `<p class="pb-r70-gen-c8fda29e4e" >Modo inferencia: pulsa cada capa y razona su posición antes de revelar la edad pulsando sobre ella.</p>` : ''}
      </div>
      <div class="strat-detail" id="stratDetailPanel">
        ${detailHtml}
      </div>
    </div>`}`;
}

/** Construye el SVG del perfil estratigráfico proceduralmente.
 *  Las capas con [DEBATIDO] en su age_label muestran un borde punteado naranja.
 *  El rectángulo de capa activa lleva stroke de acento verde.
 */
function _buildStratSVG(profile) {
  const W = 200, PADDING = 28;
  const totalUnits = profile.layers.reduce((s, l) => s + l.thickness_rel, 0);
  const H = totalUnits * 22 + PADDING * 2;

  let y = PADDING;
  const rects = profile.layers.map((layer, i) => {
    const h = layer.thickness_rel * 22;
    const isSelected = _stratState.selectedLayer === layer.id;
    const isDebated = layer.age_label && layer.age_label.includes('[DEBATIDO]');
    // Estilo de borde: seleccionado → acento verde; debatido → naranja punteado; normal → gris
    const strokeColor = isSelected ? 'var(--accent)' : (isDebated ? '#c07800' : '#888');
    const strokeW = isSelected ? 3 : (isDebated ? 2 : 1);
    const strokeDash = isDebated && !isSelected ? '4,3' : 'none';

    const rect = `
      <g class="strat-layer ${isSelected ? 'selected' : ''} ${isDebated ? 'debated' : ''}"
         data-strat-layer="${escapeHtmlAttr(layer.id)}"
         data-strat-site="${escapeHtmlAttr(_stratState.site)}"
         role="button" tabindex="0"
         aria-label="Capa ${layer.label}${!_stratState.inferenceMode ? ', ' + layer.age_label : ''}${isDebated ? ' — cronología debatida' : ''}">
        <rect x="10" y="${y}" width="${W - 20}" height="${h}"
              fill="${layer.color}"
              stroke="${strokeColor}" stroke-width="${strokeW}"
              stroke-dasharray="${strokeDash}"
              rx="2"/>
        ${isDebated ? `<text x="${W - 16}" y="${y + 11}"
              text-anchor="middle" font-family="'JetBrains Mono',monospace"
              font-size="8" fill="#c07800" font-weight="900"
              title="Cronología debatida en la literatura">?</text>` : ''}
        <text x="${W / 2}" y="${y + h / 2 + 5}" text-anchor="middle"
              font-family="'JetBrains Mono',monospace" font-size="11" fill="#1c2b3a" font-weight="700">
          ${escapeHtmlText(layer.label)}
        </text>
        <text x="${W / 2}" y="${y + h / 2 + 18}" text-anchor="middle"
              font-family="'JetBrains Mono',monospace" font-size="9" fill="#4a5a6e">
          ${_stratState.inferenceMode
            ? `<tspan class="strat-age-hidden ${isSelected ? 'revealed' : ''}" data-strat-reveal="${escapeHtmlAttr(layer.id)}">[edad oculta]</tspan>`
            : escapeHtmlText(layer.age_label)}
        </text>
      </g>`;
    y += h;
    return rect;
  });

  // Flecha de tiempo (más antiguo abajo)
  const arrow = `<line x1="6" y1="${PADDING}" x2="6" y2="${H - PADDING}" stroke="#aaa" stroke-width="1.5" marker-end="url(#arrowUp)"/>
    <text x="3" y="${H/2}" text-anchor="middle" font-size="8" fill="#aaa" transform="rotate(-90 3 ${H/2})" font-family="'JetBrains Mono',monospace">más antiguo</text>`;

  return `<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" width="100%" data-pb-r71-style="max-width:${W}px">
    <defs>
      <marker id="arrowUp" markerWidth="6" markerHeight="6" refX="3" refY="6" orient="auto">
        <path d="M0,6 L3,0 L6,6" fill="none" stroke="#aaa" stroke-width="1"/>
      </marker>
    </defs>
    ${rects.join('')}
    ${arrow}
  </svg>`;
}

/** Construye el panel de detalle de la capa seleccionada */
function _buildStratDetail(profile) {
  if (!_stratState.selectedLayer) {
    return `<div class="strat-detail-empty">← Selecciona una capa del perfil para ver sus datos estratigráficos, método de datación y pregunta de razonamiento.</div>`;
  }

  const layer = profile.layers.find(l => l.id === _stratState.selectedLayer);
  if (!layer) return `<div class="strat-detail-empty">Capa no encontrada.</div>`;

  const taxaHtml = layer.taxa.length
    ? layer.taxa.map(t => `<span class="strat-taxa-pill">${escapeHtmlText(t)}</span>`).join(' ')
    : '<span class="pb-r70-gen-45c58a388b" >Sin homininos documentados en esta capa</span>';

  const ageDisplay = _stratState.inferenceMode
    ? `<span class="strat-age-hidden ${_stratState.selectedLayer ? 'revealed' : ''}" 
             id="strat-age-display-${escapeHtmlAttr(layer.id)}">${escapeHtmlText(layer.age_label)}</span>
       <button type="button" class="strat-reveal-btn" data-strat-reveal="${escapeHtmlAttr(layer.id)}" aria-label="Revelar edad de esta capa">Revelar edad</button>`
    : escapeHtmlText(layer.age_label);

  const doiHtml = layer.doi
    ? `<a class="strat-doi-link" href="https://doi.org/${escapeHtmlAttr(layer.doi)}" target="_blank" rel="noopener">DOI fuente específica</a>`
    : '';

  return `
    <h4>${escapeHtmlText(layer.label)} — ${ageDisplay}</h4>
    <p class="strat-detail-meta">${escapeHtmlText(profile.site)}</p>
    <div class="strat-detail-field">
      <strong>Litología</strong>
      <p>${escapeHtmlText(layer.litology)}</p>
    </div>
    <div class="strat-detail-field">
      <strong>Método de datación</strong>
      <p>${escapeHtmlText(layer.method)}</p>
    </div>
    <div class="strat-detail-field">
      <strong>Fauna asociada</strong>
      <p>${escapeHtmlText(layer.fauna || 'No documentada')}</p>
    </div>
    <div class="strat-detail-field">
      <strong>Taxones homininos</strong>
      <div class="pb-r70-gen-eb2cdaa55e" >${taxaHtml}</div>
    </div>
    ${doiHtml ? `<div class="strat-detail-field"><strong>Fuente</strong><p>${doiHtml}</p></div>` : ''}
    <div class="strat-question-box" role="region" aria-label="Pregunta de razonamiento integrado">
      <p>🔍 <strong>Razonamiento:</strong> ${escapeHtmlText(layer.question)}</p>
    </div>
    <div class="strat-goto-dating">
      <button type="button" class="socratic-btn secondary pb-r70-gen-1645cc452c" 
              data-view="datacion" aria-label="Abrir laboratorio de datación">
        → Laboratorio de datación
      </button>
    </div>`;
}

// Eventos de estratigrafía — delegación
document.addEventListener('click', function(e) {
  // NOTA: data-strat-layer debe comprobarse ANTES que data-strat-site porque
  // los <g> de capa llevan ambos atributos; si se invirtiera el orden, el click
  // en una capa activaría la rama de cambio de yacimiento en lugar de abrir el detalle.
  const layerEl = e.target.closest('[data-strat-layer]');
  if (layerEl) {
    e.preventDefault();
    e.stopPropagation();
    _stratState.selectedLayer = layerEl.dataset.stratLayer;
    // Actualizar solo el panel de detalle para no re-renderizar el SVG completo
    const profile = STRATIGRAPHY_PROFILES[_stratState.site];
    const detailPanel = document.getElementById('stratDetailPanel');
    if (detailPanel && profile) detailPanel.innerHTML = _buildStratDetail(profile);
    // Actualizar clase selected en SVG
    document.querySelectorAll('.strat-layer').forEach(el => el.classList.remove('selected'));
    layerEl.classList.add('selected');
    return;
  }
  const siteBtn = e.target.closest('[data-strat-site]');
  if (siteBtn) {
    e.preventDefault();
    e.stopPropagation();
    _stratState.site = siteBtn.dataset.stratSite;
    _stratState.selectedLayer = null;
    renderStratigraphyLab();
    return;
  }
  const inferBtn = e.target.closest('[data-strat-toggle-inference]');
  if (inferBtn) {
    e.preventDefault();
    e.stopPropagation();
    _stratState.inferenceMode = !_stratState.inferenceMode;
    renderStratigraphyLab();
    return;
  }
  const compareBtn = e.target.closest('[data-strat-toggle-compare]');
  if (compareBtn) {
    e.preventDefault();
    e.stopPropagation();
    _stratState.compareMode = !_stratState.compareMode;
    renderStratigraphyLab();
    return;
  }
  const revealBtn = e.target.closest('[data-strat-reveal]');
  if (revealBtn) {
    e.preventDefault();
    e.stopPropagation();
    const ageEl = document.getElementById(`strat-age-display-${revealBtn.dataset.stratReveal}`);
    if (ageEl) ageEl.classList.add('revealed');
    revealBtn.disabled = true;
    revealBtn.textContent = 'Revelada';
    return;
  }
});

document.addEventListener('keydown', function(e) {
  const layerEl = e.target.closest('[data-strat-layer]');
  if (layerEl && (e.key === 'Enter' || e.key === ' ')) {
    e.preventDefault();
    layerEl.click();
  }
});

// ════════════════════════════════════════════════════════════════════════
//  MEJORA 1 — SIMULADOR DE SESGO TAFONÓMICO  (v30)
//  Datos de supervivencia esquelética basados en:
//    Brain (1981) The Hunters or the Hunted? Univ Chicago Press
//    Behrensmeyer (1978) Paleobiology 4(2):150-162 DOI:10.1017/S0094837300005820
//    Lyman (1994) Vertebrate Taphonomy. Cambridge University Press
//    Fernández-Jalvo & Andrews (2016) Atlas of Taphonomic Identifications
// ════════════════════════════════════════════════════════════════════════

/**
 * Catálogo de regiones esqueléticas con supervivencia base [0–1].
 * Los valores representan probabilidades empíricas medias documentadas.
 * Se modulan por las variables del simulador.
 */
const SKELETAL_REGIONS = [
  { id:'cranium',   label:'Cráneo',        base:0.35, x:95,  y:18,  r:14 },
  { id:'mandible',  label:'Mandíbula',      base:0.55, x:95,  y:42,  r:8  },
  { id:'vertebrae', label:'Vértebras',      base:0.12, x:95,  y:78,  r:10 },
  { id:'ribs',      label:'Costillas',      base:0.15, x:75,  y:75,  r:9  },
  { id:'pelvis',    label:'Pelvis',         base:0.30, x:95,  y:108, r:11 },
  { id:'humerus',   label:'Húmero',         base:0.45, x:68,  y:68,  r:7  },
  { id:'radius_ulna',label:'Radio/Cúbito', base:0.38, x:62,  y:88,  r:6  },
  { id:'hand',      label:'Mano',           base:0.08, x:56,  y:105, r:5  },
  { id:'femur',     label:'Fémur',          base:0.60, x:85,  y:132, r:9  },
  { id:'tibia',     label:'Tibia/Fíbula',   base:0.52, x:83,  y:155, r:7  },
  { id:'foot',      label:'Pie',            base:0.10, x:82,  y:174, r:6  },
  { id:'teeth',     label:'Dientes',        base:0.75, x:97,  y:36,  r:6  }
];

/**
 * Variables del simulador de tafonomía.
 * Cada modificador es un multiplicador [0.1–1.5] que escala la supervivencia base.
 */
const TAPHO_VARIABLES = [
  { id:'sediment',  label:'Tipo de sedimento',   hint:'Alta energía (gravas) destruye; baja (arcillas) conserva',
    min:0, max:100, default:60, low:'Gravas / aluvial', high:'Arcilla / lacustre',
    fn: v => 0.3 + (v / 100) * 0.9 },
  { id:'acidity',   label:'Acidez del suelo (pH)', hint:'Suelos ácidos disuelven el hueso; básicos lo preservan',
    min:0, max:100, default:35, low:'pH 4 (ácido)', high:'pH 9 (básico)',
    fn: v => 0.2 + (v / 100) * 0.85 },
  { id:'scavenging', label:'Actividad carroñera',  hint:'Alta carroña dispersa y fractura el esqueleto',
    min:0, max:100, default:50, low:'Mínima', high:'Intensa (hienas, aves)',
    fn: v => 1.1 - (v / 100) * 0.75 },
  { id:'hydraulic', label:'Energía hídrica',       hint:'Corrientes fuertes transportan y separan elementos',
    min:0, max:100, default:40, low:'Estático / seco', high:'Corriente fuerte',
    fn: v => 1.0 - (v / 100) * 0.65 },
  { id:'time',      label:'Tiempo de exposición',  hint:'Mayor tiempo antes del enterramiento = mayor destrucción',
    min:0, max:100, default:45, low:'Rápido (horas)', high:'Lento (décadas)',
    fn: v => 1.05 - (v / 100) * 0.70 }
];

/** Estado del simulador */
let _taphoState = {
  values: Object.fromEntries(TAPHO_VARIABLES.map(v => [v.id, v.default])),
  species: 'afarensis',
  hoveredRegion: null
};

/**
 * Calcula la supervivencia final de cada región esquelética aplicando los modificadores.
 * @returns {Object} Map de region.id → survival [0–1]
 */
function _calcTaphoSurvival() {
  const mods = TAPHO_VARIABLES.map(v => v.fn(_taphoState.values[v.id]));
  const combined = mods.reduce((acc, m) => acc * m, 1);
  // Normalizar para que el rango sea razonable
  const k = Math.min(1.5, Math.max(0.15, combined));
  return Object.fromEntries(
    SKELETAL_REGIONS.map(reg => {
      const raw = Math.min(1, Math.max(0, reg.base * k));
      return [reg.id, raw];
    })
  );
}

/** Interpola entre dos colores HEX según valor 0–1 */
function _taphoColor(survival) {
  // Degradado: baja=#f0e8d0 (arena) → alta=#0e7f65 (acento verde)
  const r0=240, g0=232, b0=208;
  const r1=14,  g1=127, b1=101;
  const t = survival;
  const r = Math.round(r0 + (r1-r0)*t);
  const g = Math.round(g0 + (g1-g0)*t);
  const b = Math.round(b0 + (b1-b0)*t);
  return `rgb(${r},${g},${b})`;
}

/**
 * Renderiza el simulador de tafonomía completo.
 */
function renderTaphonomyView() {
  const el = document.getElementById('taphoContent');
  if (!el) return;

  const survival = _calcTaphoSurvival();

  // Estadísticas globales
  const values = Object.values(survival);
  const mean = values.reduce((a,b)=>a+b,0) / values.length;
  const maxReg = SKELETAL_REGIONS.reduce((a,b) => survival[a.id] > survival[b.id] ? a : b);
  const minReg = SKELETAL_REGIONS.reduce((a,b) => survival[a.id] < survival[b.id] ? a : b);

  // Interpretación textual
  const interp = _taphoInterpretation(survival, mean);

  el.innerHTML = `
    <div class="tapho-layout">
      <div class="tapho-controls-panel">
        <div class="tapho-variable">
          <label for="tapho-species-sel">Especie de referencia <span>contexto ecológico</span></label>
          <select id="tapho-species-sel" class="tapho-species-select" data-tapho-species
                  aria-label="Seleccionar especie para contexto tafonómico">
            ${DB.slice(0, 20).map(sp => `<option value="${escapeHtmlAttr(sp.id)}" ${_taphoState.species === sp.id ? 'selected' : ''}>${escapeHtmlText(sp.nombre)}</option>`).join('')}
          </select>
        </div>

        ${TAPHO_VARIABLES.map(v => `
          <div class="tapho-variable">
            <label for="tapho-${v.id}">
              ${escapeHtmlText(v.label)}
              <span id="tapho-val-${v.id}">${Math.round(_taphoState.values[v.id])}%</span>
            </label>
            <input type="range" id="tapho-${v.id}" class="tapho-range"
                   min="${v.min}" max="${v.max}" step="1" value="${_taphoState.values[v.id]}"
                   data-tapho-var="${escapeHtmlAttr(v.id)}"
                   aria-label="${escapeHtmlText(v.label)}: ${Math.round(_taphoState.values[v.id])}%"
                   title="${escapeHtmlText(v.hint)}">
            <div class="pb-r70-gen-e568991736" >
              <span>${escapeHtmlText(v.low)}</span><span>${escapeHtmlText(v.high)}</span>
            </div>
          </div>`).join('')}
      </div>

      <div class="tapho-result-panel">
        <div class="tapho-heatmap-wrap" role="region" aria-label="Mapa de calor de supervivencia esquelética">
          <span class="tapho-heatmap-title">Supervivencia esquelética estimada</span>
          ${_buildTaphoSVG(survival)}
          <div class="tapho-legend">
            <span>Baja (0%)</span>
            <div class="tapho-legend-bar" aria-hidden="true"></div>
            <span>Alta (100%)</span>
          </div>
          <p class="pb-r70-gen-43b38af7ef" >
            Cada círculo = región esquelética · tamaño y color proporcionales a la supervivencia estimada
          </p>
        </div>

        <div class="tapho-stats-grid">
          <div class="tapho-stat-card">
            <span class="tapho-stat-value">${Math.round(mean * 100)}%</span>
            <span class="tapho-stat-label">supervivencia media</span>
          </div>
          <div class="tapho-stat-card">
            <span class="tapho-stat-value pb-r70-gen-cec1311c30" >${escapeHtmlText(maxReg.label)}</span>
            <span class="tapho-stat-label">más preservado</span>
          </div>
          <div class="tapho-stat-card">
            <span class="tapho-stat-value pb-r70-gen-cec1311c30" >${escapeHtmlText(minReg.label)}</span>
            <span class="tapho-stat-label">más vulnerable</span>
          </div>
        </div>

        <!-- Tabla de regiones ordenadas por supervivencia — lectura accesible del heatmap -->
        <div class="tapho-region-table" aria-label="Tabla de supervivencia por región esquelética">
          <div class="pb-r70-gen-de7a2c8748" >
            Regiones por supervivencia (mayor → menor)
          </div>
          <div class="tapho-region-rows">
            ${SKELETAL_REGIONS
              .slice()
              .sort((a,b) => survival[b.id] - survival[a.id])
              .map(reg => {
                const s = survival[reg.id];
                const pct = Math.round(s * 100);
                const barW = Math.round(s * 100);
                const col = _taphoColor(s);
                return `<div class="tapho-region-row">
                  <span class="tapho-region-row-label">${escapeHtmlText(reg.label)}</span>
                  <div class="tapho-region-row-track" role="progressbar"
                       aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"
                       aria-label="${escapeHtmlText(reg.label)}: ${pct}%">
                    <div class="tapho-region-row-fill" data-pb-r71-style="width:${barW}%;background:${col}"></div>
                  </div>
                  <span class="tapho-region-row-pct">${pct}%</span>
                </div>`;
              }).join('')}
          </div>
        </div>

        <div class="tapho-interpretation">
          <h4>Interpretación del registro</h4>
          <p>${escapeHtmlText(interp)}</p>
        </div>

        <div class="tapho-sources">
          Fuentes: Brain (1981), Behrensmeyer
          <a href="https://doi.org/10.1017/S0094837300005820" target="_blank" rel="noopener">DOI:10.1017/S0094837300005820</a>,
          Lyman (1994), Fernández-Jalvo &amp; Andrews (2016).
          Valores representativos; la variabilidad contextual real es elevada.
        </div>
      </div>
    </div>`;
}

/**
 * Construye el SVG del heatmap esquelético con silueta anatómica real.
 * La silueta usa path SVG derivados de proporciones anatómicas estándar.
 * Cada región es un elemento <g> interactivo con tooltip nativo y aria.
 * @param {Object} survival - Map de region.id → valor [0–1]
 * @returns {string} HTML del SVG completo
 */
function _buildTaphoSVG(survival) {
  const W = 210, H = 220;

  // ── Silueta anatómica esquemática ─────────────────────────────────
  // Proporciones basadas en atlas de anatomía humana (8 cabezas de altura)
  // Coordenadas escaladas al viewBox 210×220
  const silhouette = `
    <g class="tapho-silhouette" aria-hidden="true" opacity="0.18" fill="none" stroke="#5a6a7e" stroke-linecap="round" stroke-linejoin="round">
      <!-- Cabeza (cráneo + mandíbula) -->
      <ellipse cx="105" cy="22" rx="16" ry="18" stroke-width="1.5"/>
      <!-- Cuello -->
      <line x1="99" y1="38" x2="97" y2="48" stroke-width="2"/>
      <line x1="111" y1="38" x2="113" y2="48" stroke-width="2"/>
      <!-- Clavículas -->
      <path d="M97,50 Q86,47 78,50" stroke-width="1.5"/>
      <path d="M113,50 Q124,47 132,50" stroke-width="1.5"/>
      <!-- Tórax (caja torácica) -->
      <path d="M97,48 C94,58 93,72 95,84 L115,84 C117,72 116,58 113,48 Z" stroke-width="1.3"/>
      <!-- Costillas (4 pares esquemáticos) -->
      <path d="M97,54 Q87,57 84,62" stroke-width="1"/>
      <path d="M113,54 Q123,57 126,62" stroke-width="1"/>
      <path d="M96,62 Q85,65 83,71" stroke-width="1"/>
      <path d="M114,62 Q125,65 127,71" stroke-width="1"/>
      <path d="M95,70 Q85,73 84,79" stroke-width="1"/>
      <path d="M115,70 Q125,73 126,79" stroke-width="1"/>
      <path d="M95,78 Q87,82 87,87" stroke-width="1"/>
      <path d="M115,78 Q123,82 123,87" stroke-width="1"/>
      <!-- Columna vertebral -->
      <line x1="105" y1="48" x2="105" y2="118" stroke-width="1.5" stroke-dasharray="3,2"/>
      <!-- Pelvis -->
      <path d="M93,106 C85,108 80,118 83,126 Q95,130 105,130 Q115,130 127,126 C130,118 125,108 117,106 Z" stroke-width="1.5"/>
      <!-- Húmero izquierdo -->
      <path d="M78,52 L72,82" stroke-width="2"/>
      <!-- Radio/cúbito izquierdo -->
      <path d="M72,82 L65,108" stroke-width="1.5"/>
      <!-- Mano izquierda -->
      <path d="M65,108 L60,118 M62,110 L57,120 M60,112 L56,122" stroke-width="1"/>
      <!-- Húmero derecho -->
      <path d="M132,52 L138,82" stroke-width="2"/>
      <!-- Radio/cúbito derecho -->
      <path d="M138,82 L145,108" stroke-width="1.5"/>
      <!-- Mano derecha -->
      <path d="M145,108 L150,118 M148,110 L153,120 M150,112 L154,122" stroke-width="1"/>
      <!-- Fémur izquierdo -->
      <path d="M96,130 L90,168" stroke-width="2.5"/>
      <!-- Fémur derecho -->
      <path d="M114,130 L120,168" stroke-width="2.5"/>
      <!-- Tibia/fíbula izquierda -->
      <path d="M90,168 L87,200" stroke-width="2"/>
      <!-- Tibia/fíbula derecha -->
      <path d="M120,168 L123,200" stroke-width="2"/>
      <!-- Pie izquierdo -->
      <path d="M87,200 Q82,204 78,203" stroke-width="1.5"/>
      <!-- Pie derecho -->
      <path d="M123,200 Q128,204 132,203" stroke-width="1.5"/>
    </g>`;

  // ── Regiones interactivas (círculos con heatmap de color) ──────────
  const circles = SKELETAL_REGIONS.map(reg => {
    const s = survival[reg.id];
    const fill = _taphoColor(s);
    const pct = Math.round(s * 100);
    // Radio dinámico: varía levemente según supervivencia para reforzar la señal visual
    const rVisual = reg.r + Math.round(s * 3);
    return `<g class="tapho-region" data-tapho-region="${escapeHtmlAttr(reg.id)}"
               tabindex="0" role="img"
               aria-label="${escapeHtmlText(reg.label)}: ${pct}% de probabilidad de supervivencia en el registro">
      <circle class="pb-r70-gen-178d998c5b" cx="${reg.x}" cy="${reg.y}" r="${rVisual}"
              fill="${fill}" fill-opacity="0.88"
              stroke="rgba(28,43,58,0.35)" stroke-width="1.2"
              />
      <!-- Etiqueta de porcentaje dentro del círculo cuando es suficientemente grande -->
      ${rVisual >= 9 ? `<text x="${reg.x}" y="${reg.y + 4}" text-anchor="middle"
            font-family="'JetBrains Mono',monospace" font-size="8" fill="white"
            font-weight="700" pointer-events="none">${pct}%</text>` : ''}
      <title>${escapeHtmlText(reg.label)}: ${pct}% supervivencia estimada</title>
    </g>`;
  });

  // ── Eje de referencia temporal (flecha "más antiguo") ─────────────
  const axis = `
    <defs>
      <marker id="taphoArrow" markerWidth="7" markerHeight="7" refX="3" refY="3.5" orient="auto">
        <polygon points="0 0, 7 3.5, 0 7" fill="#aaa"/>
      </marker>
    </defs>`;

  return `<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg"
               width="${W}" height="${H}" focusable="false" aria-label="Mapa de calor de supervivencia esquelética sobre silueta anatómica">
    ${axis}
    ${silhouette}
    ${circles.join('')}
  </svg>`;
}

/** Genera texto de interpretación tafonómica según los valores de supervivencia */
function _taphoInterpretation(survival, mean) {
  const teethOk = survival['teeth'] > 0.55;
  const craniumOk = survival['cranium'] > 0.30;
  const postcrOk = (survival['vertebrae'] + survival['ribs']) / 2 > 0.20;
  const femurOk = survival['femur'] > 0.45;

  let msg = '';
  if (mean < 0.20) {
    msg = 'Las condiciones son muy desfavorables: es probable que solo lleguen al registro fragmentos dentales aislados y algún elemento compacto. El sesgo de muestreo sería extremo.';
  } else if (mean < 0.40) {
    msg = 'Supervivencia moderada-baja. Los dientes y huesos compactos (fémur, húmero) tendrían cierta representación, pero el cráneo y los elementos axiales estarían muy infrarepresentados.';
  } else if (mean < 0.60) {
    msg = 'Condiciones medias. El cráneo y la mandíbula podrían conservarse parcialmente. Los elementos apendiculares serían los más fiables para inferencias morfológicas.';
  } else {
    msg = 'Condiciones favorables de preservación. El registro podría ser relativamente completo, aunque los huesos pequeños (manos, pies) seguirían estando subrepresentados.';
  }

  if (teethOk) msg += ' Los dientes son el elemento con mayor probabilidad de supervivencia en estas condiciones: su uso taxonómico está justificado.';
  if (!postcrOk) msg += ' El esqueleto axial (vértebras, costillas) apenas aparecería en el registro: las inferencias locomotoras quedarían limitadas a los huesos compactos supervivientes.';

  return msg;
}

// Eventos del simulador de tafonomía — delegación
document.addEventListener('input', function(e) {
  const varRange = e.target.closest('[data-tapho-var]');
  if (varRange) {
    const varId = varRange.dataset.taphoVar;
    const val = Number(varRange.value);
    _taphoState.values[varId] = val;
    // Actualizar el label de valor sin re-renderizar todo
    const valLabel = document.getElementById(`tapho-val-${varId}`);
    if (valLabel) valLabel.textContent = `${val}%`;
    varRange.setAttribute('aria-label', `${varRange.getAttribute('aria-label').split(':')[0]}: ${val}%`);
    // Re-renderizar solo el panel de resultados
    _taphoUpdateResults();
    return;
  }
});

document.addEventListener('change', function(e) {
  const speciesSel = e.target.closest('[data-tapho-species]');
  if (speciesSel) {
    _taphoState.species = speciesSel.value;
    renderTaphonomyView();
    return;
  }
});

/** Actualiza solo el panel de resultados (heatmap + stats + interpretación) sin re-render completo */
function _taphoUpdateResults() {
  const survival = _calcTaphoSurvival();
  const values = Object.values(survival);
  const mean = values.reduce((a,b)=>a+b,0) / values.length;
  const maxReg = SKELETAL_REGIONS.reduce((a,b) => survival[a.id] > survival[b.id] ? a : b);
  const minReg = SKELETAL_REGIONS.reduce((a,b) => survival[a.id] < survival[b.id] ? a : b);

  // Actualizar círculos del SVG directamente en el DOM (color + radio dinámico + etiqueta pct)
  document.querySelectorAll('.tapho-region').forEach(g => {
    const regId = g.dataset.taphoRegion;
    const reg = SKELETAL_REGIONS.find(r => r.id === regId);
    if (!reg) return;
    const s = survival[regId];
    const pct = Math.round(s * 100);
    const rVisual = reg.r + Math.round(s * 3);
    const circle = g.querySelector('circle');
    if (circle) {
      circle.setAttribute('fill', _taphoColor(s));
      circle.setAttribute('r', rVisual);
    }
    // Actualizar etiqueta inline de porcentaje
    const textEl = g.querySelector('text');
    if (textEl && rVisual >= 9) {
      textEl.textContent = `${pct}%`;
    } else if (textEl && rVisual < 9) {
      textEl.textContent = '';
    }
    const titleEl = g.querySelector('title');
    if (titleEl) titleEl.textContent = `${reg.label}: ${pct}% supervivencia estimada`;
    g.setAttribute('aria-label', `${reg.label}: ${pct}% de probabilidad de supervivencia en el registro`);
  });

  // Actualizar stats KPI
  const statsGrid = document.querySelector('.tapho-stats-grid');
  if (statsGrid) {
    const cards = statsGrid.querySelectorAll('.tapho-stat-value');
    if (cards[0]) cards[0].textContent = `${Math.round(mean*100)}%`;
    if (cards[1]) cards[1].textContent = maxReg.label;
    if (cards[2]) cards[2].textContent = minReg.label;
  }

  // Actualizar tabla de regiones ordenada
  const regionRows = document.querySelector('.tapho-region-rows');
  if (regionRows) {
    regionRows.innerHTML = SKELETAL_REGIONS
      .slice()
      .sort((a,b) => survival[b.id] - survival[a.id])
      .map(reg => {
        const s = survival[reg.id];
        const pct = Math.round(s * 100);
        const barW = Math.round(s * 100);
        const col = _taphoColor(s);
        return `<div class="tapho-region-row">
          <span class="tapho-region-row-label">${escapeHtmlText(reg.label)}</span>
          <div class="tapho-region-row-track" role="progressbar"
               aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"
               aria-label="${escapeHtmlText(reg.label)}: ${pct}%">
            <div class="tapho-region-row-fill" data-pb-r71-style="width:${barW}%;background:${col}"></div>
          </div>
          <span class="tapho-region-row-pct">${pct}%</span>
        </div>`;
      }).join('');
  }

  // Actualizar interpretación
  const interp = document.querySelector('.tapho-interpretation p');
  if (interp) interp.textContent = _taphoInterpretation(survival, mean);
}

