/** Nodos del diagrama de introgresión (linajes) */
const INTROGRESSION_NODES = [
  { id:'neanderthal',   label:'H. neanderthalensis',   x:160, y:90,  r:22, color:'#1a4fa0' },
  { id:'denisovano',    label:'Denisovano',             x:260, y:100, r:20, color:'#8b2be2' },
  { id:'arcaico_afr',   label:'Arcaico africano\n[PROV]', x:120, y:140, r:18, color:'#c07800' },
  { id:'sap_eur',       label:'H. sapiens Eur/Asia',   x:340, y:60,  r:22, color:'#aa1f1f' },
  { id:'sap_mel',       label:'H. sapiens Oceanía',    x:420, y:80,  r:18, color:'#5a1ea0' },
  { id:'sap_tib',       label:'H. sapiens Tibet',      x:360, y:100, r:15, color:'#7a00c8' },
  { id:'sap_afr',       label:'H. sapiens África',     x:180, y:150, r:22, color:'#0a6b49' }
];

/** Estado del mapa de introgresión */
let _introgState = { selectedEvent: null };

/**
 * Renderiza la vista de introgresión arcaica.
 */
function renderIntrogressionView() {
  const el = document.getElementById('introgContent');
  if (!el) return;

  const legendHtml = [
    { label:'Neanderthal', color:'#1a4fa0' },
    { label:'Denisovano', color:'#8b2be2' },
    { label:'Arcaico africano', color:'#c07800' },
    { label:'H. sapiens', color:'#0a6b49' }
  ].map(n => `
    <div class="introg-legend-item">
      <div class="introg-legend-dot" data-pb-r71-style="background:${n.color}"></div>
      <span>${escapeHtmlText(n.label)}</span>
    </div>`).join('');

  const panelHtml = _buildIntrogPanel();

  el.innerHTML = `
    <div class="introg-legend-row" role="list" aria-label="Leyenda de linajes">${legendHtml}</div>
    <div class="introg-layout">
      <div class="introg-svg-wrap" role="img" aria-label="Diagrama de red de flujo génico entre linajes homininos">
        ${_buildIntrogSVG()}
      </div>
      <div class="introg-panel" id="introgDetailPanel">
        ${panelHtml}
      </div>
    </div>
    <p class="pb-r70-gen-9a6f17929f" >
      Grosor de flecha proporcional al porcentaje máximo documentado. Los porcentajes son estimaciones con márgenes de incertidumbre. [PROVISIONAL] indica que la identidad del donante no está confirmada por fósiles con ADN recuperable.
    </p>`;
}

/** Construye el SVG del diagrama de red de introgresión.
 *  Mejoras v33:
 *  - Arrowhead markers en los ribbons que indican dirección del flujo génico
 *  - Eje temporal Ka en la parte superior del diagrama
 *  - Badge visual PROVISIONAL en las rutas de eventos no confirmados
 */
function _buildIntrogSVG() {
  const W = 500, H = 240;

  // ── Definiciones: markers de flecha por color ─────────────────────
  const markerDefs = INTROGRESSION_EVENTS.map(ev => {
    const mid = escapeHtmlAttr(ev.id);
    // Color de la punta de flecha = color del evento
    return `<marker id="arrow-${mid}" markerWidth="8" markerHeight="8"
                    refX="7" refY="3" orient="auto" markerUnits="strokeWidth">
      <path d="M0,0 L0,6 L8,3 Z" fill="${ev.color}" fill-opacity="0.85"/>
    </marker>`;
  }).join('');

  // ── Eje temporal superior (escala Ka simplificada) ─────────────────
  const KA_TICKS = [300, 200, 100, 50, 20, 0];
  // Mapear Ka a posición X aproximada (300 Ka = x:40, 0 Ka = x:460)
  const kaToX = ka => 40 + ((300 - ka) / 300) * 420;
  const timeAxis = `
    <g class="introg-time-axis" aria-hidden="true">
      <line x1="40" y1="22" x2="460" y2="22" stroke="#ccc" stroke-width="1"/>
      ${KA_TICKS.map(ka => `
        <line x1="${kaToX(ka)}" y1="18" x2="${kaToX(ka)}" y2="26" stroke="#ccc" stroke-width="1"/>
        <text x="${kaToX(ka)}" y="14" text-anchor="middle"
              font-family="'JetBrains Mono',monospace" font-size="8" fill="#9aacbc">${ka}</text>
      `).join('')}
      <text x="250" y="8" text-anchor="middle"
            font-family="'JetBrains Mono',monospace" font-size="8" fill="#9aacbc" letter-spacing="0.04em">
        Miles de años (Ka) — anterior
      </text>
    </g>`;

  // ── Ribbons (eventos de introgresión con flecha direccional) ───────
  const ribbons = INTROGRESSION_EVENTS.map(ev => {
    const isSelected = _introgState.selectedEvent === ev.id;
    const opacity = _introgState.selectedEvent && !isSelected ? 0.18 : 0.78;
    const strokeW = 2.5 + (ev.pct_max / 7) * 4; // grosor proporcional
    // Curva Bézier cúbica con punto de control elevado para claridad visual
    const mx = (ev.fromPos.x + ev.toPos.x) / 2;
    const my = Math.min(ev.fromPos.y, ev.toPos.y) - 38;
    const d = `M ${ev.fromPos.x} ${ev.fromPos.y} Q ${mx} ${my} ${ev.toPos.x} ${ev.toPos.y}`;
    const isProvisional = ev.id === 'arcaic_afr_to_afr';
    return `<path class="introg-ribbon ${isSelected ? '' : (_introgState.selectedEvent ? 'dimmed' : '')} pb-r70-gen-9463ff4798"
                  d="${d}" fill="none" stroke="${ev.color}"
                  stroke-width="${strokeW.toFixed(1)}"
                  stroke-opacity="${opacity}"
                  stroke-dasharray="${isProvisional ? '6,3' : 'none'}"
                  marker-end="url(#arrow-${escapeHtmlAttr(ev.id)})"
                  data-introg-event="${escapeHtmlAttr(ev.id)}"
                  role="button" tabindex="0"
                  aria-label="${escapeHtmlText(ev.from)} → ${escapeHtmlText(ev.to.replace('\n',' '))}: ${ev.pct_min}–${ev.pct_max}%${isProvisional ? ' (PROVISIONAL)' : ''}"
                  >
               <title>${escapeHtmlText(ev.from)} → ${escapeHtmlText(ev.to.replace('\n',' '))} · ${ev.pct_min}–${ev.pct_max}% · ${ev.ka_min}–${ev.ka_max} Ka${isProvisional ? ' [PROVISIONAL]' : ''}</title>
             </path>`;
  });

  // ── Nodos con indicador PROVISIONAL ───────────────────────────────
  const nodes = INTROGRESSION_NODES.map(node => {
    const lines = node.label.split('\n');
    const isProvisional = lines.some(l => l.includes('[PROV]'));
    const displayLines = lines.map(l => l.replace('[PROV]', '').trim()).filter(Boolean);
    const textRows = displayLines.map((line, i) =>
      `<tspan x="${node.x}" dy="${i === 0 ? 0 : 11}">${escapeHtmlText(line)}</tspan>`
    ).join('');
    return `<g class="introg-node-circle" data-introg-node="${escapeHtmlAttr(node.id)}"
               role="img" aria-label="${escapeHtmlText(displayLines[0])}${isProvisional ? ' (PROVISIONAL)' : ''}">
      <circle cx="${node.x}" cy="${node.y}" r="${node.r}"
              fill="${node.color}" stroke="white" stroke-width="2" fill-opacity="0.90"/>
      ${isProvisional
        ? `<circle cx="${node.x}" cy="${node.y}" r="${node.r + 4}"
                   fill="none" stroke="#c07800" stroke-width="1.5" stroke-dasharray="4,3" opacity="0.6"/>`
        : ''}
      <text text-anchor="middle" x="${node.x}" y="${node.y + node.r + 12}"
            font-family="'Source Sans 3',sans-serif" font-size="8.5" fill="#1c2b3a" font-weight="600"
            font-style="italic">${textRows}</text>
      ${isProvisional
        ? `<text x="${node.x + node.r - 3}" y="${node.y - node.r + 6}"
                 text-anchor="middle" font-family="'JetBrains Mono',monospace"
                 font-size="9" fill="#c07800" font-weight="900">?</text>`
        : ''}
    </g>`;
  });

  return `<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg"
               width="100%" data-pb-r71-style="min-width:300px;max-width:${W}px">
    <defs>${markerDefs}</defs>
    ${timeAxis}
    <g transform="translate(0,28)">
      ${ribbons.join('')}
      ${nodes.join('')}
    </g>
  </svg>`;
}

/** Construye el panel lateral de detalle del evento seleccionado */
function _buildIntrogPanel() {
  if (!_introgState.selectedEvent) {
    return `<div class="introg-panel-empty">← Pulsa una flecha del diagrama para ver el detalle del evento de introgresión: porcentaje de herencia, período temporal y rasgos adaptativos asociados.</div>`;
  }
  const ev = INTROGRESSION_EVENTS.find(e => e.id === _introgState.selectedEvent);
  if (!ev) return '';

  const isProvisional = ev.description.includes('[PROVISIONAL]');
  const pctMid = (ev.pct_min + ev.pct_max) / 2;
  // Escala visual: máximo documentado es ~19% (arcaico africano), mapeamos 0–20% → 0–100% visual
  const PCT_VISUAL_MAX = 20;
  const pctFillW = Math.min(100, Math.round((pctMid / PCT_VISUAL_MAX) * 100));

  const traitHtml = ev.traits.map(t => `<span class="introg-trait-chip">${escapeHtmlText(t)}</span>`).join('');

  return `
    <h4>${escapeHtmlText(ev.from)} → ${escapeHtmlText(ev.to.replace('\n',' '))}</h4>
    <p class="introg-panel-meta">
      Período estimado: ${ev.ka_min}–${ev.ka_max} Ka
      ${isProvisional ? ' · <strong class="pb-r70-gen-da1f1d4866" >[PROVISIONAL]</strong>' : ''}
    </p>
    <div class="introg-pct-bar-wrap">
      <div class="introg-pct-label">
        <span>Herencia estimada</span>
        <span>${ev.pct_min}–${ev.pct_max}%</span>
      </div>
      <div class="introg-pct-track" role="progressbar"
           aria-valuenow="${pctMid}" aria-valuemin="0" aria-valuemax="20"
           aria-label="Porcentaje de herencia: ${ev.pct_min}–${ev.pct_max}%">
        <div class="introg-pct-fill" data-pb-r71-style="width:${pctFillW}%;background:${ev.color}"></div>
      </div>
    </div>
    <div class="pb-r70-gen-c45e284a36" >
      <strong class="pb-r70-gen-f7cdb24dbd" >Rasgos adaptativos asociados</strong>
      <div class="pb-r70-gen-2ed8beaffe" >${traitHtml}</div>
    </div>
    <p class="pb-r70-gen-65168a9fe2" >${safeGlossary(ev.description)}</p>
    <div class="introg-panel-doi">
      Fuente: <a href="https://doi.org/${escapeHtmlAttr(ev.doi)}" target="_blank" rel="noopener"
                 aria-label="DOI de la fuente: ${escapeHtmlText(ev.doi_label)}">
        ${escapeHtmlText(ev.doi_label)}
      </a>
    </div>`;
}

// Eventos del mapa de introgresión — delegación
document.addEventListener('click', function(e) {
  const ribbonEl = e.target.closest('[data-introg-event]');
  if (ribbonEl) {
    e.preventDefault();
    e.stopPropagation();
    const evId = ribbonEl.dataset.introgEvent;
    _introgState.selectedEvent = _introgState.selectedEvent === evId ? null : evId;
    // Re-renderizar solo el SVG y el panel
    const svgWrap = document.querySelector('.introg-svg-wrap');
    const detailPanel = document.getElementById('introgDetailPanel');
    if (svgWrap) svgWrap.innerHTML = _buildIntrogSVG();
    if (detailPanel) detailPanel.innerHTML = _buildIntrogPanel();
    return;
  }
});

document.addEventListener('keydown', function(e) {
  const ribbonEl = e.target.closest('[data-introg-event]');
  if (ribbonEl && (e.key === 'Enter' || e.key === ' ')) {
    e.preventDefault();
    ribbonEl.click();
  }
});

// ── Recovery R9: teclado de matriz por API pública canónica ──
document.addEventListener('keydown', function(e) {
  if (e.key !== 'Enter' && e.key !== ' ') return;
  const row = e.target.closest('.matrix-row-clickable[data-open-species]');
  if (!row) return;
  e.preventDefault();
  const sp = DB_INDEX[row.dataset.openSpecies];
  if (sp) openMatrixSpeciesViaPublicApi(sp, 'matrix-row-keyboard-core');
});

// Puente de compatibilidad: las capas v59-v63 se ejecutan en scripts
// separados y necesitan acceder a la API central declarada en este bloque.
window.__PB_CORE_BRIDGE_REACHED = true;
document.documentElement.dataset.pbCoreBridgeReached = 'true';
window.DB = DB;
window.DB_INDEX = DB_INDEX;
window.CLADE_COLORS = CLADE_COLORS;
window.CLADE_NAMES = CLADE_NAMES;
window.INTERACTIVE_BUTTON_CONTRACTS = INTERACTIVE_BUTTON_CONTRACTS;
/* R94: globales léxicas (let/const de nivel superior) que otras capas leen como window.X.
   Sin esta exposición, window.X era undefined: la búsqueda global no indexaba vistas ni
   glosario y la exportación SVG del constructor no hacía nada. Las variables reasignables
   se exponen como getters para no quedar desincronizadas. */
window.glosario = glosario;
window.VIEW_META = VIEW_META;
window.TEACHING_COMPETENCY_RUBRIC = TEACHING_COMPETENCY_RUBRIC;
window.INTROGRESSION_EVENTS = INTROGRESSION_EVENTS;
[['nivelActual', () => nivelActual], ['treeBuilderState', () => treeBuilderState]].forEach(([name, read]) => {
  try { Object.defineProperty(window, name, { get: read, configurable: true }); } catch (_) { /* recuperable */ }
});
window.renderActiveView = renderActiveView;
window.showDetail = showDetail;
window.showDetailFromQuiz = showDetailFromQuiz;
window.switchView = switchView;
window.toggleModal = toggleModal;
window.matchesActiveFilters = matchesActiveFilters;
window.getActiveViewId = getActiveViewId;
window.getSpeciesMedia = getSpeciesMedia;
window.getSpeciesImage = getSpeciesImage;
window.getSpeciesThumb = getSpeciesThumb;
window.auditSpeciesMedia = auditSpeciesMedia;
document.documentElement.dataset.pbCoreBridge = JSON.stringify({
  db: Array.isArray(window.DB) ? window.DB.length : 0,
  contracts: Array.isArray(window.INTERACTIVE_BUTTON_CONTRACTS) ? window.INTERACTIVE_BUTTON_CONTRACTS.length : 0,
  renderActiveView: typeof window.renderActiveView
});

document.addEventListener('DOMContentLoaded', watchDynamicButtonTypes);
document.addEventListener('DOMContentLoaded', init);
document.addEventListener('DOMContentLoaded', updateScrollTopButton);
window.addEventListener('scroll', updateScrollTopButton, { passive: true });
